window.aulaBook=[{"id":"book-o01","title":"L’alfabet","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"6–7","exercises":[{"id":"book-o01-ex1","number":"O1.1","title":"Llegiu en veu alta les sigles següents i escriviu-les.","type":"open","bodyHtml":"<p>TSJ: DGRN:<br>LPH: ME:<br>CF: LCX:</p>","sourcePage":6,"pdfPage":3,"solutionHtml":"<p>TSJ: te essa jota DGRN: de ge erra ena<br>LPH: ela pe hac ME: ema e<br>CF: ce efa LCX: ela ce ix/xeix</p>","book":true,"prompt":"","explanation":""},{"id":"book-o01-ex2","number":"O1.2","title":"Ordeneu alfabèticament les paraules de cada un dels grups següents.","type":"open","bodyHtml":"<p>1. brut, zebra, home:<br>2. jutge, jutjat, jutgessa:</p><p>3. loció, laberint, llop:<br>4. xàfec, fàbrica, gàbia:<br>5. cullera, cavall, crosta:<br>6. ordinador, ordre, ordenació:</p>","sourcePage":6,"pdfPage":3,"solutionHtml":"<p>1. brut, home, zebra 3. laberint, llop, loció 5. cavall, crosta, cullera<br>2. jutge, jutgessa, jutjat 4. fàbrica, gàbia, xàfec 6. ordenació, ordinador, ordre</p>","book":true,"prompt":"","explanation":""},{"id":"book-o01-ex3","number":"O1.3","title":"Ordeneu alfabèticament els aliments següents i indiqueu quins tres no són vegetals.","type":"open","bodyHtml":"<p>julivert, mongeta, cogombre, albercoc, lluç, espàrrec, síndria, tomàquet, escopinya,<br>pastanaga, préssec, pruna, taronja, magrana, pebrot, cloïssa, alvocat, bledes</p><p>1. 7. 13.<br>2. 8. 14.<br>3. 9. 15.<br>4. 10. 16.<br>5. 11. 17.<br>6. 12. 18.</p><p>No són vegetals:</p>","sourcePage":7,"pdfPage":4,"solutionHtml":"<p>1. albercoc 4. cloïssa 7. espàrrec 10. magrana 13. pebrot 16. síndria<br>2. alvocat 5. cogombre 8. julivert 11. mongeta 14. préssec 17. taronja<br>3. bledes 6. escopinya 9. lluç 12. pastanaga 15. pruna 18. tomàquet<br>No són vegetals: cloïssa, escopinya, lluç</p>","book":true,"prompt":"","explanation":""},{"id":"book-o01-ex4","number":"O1.4","title":"Ordeneu alfabèticament els termes següents i indiqueu quins tres no són termes jurídics.","type":"open","bodyHtml":"<p>sentència, desnonament, atestat, nyanyo, plet, interlocutòria, drapaire, bestreta,<br>acarament, masover, provisió, testimoni, vistiplau, maltractament, altressí</p><p>1. 6. 11.<br>2. 7. 12.<br>3. 8. 13.<br>4. 9. 14.<br>5. 10. 15.</p><p>No són termes jurídics:</p>","sourcePage":7,"pdfPage":4,"solutionHtml":"<p>1. acarament 4. bestreta 7. interlocutòria 10. nyanyo 13. sentència<br>2. altressí 5. desnonament 8. maltractament 11. plet 14. testimoni<br>3. atestat 6. drapaire 9. masover 12. provisió 15. vistiplau<br>No són termes jurídics: drapaire, masover, nyanyo</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 6–7 · <a href=\"assets/llibre-b2-ortografia.pdf#page=3\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>L’alfabet</h2><div class=\"table-wrap\"><table><thead><tr><th>Lletra</th><th>Nom</th><th>Sons i exemples</th></tr></thead><tbody><tr><td>a</td><td>a</td><td>degà, unitat; toga, partit</td></tr><tr><td>b</td><td>be alta</td><td>borsa, poble; club, dubte</td></tr><tr><td>c (ç)</td><td>ce (ce trencada)</td><td>camí, congrés, pòrtic; cessar, ciutat; llaços, vençut, capaç</td></tr><tr><td>d</td><td>de</td><td>decisió, adient; sud, fred</td></tr><tr><td>e</td><td>e</td><td>depèn, plec; tindré, fet; jutge, penal</td></tr><tr><td>f</td><td>efa</td><td>ferm, baf, cafè</td></tr><tr><td>g</td><td>ge</td><td>gabinet, guerra; gestió, gir; diàleg, mag</td></tr><tr><td>h</td><td>hac</td><td>Gairebé sempre és muda: hàbil, adhesió, hereu</td></tr><tr><td>i</td><td>i llatina</td><td>notari, invent; mai, feina; joia, iot</td></tr><tr><td>j</td><td>jota</td><td>jaqueta, jornal, jubilació</td></tr><tr><td>k</td><td>ca</td><td>karateka (en mots d’origen estranger)</td></tr><tr><td>l (l·l)</td><td>ela (ela geminada)</td><td>legal, pilot, futbol, il·lusió</td></tr><tr><td>m</td><td>ema</td><td>magistrat, comuniquem</td></tr><tr><td>n</td><td>ena</td><td>negoci, Anna</td></tr><tr><td>o</td><td>o</td><td>bloc, cosa; plom, amor; obrer, telèfon</td></tr><tr><td>p</td><td>pe</td><td>pertinença, cap</td></tr><tr><td>q</td><td>cu</td><td>quantia, queixa, requerir</td></tr><tr><td>r</td><td>erra</td><td>acarar, mare; raó, conreu; venir, lloguer</td></tr><tr><td>s</td><td>essa</td><td>sala, capsa, passar; crisi, asil, base</td></tr><tr><td>t</td><td>te</td><td>tribunal, nota, entrar, salut</td></tr><tr><td>u</td><td>u</td><td>únic, just; quatre, europeu; cauen, diuen</td></tr><tr><td>v</td><td>ve baixa</td><td>valor, faltava, vilatans</td></tr><tr><td>w</td><td>ve doble</td><td>whisky; watt (mots d’origen estranger)</td></tr><tr><td>x</td><td>ics o xeix</td><td>exemple, exèrcit; taxi, tòxic; xop, reixa</td></tr><tr><td>y</td><td>i grega</td><td>Amb la n, representa el so de n palatal: canya, puny, pinya</td></tr><tr><td>z</td><td>zeta</td><td>zona, horitzó, catorze</td></tr></tbody></table></div></section>","topicNumber":"01"},{"id":"book-o02","title":"La síl·laba","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"8–11","exercises":[{"id":"book-o02-ex1","number":"O2.1","title":"Separeu les síl·labes de les paraules següents i marqueu-ne la tònica.","type":"open","bodyHtml":"<p>ordinador: himne:<br>cortina: discos:<br>campana: cangur:<br>elefant: vacances:<br>jugador: electricista:<br>festa: atmosfera:</p>","sourcePage":10,"pdfPage":7,"solutionHtml":"<p>or-di-na-<u>dor</u> e-le-<u>fant</u> <u>him</u>-ne va-<u>can</u>-ces<br>cor-<u>ti</u>-na ju-ga-<u>dor</u> <u>dis</u>-cos e-lec-tri-<u>cis</u>-ta<br>cam-<u>pa</u>-na <u>fes</u>-ta can-<u>gur</u> at-mos-<u>fe</u>-ra</p>","book":true,"prompt":"","explanation":""},{"id":"book-o02-ex2","number":"O2.2","title":"Separeu les síl·labes de les paraules següents i digueu quantes síl·labes té cadascuna.","type":"open","bodyHtml":"<p><em>treure</em> <u><em>t</em><em>r</em><em>e</em><em>u</em><em>-</em><em>r</em><em>e</em></u> <u><em>2</em></u> estudiant<br>Andreu relació<br>feina heroi<br>piano frau<br>grua poesia<br>tauleta cuiner</p>","sourcePage":10,"pdfPage":7,"solutionHtml":"<p><u><em>t</em><em>r</em><em>e</em><em>u</em><em>-</em><em>r</em><em>e</em></u> <u><em>2</em></u> <u>pi-a-no</u> <u>3</u> <u>es-tu-di-ant</u> <u>4</u> <u>frau</u> <u>1</u><br><u>An-dreu</u> <u>2</u> <u>gru-a</u> <u>2</u> <u>re-la-ci-ó</u> <u>4</u> <u>po-e-si-a</u> <u>4</u><br><u>fei-na</u> <u>2</u> <u>tau-le-ta</u> <u>3</u> <u>he-roi</u> <u>2</u> <u>cui-ner</u> <u>2</u></p>","book":true,"prompt":"","explanation":""},{"id":"book-o02-ex3","number":"O2.3","title":"Separeu les síl·labes de les paraules següents i digueu quantes síl·labes té cadascuna.","type":"open","bodyHtml":"<p><em>ingènua</em> <u><em>i</em><em>n</em><em>-</em><em>g</em><em>è</em><em>-</em><em>n</em><em>u</em><em>-</em><em>a</em></u> <u><em>4</em></u> quantitat<br>caure rei<br>retreure freqüència<br>almoina sentència<br>paraigua triar<br>solució guardiola</p>","sourcePage":10,"pdfPage":7,"solutionHtml":"<p><u><em>i</em><em>n</em><em>-</em><em>g</em><em>è</em><em>-</em><em>n</em><em>u</em><em>-</em><em>a</em></u> <u><em>4</em></u> <u>al-moi-na</u> <u>3</u> <u>quan-ti-tat</u> <u>3</u> <u>sen-tèn-ci-a</u> <u>4</u><br><u>cau-re</u> <u>2</u> <u>pa-rai-gua</u> <u>3</u> <u>rei</u> <u>1</u> <u>tri-ar</u> <u>2</u><br><u>re-treu-re</u> <u>3</u> <u>so-lu-ci-ó</u> <u>4</u> <u>fre-qüèn-ci-a</u> <u>4</u> <u>guar-di-o-la</u> <u>4</u></p>","book":true,"prompt":"","explanation":""},{"id":"book-o02-ex4","number":"O2.4","title":"Encercleu els diftongs de les paraules següents i distribuïu-les a la columna corresponent.","type":"open","bodyHtml":"<p>riure, guardar, lleó, teatre, llaurar, campió, enlaire, seure, sandàlia, idea, avui, cinquanta,<br>cua, clienta, llengües, votació, diem, farmàcia, boira, aleatòria</p><p><u>amb</u> <u>diftong</u> <u>decreixent</u> <u>amb</u> <u>diftong</u> <u>creixent</u> <u>no</u> <u>hi</u> <u>ha</u> <u>diftong</u></p>","sourcePage":10,"pdfPage":7,"solutionHtml":"<p>Amb diftong decreixent: r<u>iu</u>re, ll<u>au</u>rar, enl<u>ai</u>re, s<u>eu</u>re, av<u>ui</u>, b<u>oi</u>ra<br>Amb diftong creixent: g<u>ua</u>rdar, cinq<u>ua</u>nta, lleng<u>üe</u>s<br>No hi ha diftong: lleó, teatre, campió, sandàlia, idea, cua, clienta, votació, diem, farmàcia, aleatòria</p>","book":true,"prompt":"","explanation":""},{"id":"book-o02-ex5","number":"O2.5","title":"Separeu les síl·labes d’aquestes paraules i marqueu-ne la tònica.","type":"open","bodyHtml":"<p>xemeneia: pacient:<br>ianqui: veia:<br>claraboia: quota:</p><p>aigüera: iaia:<br>creueu: qualificació:<br>meandre: joia:</p>","sourcePage":10,"pdfPage":7,"solutionHtml":"<p>xe-me-<u>ne</u>-ia ai-<u>güe</u>-ra pa-ci-<u>ent</u> <u>ia</u>-ia<br><u>ian</u>-qui cre-<u>ueu</u> <u>ve</u>-ia qua-li-fi-ca-ci-<u>ó</u><br>cla-ra-<u>bo</u>-ia me-<u>an</u>-dre <u>quo</u>-ta <u>jo</u>-ia</p>","book":true,"prompt":"","explanation":""},{"id":"book-o02-ex6","number":"O2.6","title":"Separeu les síl·labes d’aquestes paraules i marqueu-ne la tònica.","type":"open","bodyHtml":"<p>iogurt: caieu:<br>raucar: dormiu:<br>diccionari: reedició:<br>biblioteca: cauen:<br>enquadernació: quaranta:<br>tancàveu: fluorescent:</p>","sourcePage":11,"pdfPage":8,"solutionHtml":"<p>io-<u>gurt</u> bi-bli-o-<u>te</u>-ca ca-<u>ieu</u> <u>ca</u>-uen<br>rau-<u>car</u> en-qua-der-na-ci-<u>ó</u> dor-<u>miu</u> qua-<u>ran</u>-ta<br>dic-ci-o-<u>na</u>-ri tan-<u>cà</u>-veu re-e-di-ci-<u>ó</u> flu-o-res-<u>cent</u></p>","book":true,"prompt":"","explanation":""},{"id":"book-o02-ex7","number":"O2.7","title":"Escriviu les paraules següents, amb les síl·labes separades, a la columna corresponent.","type":"open","bodyHtml":"<p>brotxa, salsitxa, fuet, destral, vedella, mànega, albergínia, llonganissa, coliflor, serra,<br>enciam, endívia, tenalles, botifarra, martell, fonoll, carbassó, xai</p><p><u>de</u> <u>la</u> <u>ferreteria</u> <u>de</u> <u>la</u> <u>carnisseria</u> <u>de</u> <u>la</u> <u>verduleria</u></p>","sourcePage":11,"pdfPage":8,"solutionHtml":"<p>De la ferreteria: brot-xa, des-tral, mà-ne-ga, ser-ra, te-na-lles, mar-tell<br>De la carnisseria: sal-sit-xa, fu-et, ve-de-lla, llon-ga-nis-sa, bo-ti-far-ra, xai<br>De la verduleria: al-ber-gí-ni-a, col-i-flor, en-ci-am, en-dí-vi-a, fo-noll, car-bas-só</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 8–11 · <a href=\"assets/llibre-b2-ortografia.pdf#page=5\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>LA SÍL·LABA</h3><p>Una síl·laba és un so o un conjunt de sons que pronunciem d’un sol cop de veu. Perquè hi hagi una síl·laba<br>és imprescindible la presència d’una vocal, que n’és el nucli. Els mots que només tenen una síl·laba<br>s’anomenen monosíl·labs.</p><p>llet<br>pera: pe-ra<br>aprendre: a-pren-dre<br>estomacar: es-to-ma-car</p><p>Totes les paraules, excepte alguns monosíl·labs (<em>per</em>, <em>ho</em>, <em>en</em>, <em>les</em>, <em>li</em>, <em>que</em>...), tenen una síl·laba tònica, que<br>és la que es pronuncia amb més força que les altres, anomenades àtones.</p><p>camisa: ca-<em>mi</em>-sa ordinador: or-di-na-<em>dor</em></p><h3>Els diftongs</h3><p>Dues vocals formen un diftong quan es pronuncien en una mateixa síl·laba, en el mateix cop de veu. Perquè<br>hi hagi un diftong cal que una de les vocals de la combinació sigui sempre una <em>i</em> o bé una <em>u</em> àtones i que<br>aquesta vocal ocupi una posició determinada. A més, encara que en la combinació hi hagi una i o bé una u,<br>no sempre hi ha diftong, perquè també és determinant el lloc en què es troben aquestes vocals.</p><p>reina: r<em>ei</em>-na història: his-tò-ri-a Eulàlia: <em>Eu</em>-là-li-a mouen: mo-<em>ue</em>n<br>quatre: q<em>ua</em>-tre coure: c<em>ou</em>-re suor: su-or maia: ma-<em>ia</em></p><p>En català tenim els diftongs següents:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>Decreixents</u></td><td colspan=\"1\" rowspan=\"1\"><u>Quan</u> <u>la</u> <u><em>i</em></u> <u>i</u> <u>la</u> <u><em>u</em></u> <u>estan</u> <u>situades</u> <u>al</u> <u>darrere</u><br><u>d’una</u> <u>altra</u> <u>vocal.</u></td><td colspan=\"1\" rowspan=\"1\"><em>ai</em>: <em>ai</em>-re <em>au</em>: pa-l<em>au</em><br><em>ei</em>: f<em>ei</em>-na <em>eu</em>: cr<em>eu</em>-re<br><em>oi</em>: n<em>oi</em> <em>iu</em>: v<em>iu</em>-re<br><em>ui</em>: c<em>ui</em>-na <u><em>o</em><em>u</em>:</u> <u>m<em>o</em><em>u</em>-re</u></td></tr><tr><td colspan=\"1\" rowspan=\"3\"><u>Creixents</u></td><td colspan=\"1\" rowspan=\"1\"><u>Quan</u> <u>la</u> <u><em>u</em></u> <u>va</u> <u>precedida</u> <u>de</u> <u><em>g</em></u> <u>o</u> <u><em>q</em>.</u></td><td colspan=\"1\" rowspan=\"1\"><em>gua</em>: a-g<em>ua</em>n-tar <em>qua</em>: q<em>ua</em>-li-tat<br><em>güe</em>: <em>ai</em>-g<em>üe</em>-ra <em>qüe</em>: de-lin-q<em>üe</em>nt<br><em>güi</em>: pin-g<em>üí</em> <em>qüi</em>: a-q<em>üi</em>-cul-tu-ra<br><em>guo</em>: pa-rai-g<em>uo</em>t <em>quo</em>: q<em>uo</em>-ti-di-à</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u><em>i</em></u> <u>/</u> <u><em>u</em></u> <u>+</u> <u>vocal</u> <u>a</u> <u>inici</u> <u>de</u> <u>mot</u></td><td colspan=\"1\" rowspan=\"1\"><em>io</em>t <em>io-</em>gurt<br><em>iu</em>-gos-lau <em>io</em>-de<br>h<em>ie</em>-na<br><em>ua</em>-ca-ri</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>vocal</u> <u>+</u> <u><em>i</em></u> <u>/</u> <u><em>u</em></u> <u>+</u> <u>vocal</u></td><td colspan=\"1\" rowspan=\"1\">fe-<em>ia</em> cre-<em>ua</em>r<br>dè-<em>ie</em>m be-<em>ue</em>n<br>no-<em>ia</em> ni-<em>ua</em>-da<br>La-<em>ia</em> mo-<em>ue</em>n</td></tr></tbody></table></div><p><em>Remarques</em></p><p><em>a</em>) Només les combinacions anteriors formen diftong i, per tant, no es poden separar en síl·labes diferents.<br>En canvi, sí que separem, per exemple:</p><p>Ma-r<em>i</em>-<em>a</em> c<em>u</em>-<em>a</em><br>J<em>o</em>-<em>a</em>n t<em>e</em>-<em>a</em>-tre<br>ac-t<em>u</em>-<em>a</em>-c<em>i</em>-<em>ó</em> c<em>i</em>-<em>è</em>n-c<em>i</em>-<em>a</em></p><p><em>b</em>) No posem dièresi en els grups <em>gua</em>, <em>qua</em>, <em>guo</em>, <em>quo</em>, perquè no cal indicar que la <em>u</em> es pronuncia.</p><p><em>c</em>) En alguns casos trobem també la combinació de tres vocals en una sola síl·laba. Aquestes combinacions<br>s’anomenen triftongs.</p><p>Pa-ra-g<em>uai</em>, g<em>uai</em>-tar, Al-g<em>uai</em>-re, fè-<em>ieu</em>, dú-<em>ieu</em>, cre-<em>ueu</em></p><h3>La separació de síl·labes a efectes ortogràfics</h3><p>Quan hem de partir una paraula perquè no cap sencera a la mateixa línia, cal tenir en compte els dígrafs,<br>conjunts de lletres que formen el so d’una consonant.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"3\"><u>Dígrafs</u> <u>que</u> <u>no</u> <u>podem</u> <u>separar</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>g</em><em>u</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"3\">a-con-se-<em>gu</em>ir<br>ro-<em>qu</em>es<br>ca-va-<em>ll</em>er</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>n</em><em>y</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"3\">pi-<em>ny</em>a<br>re-bu<em>ig</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>q</em><em>u</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>i</em><em>g</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><em>ll</em></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"3\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"5\"><u>Dígrafs</u> <u>que</u> <u>hem</u> <u>de</u> <u>separar</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>r</em><em>r</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"5\">ca<em>r</em>-<em>r</em>o<br>a<em>s</em>-<em>c</em>en-sor<br>co<em>t</em>-<em>x</em>e<br>fe<em>t</em>-<em>g</em>e<br>ca<em>i</em>-<em>x</em>a</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>s</em><em>s</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"5\">ta<em>s</em>-<em>s</em>a<br>ti<em>l</em>-<em>l</em>a<br>na<em>t</em>-<em>j</em>a<br>se<em>t</em>-<em>z</em>e</td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>s</em><em>c</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>l</em><em>·</em><em>l</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>t</em><em>x</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>t</em><em>j</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>t</em><em>g</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>t</em><em>z</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><em>ix</em></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div><p>En mots tipus <em>caixa</em>, <em>cuixa</em> o <em>reixa</em>, el grup <em>ix</em> representa un únic so (és a dir, funciona com a dígraf) a la<br>major part del domini lingüístic, però, en canvi, representa dos sons a la major part del català occidental<br>perquè la <em>i</em> es pronuncia.</p><p>A banda dels dígrafs, també hem de tenir en compte que en els mots compostos hem de destriar quins són<br>els elements que els integren.</p><p>in-ter-ur-bà, trans-at-làn-tic, in-hu-mà, cel-o-bert, vos-al-tres</p><p>Finalment, també hem de tenir present que a final o a inici de ratlla no podem deixar mai una lletra tota<br>sola. Per tant, és incorrecte fer les separacions següents al final d’una línia:</p><p>farmàci-a, d’-altres, l’-oli, a-nell, o-bligació</p></section>","topicNumber":"02"},{"id":"book-o03","title":"Les vocals A/E àtones","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"12–16","exercises":[{"id":"book-o03-ex1","number":"O3.1","title":"Subratlleu les vocals a/e àtones del paràgraf següent.","type":"open","bodyHtml":"<p>No sempre és cert que la vida s’espatlla fent-la servir. De vegades s’espatlla de no fer-la servir,<br>precisament.<br>Vicenç Villatoro, <em>Tenim</em> <em>un</em> <em>nom</em></p>","sourcePage":14,"pdfPage":11,"solutionHtml":"<p>No sempr<u>e</u> és cert qu<u>e</u> l<u>a</u> vid<u>a</u> s’<u>e</u>spatll<u>a</u> fent-l<u>a</u> s<u>e</u>rvir. D<u>e</u> v<u>e</u>gad<u>e</u>s s’<u>e</u>spatll<u>a</u> d<u>e</u> no fer-l<u>a</u> s<u>e</u>rvir, pr<u>e</u>cis<u>a</u>ment.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o03-ex2","number":"O3.2","title":"Completeu els substantius següents amb la vocal corresponent.","type":"open","bodyHtml":"<p>sostr__ pollastr__ sastr__ deut__ orf__<br>bestret__ colz__ el__ vespr__ Assumpt__<br>turism__ tard__ monstr__ titell__ fallid__<br>aixet__ act__ assumpt__ coratg__ pebr__</p>","sourcePage":14,"pdfPage":11,"solutionHtml":"<p>sostr<strong>e</strong> pollastr<strong>e</strong> sastr<strong>e</strong> deut<strong>e</strong> orf<strong>e</strong><br>bestret<strong>a</strong> colz<strong>e</strong> el<strong>a</strong> vespr<strong>e</strong> Assumpt<strong>a</strong><br>turism<strong>e</strong> tard<strong>a</strong> monstr<strong>e</strong> titell<strong>a</strong> fallid<strong>a</strong><br>aixet<strong>a</strong> act<strong>a</strong>/act<strong>e</strong> assumpt<strong>e</strong> coratg<strong>e</strong> pebr<strong>e</strong></p>","book":true,"prompt":"","explanation":""},{"id":"book-o03-ex3","number":"O3.3","title":"Completeu aquests adjectius amb la vocal corresponent i escriviu el plural dels sintagmes.","type":"open","bodyHtml":"<p>vaca jov__: closca negr__:<br>granja pobr__: aigua agr__:<br>tortuga salvatg__: plaça alegr__:<br>monja xerrair__: platja enorm__:<br>butaca còmod__: llengua rect__:<br>esperança febl__: truja golafr__:</p>","sourcePage":15,"pdfPage":12,"solutionHtml":"<p>vaca jov<strong>e</strong>: vaques joves closca negr<strong>a</strong>: closques negres<br>granja pobr<strong>a</strong>: granges pobres aigua agr<strong>a</strong>: aigües agres<br>tortuga salvatg<strong>e</strong>: tortugues salvatges plaça alegr<strong>e</strong>: places alegres<br>monja xerrair<strong>e</strong>: monges xerraires platja enorm<strong>e</strong>: platges enormes<br>butaca còmod<strong>a</strong>: butaques còmodes llengua rect<strong>a</strong>: llengües rectes<br>esperança febl<strong>e</strong>: esperances febles truja golafr<strong>e</strong>: truges golafres</p>","book":true,"prompt":"","explanation":""},{"id":"book-o03-ex4","number":"O3.4","title":"Completeu les frases següents amb la vocal corresponent i escriviu-ne el plural.","type":"open","bodyHtml":"<p>1. El diari amag__ la imatg__ més tendr__ de la notíci__ i en destac__ la més trist__ i terribl__.</p><p>2. La mestress__ passej__ a prop de la rier__ fresc__ acompanyada d’una goss__ ferotg__.</p><p>3. M’agradari__ ser jutg__ de pau pel que represent__ i no pel que jutj__.</p><p>4. La barc__ pirat__ pleg__ la vel__ perquè no desitj__ una altr__ derrot__.</p>","sourcePage":15,"pdfPage":12,"solutionHtml":"<p>1. El diari amag<strong>a</strong> la imatg<strong>e</strong> més tendr<strong>a</strong> de la notíci<strong>a</strong> i en destac<strong>a</strong> la més trist<strong>a</strong> i terribl<strong>e</strong>.<br>Els diaris amaguen les imatges més tendres de les notícies i en destaquen les més tristes i terribles.<br>2. La mestress<strong>a</strong> passej<strong>a</strong> a prop de la rier<strong>a</strong> fresc<strong>a</strong> acompanyada d’una goss<strong>a</strong> ferotg<strong>e</strong>.<br>Les mestresses passegen a prop de les rieres fresques acompanyades d’unes gosses ferotges.<br>3. M’agradari<strong>a</strong> ser jutg<strong>e</strong> de pau pel que represent<strong>a</strong> i no pel que jutj<strong>a</strong>.<br>Ens agradaria ser jutges de pau pel que representen i no pel que jutgen.<br>4. La barc<strong>a</strong> pirat<strong>a</strong> pleg<strong>a</strong> la vel<strong>a</strong> perquè no desitj<strong>a</strong> una altr<strong>a</strong> derrot<strong>a</strong>.<br>Les barques pirates pleguen les veles perquè no desitgen unes altres derrotes.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o03-ex5","number":"O3.5","title":"Escriviu el primitiu de cadascuna d’aquestes paraules derivades i, tot seguit, completeu-les amb la vocal corresponent.","type":"open","bodyHtml":"<p>______________: cav__ller ______________: p__drera ______________: bol__taire<br>______________: cull__rada ______________: sacs__jar ______________: v__rdet<br>______________: bad__llar ______________: dav__nter ______________: merav__llar<br>______________: engr__ixar ______________: cap__llà ______________: quar__ntena<br>______________: emp__rar ______________: c__ndrer ______________: endarr__rir<br>______________: fr__dolic ______________: at__rrar ______________: rasp__llar</p>","sourcePage":15,"pdfPage":12,"solutionHtml":"<p>cavall: cav<strong>a</strong>ller pedra: p<strong>e</strong>drera bolet: bol<strong>e</strong>taire<br>cullera: cull<strong>e</strong>rada sacseig: sacs<strong>e</strong>jar verd: v<strong>e</strong>rdet<br>badall: bad<strong>a</strong>llar davant: dav<strong>a</strong>nter meravella: merav<strong>e</strong>llar<br>greix: engr<strong>e</strong>ixar capella: cap<strong>e</strong>llà quaranta: quar<strong>a</strong>ntena<br>empara: emp<strong>a</strong>rar cendra: c<strong>e</strong>ndrer darrer: endarr<strong>e</strong>rir<br>fred: fr<strong>e</strong>dolic terra: at<strong>e</strong>rrar raspall: rasp<strong>a</strong>llar</p>","book":true,"prompt":"","explanation":""},{"id":"book-o03-ex6","number":"O3.6","title":"Completeu la taula següent.","type":"open","bodyHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>cantes</u></td><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>cantava</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>ha</u> <u>cantat</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>fer</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>treure</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>saber</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>començar</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>néixer</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>embolicar</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div>","sourcePage":15,"pdfPage":12,"solutionHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>fas</u></td><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>feia</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>ha</u> <u>fet</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>treus</u></td><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>treia</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>ha</u> <u>tret</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>saps</u></td><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>sabia</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>ha</u> <u>sabut</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>comences</u></td><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>començava</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>ha</u> <u>començat</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>neixes/naixes</u></td><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>naixia</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>ha</u> <u>nascut</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>emboliques</u></td><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>embolicava</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>ha</u> <u>embolicat</u></td></tr></tbody></table></div>","book":true,"prompt":"","explanation":""},{"id":"book-o03-ex7","number":"O3.7","title":"Completeu les frases següents amb a/e segons correspongui.","type":"open","bodyHtml":"<p>1. El mestr__ vol fer class__ en aquella aula tan ampl__ del final del pass__dís.<br>2. No m’agrad__ el pastís d’espàrr__cs. El trobo massa agr__ per al meu gust.<br>3. El profet__ és molt amabl__ , però és incapaç de rep__rar l’av__ria de la llum.<br>4. En aquest pobl__ __mpordanès fei__ temps que no hi n__ixia cap nen.</p><p>5. El jutge va __valuar la capacitat m__ntal de la insign__ ass__ssina del Raval.<br>6. Em sentia des__mparat enmig d’aquella ass__mblea d’estudiants anarquistes.<br>7. Si vols viur__ al nostr__ mon__stir t’hauràs d’af__itar cada dia.<br>8. L’Estev__ va quedar orf__ de petit perquè els seus pares van morir de pest__ negr__.<br>9. Vin__ amb mi al m__rcat a encom__nar els alb__rcocs de les postr__s.</p>","sourcePage":15,"pdfPage":12,"solutionHtml":"<p>1. El mestr<strong>e</strong> vol fer class<strong>e</strong> en aquella aula tan ampl<strong>a</strong> del final del pass<strong>a</strong>dís.<br>2. No m’agrad<strong>a</strong> el pastís d’espàrr<strong>e</strong>cs. El trobo massa agr<strong>e</strong> per al meu gust.<br>3. El profet<strong>a</strong> és molt amabl<strong>e</strong>, però és incapaç de rep<strong>a</strong>rar l’av<strong>a</strong>ria de la llum.<br>4. En aquest pobl<strong>e</strong> <strong>e</strong>mpordanès fei<strong>a</strong> temps que no hi n<strong>a</strong>ixia cap nen.<br>5. El jutge va <strong>a</strong>valuar la capacitat m<strong>e</strong>ntal de la insign<strong>e</strong> ass<strong>a</strong>ssina del Raval.<br>6. Em sentia des<strong>e</strong>mparat enmig d’aquella ass<strong>e</strong>mblea d’estudiants anarquistes.<br>7. Si vols viur<strong>e</strong> al nostr<strong>e</strong> mon<strong>e</strong>stir t’hauràs d’af<strong>a</strong>itar cada dia.<br>8. L’Estev<strong>e</strong> va quedar orf<strong>e</strong> de petit perquè els seus pares van morir de pest<strong>a</strong> negr<strong>a</strong>.<br>9. Vin<strong>e</strong> amb mi al m<strong>e</strong>rcat a encom<strong>a</strong>nar els alb<strong>e</strong>rcocs de les postr<strong>e</strong>s.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o03-ex8","number":"O3.8","title":"Completeu el text següent amb a/e segons calgui.","type":"open","bodyHtml":"<p>La cambrera, jov__ i alegr__, les segueix amb la vista, humiliada per la propina un pèl<br>excessiva. No li agrad__n les don__s que paguen. Les veu que pug__n en un cotxe bo i que<br>sembla còmod__, aparcat just a sota el senyal de prohibit estacionar-hi, a l’altr__ banda del<br>carrer. Quan la Roser hi puja, la pobr__ cambrera juraria que li ha vist les calc__s. El cotxe es<br>perd de vista per l’ampl__ passeig. Fa una tard__ molt quieta i l’aire té un gust dolç.</p><p>Maria Mercè Roca, <em>Cames</em> <em>de</em> <em>seda</em> (text adaptat)</p>","sourcePage":16,"pdfPage":13,"solutionHtml":"<p>La cambrera, jov<strong>e</strong> i alegr<strong>e</strong>, les segueix amb la vista, humiliada per la propina un pèl excessiva. No li agrad<strong>e</strong>n les don<strong>e</strong>s<br>que paguen. Les veu que pug<strong>e</strong>n en un cotxe bo i que sembla còmod<strong>e</strong>, aparcat just a sota el senyal de prohibit estacionar-<br>hi, a l’altr<strong>a</strong> banda del carrer. Quan la Roser hi puja, la pobr<strong>a</strong> cambrera juraria que li ha vist les calc<strong>e</strong>s. El cotxe es perd<br>de vista per l’ampl<strong>e</strong> passeig. Fa una tard<strong>a</strong> molt quieta i l’aire té un gust dolç.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o03-ex9","number":"O3.9","title":"Completeu aquest text amb a/e segons correspongui.","type":"open","bodyHtml":"<p>Una investigació ha provat que les dones que pren__n supl__ments amb àcid omega 3 durant<br>l’embaràs ten__n n__dons amb menys símptomes de refr__dats i que, a més, pateix__n<br>malalties de menys duració. Les criatures object__ de l’estudi van ser __valuades al cap d’un,<br>de tres i de sis mesos després d’haver n__scut. D’altr__ banda, les mares van respondr__ a un<br>qüestionari sobr__ la salut dels seus fills i dui__n un dietari per controlar l’estat de salut dels<br>m__nuts.</p>","sourcePage":16,"pdfPage":13,"solutionHtml":"<p>Una investigació ha provat que les dones que pren<strong>e</strong>n supl<strong>e</strong>ments amb àcid omega 3 durant l’embaràs ten<strong>e</strong>n n<strong>a</strong>dons amb<br>menys símptomes de refr<strong>e</strong>dats i que, a més, pateix<strong>e</strong>n malalties de menys duració. Les criatures object<strong>e</strong> de l’estudi van<br>ser <strong>a</strong>valuades al cap d’un, de tres i de sis mesos després d’haver n<strong>a</strong>scut. D’altr<strong>a</strong> banda, les mares van respondr<strong>e</strong> a un<br>qüestionari sobr<strong>e</strong> la salut dels seus fills i dui<strong>e</strong>n un dietari per controlar l’estat de salut dels m<strong>e</strong>nuts.</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 12–16 · <a href=\"assets/llibre-b2-ortografia.pdf#page=9\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>LES VOCALS A/E ÀTONES</h3><p>En català oriental les lletres <em>a</em> i <em>e</em> en posició àtona tenen el mateix so, el de vocal neutra, la qual cosa<br>provoca dubtes ortogràfics.</p><p>galt<em>a</em>, map<em>a</em>, m<em>a</em>duixot, comunic<em>a</em><br>Jaum<em>e</em>, torr<em>e</em>, v<em>e</em>nim, tisor<em>e</em>s, dormí<em>e</em>m</p><h3>A/E àtones en l’acabament de substantius i adjectius</h3><p>La norma general per escriure la vocal neutra en aquesta posició és la següent:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>mots</u> <u>masculins</u> <u>acaben</u> <u>en</u> <u>-<em>e</em>.</u></td><td colspan=\"1\" rowspan=\"1\">alcald<em>e</em>, pobl<em>e</em>, Per<em>e</em>, Jaum<em>e</em><br>tendr<em>e</em>, direct<em>e</em>, esquerr<em>e</em>, ampl<em>e</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>mots</u> <u>femenins</u> <u>acaben</u> <u>en</u> <u>-<em>a</em>.</u></td><td colspan=\"1\" rowspan=\"1\">port<em>a</em>, taul<em>a</em>, Marion<em>a</em>, tard<em>a</em><br>noms de lletra: ef<em>a</em>, em<em>a</em>, ess<em>a</em><br>tendr<em>a</em>, direct<em>a</em>, esquerr<em>a</em>, ampl<em>a</em></td></tr></tbody></table></div><p>Hi ha alguns substantius, però, que no segueixen la regla general; és a dir, són mots masculins que acaben<br>en -<em>a</em> i mots femenins que acaben en -<em>e</em>.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"2\"><u>Masculins</u> <u>que</u><br><u>acaben</u> <u>en</u> <u>-<em>a</em></u></td><td colspan=\"3\" rowspan=\"1\"><u>Les</u> <u>terminacions</u></td><td colspan=\"1\" rowspan=\"1\">-<em>arca</em>: mon<em>arca</em>, patri<em>arca</em><br>-<em>cida</em>: homi<em>cida</em>, insecti<em>cida</em><br>-<em>ista</em>: art<em>ista</em>, cicl<em>ista</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\">A</td><td colspan=\"1\" rowspan=\"1\">Altres</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">goril·l<em>a</em>, iog<em>a</em>, titell<em>a</em>, paraigu<em>a</em></td></tr><tr><td colspan=\"1\" rowspan=\"2\"><u>Femenins</u> <u>que</u><br><u>acaben</u> <u>en</u> <u>-<em>e</em></u></td><td colspan=\"3\" rowspan=\"1\"><u>Les</u> <u>terminacions</u></td><td colspan=\"1\" rowspan=\"1\">-<em>aire</em>: cant<em>aire</em>, escombri<em>aire</em><br>-<em>ble</em>: compta<em>ble</em>, do<em>ble</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\">A</td><td colspan=\"1\" rowspan=\"1\">Altres</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">febr<em>e</em>, llebr<em>e</em>, mar<em>e</em>, Carm<em>e</em>, class<em>e</em>, espèci<em>e</em>, sèri<em>e</em></td></tr></tbody></table></div><p>Pel que fa als adjectius, poden ser de dues terminacions o d’una. Els primers tenen una forma per al masculí<br>i una per al femení. En canvi, els d’una terminació tenen la mateixa forma per al masculí i per al femení.</p><p>un pèsol tendr<em>e</em> / una mongeta tendr<em>a</em> un oncle jov<em>e</em> / una tia jov<em>e</em><br>el braç esquerr<em>e</em> / la mà esquerr<em>a</em> un monarca pers<em>a</em> / una reina pers<em>a</em></p><p>En general, els adjectius que en català són d’una o de dues terminacions coincideixen amb el castellà. Cal<br>anar amb compte, però, amb els adjectius següents, ja que aquests difereixen del castellà:</p><p>un país pobr<em>e</em> / una nació pobr<em>a</em><br>un xicot rud<em>e</em> / una noia rud<em>e</em></p><p>Tots els substantius i adjectius, encara que en singular acabin en -<em>a</em>, fan el plural en -<em>es</em>.</p><p>alcald<em>e</em> alcald<em>es</em> tendr<em>e</em> tendr<em>es</em><br>tard<em>a</em> tard<em>es</em> tendr<em>a</em> tendr<em>es</em></p><p>La formació del plural en -<em>es</em> comporta els canvis ortogràfics següents:</p><p>-ca  -ques vaca  va<em>ques</em> -ja  -ges esponja  espon<em>ges</em><br>-ça  -ces plaça  pla<em>ces</em> -ga  -gues mànega  màne<em>gues</em><br>-qua  -qües pasqua  pas<em>qües</em> -gua  -gües aigua  ai<em>gües</em></p><h3>A/E àtones en l’acabament de verbs</h3><p>La regla general diu el següent:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\">S</td><td colspan=\"1\" rowspan=\"1\">Si la vocal neutra és l’última lletra, hi escrivim <em>a</em>.</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">veni<em>a</em>, anav<em>a</em>, cant<em>a</em>, dei<em>a</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\">S</td><td colspan=\"1\" rowspan=\"1\">Si la vocal neutra és la penúltima lletra, hi escrivim <em>e</em>.</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">veni<em>e</em>n, anav<em>e</em>s, cant<em>e</em>s, dèi<em>e</em>u</td></tr></tbody></table></div><p>El fet que calgui escriure una <em>e</em> quan la vocal neutra és la penúltima lletra comporta els canvis ortogràfics<br>següents:</p><p>toca to<em>ques</em>, to<em>quen</em> jutja ju<em>tges</em>, ju<em>tgen</em><br>comença comen<em>ces</em>, comen<em>cen</em> prega pre<em>gues</em>, pre<em>guen</em><br>adequa ade<em>qües</em>, ade<em>qüen</em> enaigua enai<em>gü</em>es, enai<em>gü</em>en</p><p>Hi ha alguns mots, però, que no segueixen aquesta regla. Escrivim <em>e</em> en posició final en aquests casos:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\">E</td><td colspan=\"1\" rowspan=\"1\">Els infinitius dels verbs de la 2a conjugació: veur<em>e</em>, prendr<em>e</em>, riur<em>e</em>, caur<em>e</em></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"2\"><u>L</u></td><td colspan=\"1\" rowspan=\"1\"><u>Les</u> <u>quatre</u> <u>formes</u> <u>verbals</u> <u>següents:</u> <u>corr<em>e</em>,</u> <u>vin<em>e</em>,</u> <u>obr<em>e</em></u> <u>i</u> <u>ompl<em>e</em></u></td><td colspan=\"1\" rowspan=\"2\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\">Corr<em>e</em>, vin<em>e</em>! Obr<em>e</em> l’aixeta i ompl<em>e</em> el got.</td></tr></tbody></table></div><h3>A/E àtones en l’arrel dels mots</h3><p>Disposem de diferents recursos per saber com cal escriure la vocal neutra en aquesta posició.</p><p>1. Buscar el primitiu de la paraula, o una paraula de la família, en què aquest so sigui tònic.</p><p>t__ulada  t<em>a</em>ula  t<em>a</em>ulada bl__vós  bl<em>a</em>u  bl<em>a</em>vós<br>t__ulada  t<em>e</em>ula  t<em>e</em>ulada n__grós  n<em>e</em>gre  n<em>e</em>grós</p><p>Quan es tracta de verbs, cal buscar la 1a o la 3a persona del singular del present d’indicatiu.</p><p>recom__nem  recom<em>a</em>no  recom<em>a</em>nem af__itar  af<em>a</em>ita  af<em>a</em>itar</p><p>Cal anar amb compte, però, amb els verbs <em>jeure/jaure</em>, <em>néixer/nàixer</em> i <em>treure/traure</em>. En aquests verbs,<br>quan l’arrel és tònica, escriurem <em>a</em> o bé <em>e</em>, segons la vocal que pronunciem; quan l’arrel és àtona, escriurem<br>sempre <em>a</em>.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Síl·laba tònica</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Síl·laba àtona</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\">jeure<br>néixer<br><u>treure</u></td><td colspan=\"3\" rowspan=\"1\">j<em>e</em>c (o j<em>a</em>c), j<em>e</em>guis (o j<em>a</em>guis)<br>n<em>e</em>ixi (o n<em>a</em>ixi), n<em>e</em>ix (o n<em>a</em>ix)<br><u>tr<em>e</em>us</u> <u>(o</u> <u>tr<em>a</em>us),</u> <u>tr<em>e</em>uen</u> <u>(o</u> <u>tr<em>a</em>uen),</u> <u>tr<em>e</em>t</u></td><td colspan=\"3\" rowspan=\"1\">j<em>a</em>iem, j<em>a</em>uríeu, j<em>a</em>ient, j<em>a</em>gut<br>n<em>a</em>ixia, n<em>a</em>ixessis, n<em>a</em>ixent, n<em>a</em>scut<br><u>tr<em>a</em>uràs,</u> <u>tr<em>a</em>guem,</u> <u>tr<em>a</em>ient</u></td></tr></tbody></table></div><p>Així mateix, en els verbs següents, quan l’arrel és tònica, també escriurem <em>a</em> o bé <em>e</em>, segons la vocal que<br>pronunciem i, quan l’arrel és àtona, escriurem sempre <em>a</em>.</p><p>saber s<em>a</em>p, s<em>é</em> s<em>a</em>bés, s<em>a</em>but<br>caure c<em>a</em>u, qu<em>è</em>iem c<em>a</em>uran, c<em>a</em>ient<br>fer f<em>a</em>cis, f<em>e</em>ssis f<em>a</em>ria, f<em>a</em>rem<br><u>haver</u> <u>h<em>a</em>s,</u> <u>h<em>e</em>m</u> <u>h<em>a</em>gut,</u> <u>h<em>a</em>uré</u></p><p>2. Com que el català i el castellà són dues llengües romàniques, moltes vegades coincideixen en la grafia,<br>però en altres casos no.</p><p>Escrivim amb <em>e</em>:</p><p>albercoc emparar Esteve orfe tàvec<br>assemblea Empordà meravella resplendir treball<br>Caterina enyorar monestir sergent vernís</p><p>Escrivim amb <em>a</em>:</p><p>afaitar avaluar davant rancor els noms<br>ambaixada avantatge pesta sanefa de lletra<br>arravatar avaria quarantena Sardenya [la ema,<br>assassí darrere ramat tarda la ena...]</p></section>","topicNumber":"03"},{"id":"book-o04","title":"Les vocals O/U àtones","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"17–20","exercises":[{"id":"book-o04-ex1","number":"O4.1","title":"Feu el plural dels mots següents.","type":"open","bodyHtml":"<p>ferro: cau:<br>mosso: feliç:<br>babau: pallasso:<br>calaix: despatx:<br>annex: text:</p>","sourcePage":19,"pdfPage":16,"solutionHtml":"<p>ferros / mossos / babaus / calaixos / annexos / caus / feliços / pallassos / despatxos / textos-texts</p>","book":true,"prompt":"","explanation":""},{"id":"book-o04-ex2","number":"O4.2","title":"Completeu les frases següents amb les vocals o/u.","type":"open","bodyHtml":"<p>1. Aquell individ__ ven pis__s a pre__s escandalos__s.<br>2. Us pode__ trencar el pe__ si caie__ de la mot__.<br>3. Admet__ a tràmit la demanda de divorci de mut__ acord.<br>4. Els veïns quedaran sorpres__s si vosaltres plante__ els arbust__s.<br>5. No tots els europe__s teni__ els mateix__s complex__s que els nord-americans.</p>","sourcePage":19,"pdfPage":16,"solutionHtml":"<p>1. Aquell individ<strong>u</strong> ven pis<strong>o</strong>s a pre<strong>u</strong>s escandalos<strong>o</strong>s.<br>2. Us pode<strong>u</strong> trencar el pe<strong>u</strong> si caie<strong>u</strong> de la mot<strong>o</strong>.<br>3. Admet<strong>o</strong> a tràmit la demanda de divorci de mut<strong>u</strong> acord.<br>4. Els veïns quedaran sorpres<strong>o</strong>s si vosaltres plante<strong>u</strong> els arbust<strong>o</strong>s.<br>5. No tots els europe<strong>u</strong>s teni<strong>u</strong> els mateix<strong>o</strong>s complex<strong>o</strong>s que els nord-americans.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o04-ex3","number":"O4.3","title":"Escriviu el primitiu d’aquestes paraules derivades i completeu-les amb la vocal corresponent.","type":"open","bodyHtml":"<p>______________: rell__tgeria ______________: f__llatge ______________: campi__nat<br>______________: s__rral ______________: tovall__leta ______________: emb__irat<br>______________: enn__volat ______________: gr__ixut ______________: f__guera<br>______________: f__rçut ______________: p__pet ______________: sab__nera<br>______________: p__rtalada ______________: cal__rós ______________: encart__nat<br>______________: m__cador ______________: sangl__tar ______________: c__quet</p>","sourcePage":19,"pdfPage":16,"solutionHtml":"<p>rellotge: rell<strong>o</strong>tgeria fulla: f<strong>u</strong>llatge campió: campi<strong>o</strong>nat<br>sorra: s<strong>o</strong>rral tovallola: tovall<strong>o</strong>leta boira: emb<strong>o</strong>irat<br>núvol: enn<strong>u</strong>volat gruix: gr<strong>u</strong>ixut foc: f<strong>o</strong>guera<br>força: f<strong>o</strong>rçut pop: p<strong>o</strong>pet sabó: sab<strong>o</strong>nera<br>porta: p<strong>o</strong>rtalada calor: cal<strong>o</strong>rós cartó: encart<strong>o</strong>nat<br>moc: m<strong>o</strong>cador sanglot: sangl<strong>o</strong>tar cuc: c<strong>u</strong>quet</p>","book":true,"prompt":"","explanation":""},{"id":"book-o04-ex4","number":"O4.4","title":"Escriviu la 1a persona del present d’indicatiu d’aquests infinitius i, tot seguit, completeu-los amb la vocal corresponent.","type":"open","bodyHtml":"<p>______________: d__txar ______________: b__far ______________: desc__rdar<br>______________: trem__lar ______________: m__ntar ______________: b__rxar<br>______________: c__lgar ______________: b__llir ______________: griny__lar<br>______________: esc__rçar ______________: tr__car ______________: j__gar<br>______________: p__jar ______________: t__mbar ______________: apr__var<br>______________: rep__sar ______________: m__llar ______________: arr__gar</p>","sourcePage":19,"pdfPage":16,"solutionHtml":"<p>dutxo: d<strong>u</strong>txar bufo: b<strong>u</strong>far descordo: desc<strong>o</strong>rdar<br>tremolo: trem<strong>o</strong>lar munto: m<strong>u</strong>ntar burxo: b<strong>u</strong>rxar<br>colgo: c<strong>o</strong>lgar bullo: b<strong>u</strong>llir grinyolo: griny<strong>o</strong>lar<br>escurço: esc<strong>u</strong>rçar truco: tr<strong>u</strong>car jugo: j<strong>u</strong>gar<br>pujo: p<strong>u</strong>jar tombo: t<strong>o</strong>mbar aprovo: apr<strong>o</strong>var<br>reposo: rep<strong>o</strong>sar mullo: m<strong>u</strong>llar arrugo: arr<strong>u</strong>gar</p>","book":true,"prompt":"","explanation":""},{"id":"book-o04-ex5","number":"O4.5","title":"Completeu la taula següent.","type":"open","bodyHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>canto</u></td><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>cantessis</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>cantarà</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>collir</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>poder</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>sortir</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>cosir</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>trobar</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>voler</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div>","sourcePage":20,"pdfPage":17,"solutionHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>cullo</u></td><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>collissis</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>collirà</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>puc</u></td><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>poguessis</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>podrà</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>surto</u></td><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>sortissis</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>sortirà</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>cuso</u></td><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>cosissis</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>cosirà</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>trobo</u></td><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>trobessis</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>trobarà</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>jo</u> <u>vull</u></td><td colspan=\"1\" rowspan=\"1\"><u>tu</u> <u>volguessis</u></td><td colspan=\"1\" rowspan=\"1\"><u>ell</u> <u>voldrà</u></td></tr></tbody></table></div>","book":true,"prompt":"","explanation":""},{"id":"book-o04-ex6","number":"O4.6","title":"Completeu les frases següents amb les vocals o/u.","type":"open","bodyHtml":"<p>1. Els b__mbers no van p__der apagar l’incendi que va calcinar la m__ntanya.<br>2. El f__ster es va embr__tar com si fos un carb__ner.<br>3. No c__mptava que el corre__ arribés fins demà al matí.<br>4. Quan menj__ un ll__nguet amb crema de caca__, la d__lçor m’embafa.<br>5. Si la crescuda del ri__ persisteix, no p__drem s__rtir en tot el dia.<br>6. Mai no v__ldran c__mplir els teus desitj__s.<br>7. Aquest esti__, els comerç__s de la vila donaran divers__s trofe__s als guanyadors.</p>","sourcePage":20,"pdfPage":17,"solutionHtml":"<p>1. Els b<strong>o</strong>mbers no van p<strong>o</strong>der apagar l’incendi que va calcinar la m<strong>u</strong>ntanya.<br>2. El f<strong>u</strong>ster es va embr<strong>u</strong>tar com si fos un carb<strong>o</strong>ner.<br>3. No c<strong>o</strong>mptava que el corre<strong>u</strong> arribés fins demà al matí.<br>4. Quan menj<strong>o</strong> un ll<strong>o</strong>nguet amb crema de caca<strong>u</strong>, la d<strong>o</strong>lçor m’embafa.<br>5. Si la crescuda del ri<strong>u</strong> persisteix, no p<strong>o</strong>drem s<strong>o</strong>rtir en tot el dia.<br>6. Mai no v<strong>o</strong>ldran c<strong>o</strong>mplir els teus desitj<strong>o</strong>s.<br>7. Aquest esti<strong>u</strong>, els comerç<strong>o</strong>s de la vila donaran divers<strong>o</strong>s trofe<strong>u</strong>s als guanyadors.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o04-ex7","number":"O4.7","title":"Completeu aquest text amb les vocals o/u.","type":"open","bodyHtml":"<p>Havia pecat però no v__lia que la teva àvia m’ac__sés encara i em fes retrets. Me’n vaig haver<br>d’anar sense veure’t per segona vegada.<br>Llavors, la primera, havia estat ben diferent. Ni jo mateixa m’ho p__dia explicar del tot. Va<br>ser com si en la f__scor entrés un canal de llum i em deixés enll__ernada. Com de__ passar a<br>un re__ que ha viscut temps en el rescl__sit d’un s__terrani i de sobte desc__breix l’aire lliure;<br>separar-me de tu va ser l’única pena que em vaig emp__rtar a Marsella. No sé si et desitj__ res<br>així, perquè malgrat el mal que he fet, que t’he fet a tu, va ser desc__berta i felicitat, saps?<br>No, no començ__ bé. Si us plau, filla, tu que tan s__vint m’havies c__bert d’abraçades, no em<br>tinguis ràbia. No v__lguis del tot __blidar-me.<br>Maria Barbal, <em>Emma</em> (text adaptat)</p>","sourcePage":20,"pdfPage":17,"solutionHtml":"<p>Havia pecat però no v<strong>o</strong>lia que la teva àvia m’ac<strong>u</strong>sés encara i em fes retrets. Me’n vaig haver d’anar sense veure’t per<br>segona vegada.<br>Llavors, la primera, havia estat ben diferent. Ni jo mateixa m’ho p<strong>o</strong>dia explicar del tot. Va ser com si en la f<strong>o</strong>scor entrés<br>un canal de llum i em deixés enll<strong>u</strong>ernada. Com de<strong>u</strong> passar a un re<strong>u</strong> que ha viscut temps en el rescl<strong>o</strong>sit d’un s<strong>o</strong>terrani i<br>de sobte desc<strong>o</strong>breix l’aire lliure; separar-me de tu va ser l’única pena que em vaig emp<strong>o</strong>rtar a Marsella. No sé si et<br>desitj<strong>o</strong> res així, perquè malgrat el mal que he fet, que t’he fet a tu, va ser desc<strong>o</strong>berta i felicitat, saps? No, no començ<strong>o</strong><br>bé. Si us plau, filla, tu que tan s<strong>o</strong>vint m’havies c<strong>o</strong>bert d’abraçades, no em tinguis ràbia. No v<strong>u</strong>lguis del tot <strong>o</strong>blidar-me.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o04-ex8","number":"O4.8","title":"Completeu el text següent amb les vocals o/u, segons correspongui.","type":"open","bodyHtml":"<p>La tram__ntana és un vent d’origen p__lar no excessivament humit que usa el nord dels<br>Pirine__s i el sud-oest del Massís Central Francès com a zona d’acceleració. Aquest vent,<br>den__minat de manera diferent segons la regió o l__calitat d’on es c__nsidera que pr__cedeix,<br>es fa particularment present a la plana del R__sselló, a l’Emp__rdà i a Menorca.<br>En ser un vent de terra, a tota la zona c__stanera del Principat no hi sol alçar temp__rals<br>importants. Cap a l’est, però, la situació és ben diferent, ja que pot ass__lir vel__citats<br>pr__peres als 100 km/h, alhora que alça temp__rals marítims molt perillos__s per a la<br>navegació.<br>Les referències literàries i artístiques a aquest vent són n__mbroses. Així mateix, també dona<br>nom a l’alineació m__ntanyosa més important de l’illa de Mallorca.</p><p>&lt;https://ca.wikipedia.org/wiki/Tramuntana&gt; (text adaptat)</p>","sourcePage":20,"pdfPage":17,"solutionHtml":"<p>La tram<strong>u</strong>ntana és un vent d’origen p<strong>o</strong>lar no excessivament humit que usa el nord dels Pirine<strong>u</strong>s i el sud-oest del Massís<br>Central Francès com a zona d’acceleració. Aquest vent, den<strong>o</strong>minat de manera diferent segons la regió o l<strong>o</strong>calitat d’on<br>es c<strong>o</strong>nsidera que pr<strong>o</strong>cedeix, es fa particularment present a la plana del R<strong>o</strong>sselló, a l’Emp<strong>o</strong>rdà i a Menorca.<br>En ser un vent de terra, a tota la zona c<strong>o</strong>stanera del Principat no hi sol alçar temp<strong>o</strong>rals importants. Cap a l’est, però,<br>la situació és ben diferent, ja que pot ass<strong>o</strong>lir vel<strong>o</strong>citats pr<strong>o</strong>peres als 100 km/h, alhora que alça temp<strong>o</strong>rals marítims molt<br>perillos<strong>o</strong>s per a la navegació.<br>Les referències literàries i artístiques a aquest vent són n<strong>o</strong>mbroses. Així mateix, també dona nom a l’alineació<br>m<strong>u</strong>ntanyosa més important de l’illa de Mallorca.</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 17–20 · <a href=\"assets/llibre-b2-ortografia.pdf#page=14\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>LES VOCALS O/U ÀTONES</h3><p>En català oriental, la <em>o</em> situada en síl·laba àtona es pronuncia <em>u</em>. De vegades, doncs, podem dubtar si el so<br><em>u</em> es correspon ortogràficament a una <em>u</em> o bé a una <em>o</em> àtona.</p><p>ac<em>o</em>nseguir, text<em>o</em>s, c<em>o</em>mputador, síndr<em>o</em>me, mot<em>o</em>, eur<em>o</em>, J<em>o</em>an</p><h3>O/U àtones en l’acabament dels mots</h3><p><em>a</em>) En els verbs, la 1a persona del present d’indicatiu acaba en -<em>o</em>.</p><p>admet<em>o</em>, començ<em>o</em>, reb<em>o</em>, venç<em>o</em></p><p><em>b</em>) En els substantius i els adjectius, normalment s’ha d’escriure <em>o</em>.</p><p>xoriç<em>o</em>, filferr<em>o</em>, bitx<em>o</em>, tor<em>o</em>, llor<em>o</em></p><p>El plural d’aquests mots acaba en -<em>os</em>. Així mateix, també escrivim amb -<em>os</em> el plural de substantius i<br>adjectius masculins com ara:</p><p>disc<em>o</em>s, calaix<em>o</em>s, braç<em>o</em>s, pis<em>o</em>s, espess<em>o</em>s, test<em>o</em>s, lletj<em>o</em>s, complex<em>o</em>s</p><p>Hi ha alguns cultismes, però, que acaben en -<em>u</em>: individ<em>u</em>, vid<em>u</em>, intervi<em>u</em>, contig<em>u</em>, mut<em>u</em>... En fer el plural<br>d’aquests mots, només cal afegir una -<em>s</em> final.</p><p>fideu<em>s</em>, riu<em>s</em>, hereu<em>s</em>, ambigu<em>s</em>, museu<em>s</em>, correu<em>s</em></p><h3>O/U àtones en l’arrel dels mots</h3><p><em>a</em>) En els substantius i adjectius cal buscar un primitiu de la paraula en què aquesta vocal es trobi en posició<br>tònica.</p><p>ll<em>u</em>nyania  ll<em>u</em>ny f<em>u</em>mador  f<em>u</em>m s<em>u</em>quet  s<em>u</em>c<br>p<em>o</em>rtal  p<em>o</em>rta grum<em>o</em>llós  grum<em>o</em>ll b<em>o</em>squet  b<em>o</em>sc</p><p>Hi ha, però, alguns substantius i adjectius que no segueixen la norma general, com ara: h<em>u</em>manitat, j<em>u</em>venil,<br>m<em>u</em>ndial...</p><p><em>b</em>) En el cas dels verbs, cal buscar una forma verbal, com ara la 1a o la 3a persona del singular del present<br>d’indicatiu, en què aquesta vocal sigui tònica.</p><p>f<em>u</em>mar  f<em>u</em>ma m<em>u</em>llem  m<em>u</em>llo m<em>u</em>ntaré  m<em>u</em>nto<br>m<em>o</em>strar  m<em>o</em>stra p<em>o</em>rtaria  p<em>o</em>rta ll<em>o</em>aran  ll<em>o</em>a</p><p>Hi ha, però, entre d’altres, alguns verbs que no segueixen la regla general.</p><p>1. En els verbs <em>collir</em>, <em>cosir</em>, <em>escopir</em>, <em>sortir</em> i <em>tossir</em>, i els seus compostos, l’arrel s’escriu amb <em>u</em> quan és tònica<br>i amb <em>o</em> quan és àtona.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Arrel àtona</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Arrel tònica</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>collir</u></td><td colspan=\"3\" rowspan=\"1\"><u>c<em>o</em>llíem,</u> <u>c<em>o</em>lliré</u></td><td colspan=\"2\" rowspan=\"1\"><u>c<em>u</em>lli,</u> <u>c<em>u</em>lls</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>cosir</u></td><td colspan=\"3\" rowspan=\"1\"><u>c<em>o</em>síssim,</u> <u>c<em>o</em>siries</u></td><td colspan=\"2\" rowspan=\"1\"><u>c<em>u</em>so,</u> <u>c<em>u</em>sin</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>escopir</u></td><td colspan=\"3\" rowspan=\"1\"><u>esc<em>o</em>piré,</u> <u>esc<em>o</em>pia</u></td><td colspan=\"2\" rowspan=\"1\"><u>esc<em>u</em>p,</u> <u>esc<em>u</em>pis</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>sortir</u></td><td colspan=\"3\" rowspan=\"1\"><u>s<em>o</em>rtiríeu,</u> <u>s<em>o</em>rtí</u></td><td colspan=\"2\" rowspan=\"1\"><u>s<em>u</em>rt,</u> <u>s<em>u</em>rto</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>tossir</u></td><td colspan=\"3\" rowspan=\"1\"><u>t<em>o</em>ssim,</u> <u>t<em>o</em>ssissis</u></td><td colspan=\"2\" rowspan=\"1\"><u>t<em>u</em>sso,</u> <u>t<em>u</em>ssi</u></td></tr></tbody></table></div><p>2. En els verbs <em>poder</em> i <em>voler</em>, quan l’arrel és tònica, escrivim <em>o/u</em>, segons soni, i quan és àtona escrivim <em>o</em>.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Arrel tònica</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Arrel àtona</td></tr><tr><td colspan=\"3\" rowspan=\"1\">p<em>u</em>c v<em>u</em>ll<br>p<em>u</em>gui v<em>u</em>lguis<br>p<em>o</em>ts v<em>o</em>l<br>p<em>o</em>den v<em>o</em>len</td><td colspan=\"2\" rowspan=\"1\">p<em>o</em>gués v<em>o</em>lguessis<br>p<em>o</em>dies v<em>o</em>ldríeu<br>p<em>o</em>dran v<em>o</em>lgut<br>p<em>o</em>gut v<em>o</em>lem</td></tr></tbody></table></div><p>Ara bé, totes les formes del present de subjuntiu i de l’imperatiu s’escriuen amb <em>u</em>.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Present de subjuntiu</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Imperatiu</td></tr><tr><td colspan=\"3\" rowspan=\"1\">p<em>u</em>gui v<em>u</em>lgui<br>p<em>u</em>guis v<em>u</em>lguis<br>p<em>u</em>gui v<em>u</em>lgui<br>p<em>u</em>guem v<em>u</em>lguem<br>p<em>u</em>gueu v<em>u</em>lgueu<br>p<em>u</em>guin v<em>u</em>lguin</td><td colspan=\"2\" rowspan=\"1\">p<em>u</em>gues v<em>u</em>lgues<br>p<em>u</em>gui v<em>u</em>lgui<br>p<em>u</em>guem v<em>u</em>lguem<br>p<em>u</em>gueu v<em>u</em>lgueu<br>p<em>u</em>guin v<em>u</em>lguin</td></tr></tbody></table></div><p><em>c</em>) Sovint la llengua catalana i les altres llengües romàniques coincideixen a l’hora d’escriure <em>o</em> o <em>u</em>, però no<br>sempre és així.</p><p>Escrivim amb <em>o</em>:</p><p>avorrir-se cobrir fonament podrir títol<br>botifarra complir Hongria sofrir tomba<br>capítol Empordà joguina sospirar tonyina<br>cartolina escopir joventut tamboret triomfar</p><p>Escrivim amb <em>u</em>:</p><p>bufetada cacau europeu Pirineus suportar<br>butlletí correu muntanya riu tramuntana<br>butxaca estiu muntar suborn trofeu</p></section>","topicNumber":"04"},{"id":"book-o05","title":"L’accentuació","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"21–27","exercises":[{"id":"book-o05-ex1","number":"O5.1","title":"Torneu a escriure aquests mots amb les síl·labes separades i marqueu-ne la tònica.","type":"open","bodyHtml":"<p>allunyar: cautela:<br>queia: escarransit:<br>mania: addicional:<br>pessigolles: megafonia:<br>adjudicatària: lluita:<br>triar: deien:</p>","sourcePage":24,"pdfPage":21,"solutionHtml":"<p>a-llu-<u>nyar</u> pes-si-<u>go</u>-lles cau-<u>te</u>-la me-ga-fo-<u>ni</u>-a<br><u>que</u>-ia ad-ju-di-ca-<u>tà</u>-ri-a es-car-ran-<u>sit</u> <u>llui</u>-ta<br>ma-<u>ni</u>-a tri-<u>ar</u> ad-di-ci-o-<u>nal</u> <u>de</u>-ien</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex2","number":"O5.2","title":"Classifiqueu les paraules següents a la columna corresponent.","type":"open","bodyHtml":"<p>emmagatzematge, notària, al·ludir, futbol, assumpte, degustació, atmosfera, bestreta,<br>arrendatària, territorial, esbrinar, deies, immoble, blanqueig, notaria</p><p><u>paraules</u> <u>agudes</u> <u>paraules</u> <u>planes</u> <u>paraules</u> <u>esdrúixoles</u></p>","sourcePage":24,"pdfPage":21,"solutionHtml":"<p>Paraules agudes: al·ludir, futbol, degustació, territorial, esbrinar, blanqueig<br>Paraules planes: emmagatzematge, assumpte, atmosfera, bestreta, deies, immoble, notaria<br>Paraules esdrúixoles: notària, arrendatària</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex3","number":"O5.3","title":"Marqueu amb una X si aquestes paraules es pronuncien amb e oberta o amb e tancada.","type":"open","bodyHtml":"<p><u><em>e</em></u> <u>oberta</u> <u><em>e</em></u> <u>tancada</u> <u><em>e</em></u> <u>oberta</u> <u><em>e</em></u> <u>tancada</u><br><u>mel</u> <u>peix</u><br><u>llet</u> <u>neu</u><br><u>pet</u> <u>cel</u><br><u>fred</u> <u>nen</u><br><u>peu</u> <u>lleu</u><br><u>serp</u> <u>vent</u><br><u>fe</u> <u>cert</u><br><u>veu</u> <u>fer</u><br><u>breu</u> <u>temps</u></p>","sourcePage":25,"pdfPage":22,"solutionHtml":"<p><u><em>e</em></u> <u>oberta</u> <u><em>e</em></u> <u>tancada</u> <u><em>e</em></u> <u>oberta</u> <u><em>e</em></u> <u>tancada</u><br><u>mel</u> <u>x</u> <u>peix</u> <u>x</u><br><u>llet</u> <u>x</u> <u>neu</u> <u>x</u><br><u>pet</u> <u>x</u> <u>cel</u> <u>x</u><br><u>fred</u> <u>x</u> <u>nen</u> <u>x</u><br><u>peu</u> <u>x</u> <u>lleu</u> <u>x</u><br><u>serp</u> <u>x</u> <u>vent</u> <u>x</u><br><u>fe</u> <u>x</u> <u>cert</u> <u>x</u><br><u>veu</u> <u>x</u> <u>fer</u> <u>x</u><br><u>breu</u> <u>x</u> <u>temps</u> <u>x</u></p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex4","number":"O5.4","title":"Marqueu amb una X si aquestes paraules es pronuncien amb o oberta o amb o tancada.","type":"open","bodyHtml":"<p><u><em>o</em></u> <u>oberta</u> <u><em>o</em></u> <u>tancada</u> <u><em>o</em></u> <u>oberta</u> <u><em>o</em></u> <u>tancada</u><br><u>llop</u> <u>cos</u><br><u>foc</u> <u>cor</u><br><u>rot</u> <u>plor</u><br><u>mot</u> <u>pou</u><br><u>clot</u> <u>moll</u><br><u>pop</u> <u>groc</u><br><u>roc</u> <u>pols</u><br><u>trot</u> <u>front</u><br><u>tro</u> <u>hort</u></p>","sourcePage":25,"pdfPage":22,"solutionHtml":"<p><u><em>o</em></u> <u>oberta</u> <u><em>o</em></u> <u>tancada</u> <u><em>o</em></u> <u>oberta</u> <u><em>o</em></u> <u>tancada</u><br><u>llop</u> <u>x</u> <u>cos</u> <u>x</u><br><u>foc</u> <u>x</u> <u>cor</u> <u>x</u><br><u>rot</u> <u>x</u> <u>plor</u> <u>x</u><br><u>mot</u> <u>x</u> <u>pou</u> <u>x</u><br><u>clot</u> <u>x</u> <u>moll</u> <u>x</u><br><u>pop</u> <u>x</u> <u>groc</u> <u>x</u><br><u>roc</u> <u>x</u> <u>pols</u> <u>x</u><br><u>trot</u> <u>x</u> <u>front</u> <u>x</u><br><u>tro</u> <u>x</u> <u>hort</u> <u>x</u></p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex5","number":"O5.5","title":"Classifiqueu les paraules següents segons si la seva vocal tònica és una e/o oberta o tancada.","type":"open","bodyHtml":"<p>lloguer, patidor, escola, porta, rebel, decent, sisena, actor, clarinet, malson, querella, gota, pera,<br>taronja, capella, cullera, plet, accident, dret, monstre, color, finestra, cullereta</p><p><u><em>e</em><em>/</em><em>o</em></u> <u>oberta</u> <u><em>e</em><em>/</em><em>o</em></u> <u>tancada</u></p>","sourcePage":25,"pdfPage":22,"solutionHtml":"<p><em>e/o</em> oberta: escola, porta, rebel, sisena, clarinet, malson, pera, taronja, plet, dret, monstre, cullereta<br><em>e/o</em> tancada: lloguer, patidor, decent, actor, querella, gota, capella, cullera, accident, color, finestra</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex6","number":"O5.6","title":"Totes les paraules d’aquest exercici són agudes. Accentueu les que calgui.","type":"open","bodyHtml":"<p>respon entendran segon perdo admes<br>decisio desnonament impres pero citacio<br>preso aten exclos ningu trametreu<br>congres sete tobogan enten algun</p>","sourcePage":25,"pdfPage":22,"solutionHtml":"<p>respon entendran segon perd<strong>ó</strong> adm<strong>è</strong>s<br>decisi<strong>ó</strong> desnonament impr<strong>è</strong>s per<strong>ò</strong> citaci<strong>ó</strong><br>pres<strong>ó</strong> at<strong>é</strong>n excl<strong>ò</strong>s ning<strong>ú</strong> trametreu<br>congr<strong>é</strong>s set<strong>è</strong> tobogan ent<strong>é</strong>n algun</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex7","number":"O5.7","title":"Totes les paraules d’aquest exercici són planes. Accentueu les que calgui.","type":"open","bodyHtml":"<p>diguessin pressec solid empara examen<br>poble telefon fenomens efecte mobil<br>logic temer caracter tinguessim obrissiu<br>rentessiu estomac neixer concorrer carrec</p>","sourcePage":26,"pdfPage":23,"solutionHtml":"<p>diguessin pr<strong>é</strong>ssec s<strong>ò</strong>lid empara examen<br>poble tel<strong>è</strong>fon fen<strong>ò</strong>mens efecte m<strong>ò</strong>bil<br>l<strong>ò</strong>gic t<strong>é</strong>mer car<strong>à</strong>cter tingu<strong>é</strong>ssim obr<strong>í</strong>ssiu<br>rent<strong>é</strong>ssiu est<strong>ó</strong>mac n<strong>é</strong>ixer conc<strong>ó</strong>rrer c<strong>à</strong>rrec</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex8","number":"O5.8","title":"En aquesta llista de paraules només les esdrúixoles porten accent. Poseu-l’hi.","type":"open","bodyHtml":"<p>trinxeraire atmosfera infancia estatua miseria<br>taulell familia polvora memories tecnica<br>paciencia esglesia nacional colonia materialista<br>victima esportiu quilometre solitaria bibliotecari</p>","sourcePage":26,"pdfPage":23,"solutionHtml":"<p>trinxeraire atmosfera inf<strong>à</strong>ncia est<strong>à</strong>tua mis<strong>è</strong>ria<br>taulell fam<strong>í</strong>lia p<strong>ó</strong>lvora mem<strong>ò</strong>ries t<strong>è</strong>cnica<br>paci<strong>è</strong>ncia esgl<strong>é</strong>sia nacional col<strong>ò</strong>nia materialista<br>v<strong>í</strong>ctima esportiu quil<strong>ò</strong>metre solit<strong>à</strong>ria bibliotecari</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex9","number":"O5.9","title":"Completeu les frases següents amb la forma adequada de les que hi ha entre parèntesis.","type":"open","bodyHtml":"<p>1. ____________ fan aquests policies? ―Es veu ___________ busquen un lladre. (que / què)<br>2. S’ha quedat ____________ reclamant que aquest terreny es declari ____________ no<br>urbanitzable. (sol / sòl)<br>3. ____________ veu que el jutge nou ____________ molt esportista. (es / és)<br>4. No ____________ de què li servirà que ____________ sàpiga que ho ha fet ell. (se / sé)<br>5. Ja ____________ han avisat que heu de fer un bon ____________ de les instal·lacions. (us /<br>ús)<br>6. Hi ha judicis que ____________ entretinguts, però n’hi ha molts en què et pots morir de<br>____________. (son / són)<br>7. ____________ que em dius, aquesta advocada t’ha pres el ____________. (pel / pèl)<br>8. ____________ voleu venir a Deltebre, ja ens avisareu, perquè nosaltres ____________ que hi<br>anirem. (Si / Sí)<br>9. Aquest ___________ no està gens ben dibuixat: dibuixa’l més ___________. (be / bé)<br>10. Aquest ___________ hem fet ___________ desnonaments que en tot l’any. (mes / més)</p>","sourcePage":26,"pdfPage":23,"solutionHtml":"<p>1. <strong>Què</strong> fan aquests policies? ―Es veu <strong>que</strong> busquen un lladre.<br>2. S’ha quedat <strong>sol</strong> reclamant que aquest terreny es declari <strong>sòl</strong> no urbanitzable.<br>3. <strong>Es</strong> veu que el jutge nou <strong>és</strong> molt esportista.<br>4. No <strong>sé</strong> de què li servirà que <strong>se</strong> sàpiga que ho ha fet ell.<br>5. Ja <strong>us</strong> han avisat que heu de fer un bon <strong>ús</strong> de les instal·lacions.<br>6. Hi ha judicis que <strong>són</strong> entretinguts, però n’hi ha molts en què et pots morir de <strong>son</strong>.<br>7. <strong>Pel</strong> que em dius, aquesta advocada t’ha pres el <strong>pèl</strong>.<br>8. <strong>Si</strong> voleu venir a Deltebre, ja ens avisareu, perquè nosaltres <strong>sí</strong> que hi anirem.<br>9. Aquest <strong>be</strong> no està gens ben dibuixat: dibuixa’l més <strong>bé</strong>.<br>10. Aquest <strong>mes</strong> hem fet <strong>més</strong> desnonaments que en tot l’any.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex10","number":"O5.10","title":"Accentueu les frases següents. Tingueu en compte que en cada frase hi falten 3 accents.","type":"open","bodyHtml":"<p>1. La solvencia defensiva del millor equip del mon l’ha fet campio novament.<br>2. Mentre vosaltres obrieu la porta, nosaltres fugiem rapidament de la casa.<br>3. El meu avi feia de pages al delta de l’Ebre i coneixia a consciencia el conreu de l’arros.<br>4. He sentit a la radio que es imminent l’estrena de la nova comedia del meu autor preferit.<br>5. El meu vei fa por perque te un aspecte molt sinistre quan te’l trobes de nit a l’escala.<br>6. Despres del terratremol es van sentir ambulancies i bombers durant tota la matinada.<br>7. Els ciutadans de l’Iran no tenien acces a les materies primeres que son tan abundants a la<br>zona.</p>","sourcePage":26,"pdfPage":23,"solutionHtml":"<p>1. La solv<strong>è</strong>ncia defensiva del millor equip del m<strong>ó</strong>n l’ha fet campi<strong>ó</strong> novament.<br>2. Mentre vosaltres obr<strong>í</strong>eu la porta, nosaltres fug<strong>í</strong>em r<strong>à</strong>pidament de la casa.<br>3. El meu avi feia de pag<strong>è</strong>s al delta de l’Ebre i coneixia a consci<strong>è</strong>ncia el conreu de l’arr<strong>ò</strong>s.<br>4. He sentit a la r<strong>à</strong>dio que <strong>é</strong>s imminent l’estrena de la nova com<strong>è</strong>dia del meu autor preferit.<br>5. El meu ve<strong>í</strong> fa por perqu<strong>è</strong> t<strong>é</strong> un aspecte molt sinistre quan te’l trobes de nit a l’escala.<br>6. Despr<strong>é</strong>s del terratr<strong>è</strong>mol es van sentir ambul<strong>à</strong>ncies i bombers durant tota la matinada.<br>7. Els ciutadans de l’Iran no tenien acc<strong>é</strong>s a les mat<strong>è</strong>ries primeres que s<strong>ó</strong>n tan abundants a la zona.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex11","number":"O5.11","title":"Accentueu les paraules que calgui del text següent.","type":"open","bodyHtml":"<p>La fabrica era el nucli principal de la vida a les colonies industrials. Al seu voltant es construïen<br>habitatges, cuines comunitaries, botigues, dispensaris, teatres, biblioteques... Aixi, aquests<br>nuclis fabrils es van erigir com a autentics nuclis urbans situats en zones rurals que van convertir<br>Catalunya en una potencia industrial europea. Ara fa 150 anys es va promulgar una llei que<br>permetia l’establiment de les primeres colonies al llarg dels rius Llobregat, Ter i Cardener, uns<br>nuclis dedicats a la industria que, encara ara, caracteritzen el paisatge de les comarques del<br>Bages, el Bergueda, Osona, el Ripolles o el Baix Llobregat.</p>","sourcePage":27,"pdfPage":24,"solutionHtml":"<p>La f<strong>à</strong>brica era el nucli principal de la vida a les col<strong>ò</strong>nies industrials. Al seu voltant es construïen habitatges, cuines<br>comunit<strong>à</strong>ries, botigues, dispensaris, teatres, biblioteques... Aix<strong>í</strong>, aquests nuclis fabrils es van erigir com a aut<strong>è</strong>ntics<br>nuclis urbans situats en zones rurals que van convertir Catalunya en una pot<strong>è</strong>ncia industrial europea. Ara fa 150 anys es<br>va promulgar una llei que permetia l’establiment de les primeres col<strong>ò</strong>nies al llarg dels rius Llobregat, Ter i Cardener,<br>uns nuclis dedicats a la ind<strong>ú</strong>stria que, encara ara, caracteritzen el paisatge de les comarques del Bages, el Bergued<strong>à</strong>,<br>Osona, el Ripoll<strong>è</strong>s o el Baix Llobregat.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex12","number":"O5.12","title":"Accentueu les paraules que calgui d’aquest text.","type":"open","bodyHtml":"<p>Segurament amb sorpresa, molts de vostes deuen haver observat de vegades la presencia d’uns<br>curiosos artefactes solids, d’aparença plastica, formats per una base plana de periferia corba i<br>una superficie formada per les rectes que uneixen cada punt de la base amb el vertex. Son aixo<br>que, per abreujar, anomenem cons de transit o, amb mes imprecisio, simplement cons.<br>Apareixen de sobte a carreteres, carrers, gasolineres i aparcaments. Fins i tot en algun camp<br>de futbol sovint es veu com els jugadors s’entrenen amb la pilota als peus fent ziga-zagues<br>entre cons. Solen ser de colors cridaners: ataronjats o vermellosos, pero tambe n’hi ha de<br>ratlles. Tenen un caracter gregari: poques vegades apareixen en solitari. Son timids i hieratics,<br>i hi ha qui sospita que el caracter inofensiu que aparenten es una farsa.</p><p>Quim Monzó, <em>El</em> <em>tema</em> <em>del</em> <em>tema</em> (text adaptat)</p>","sourcePage":27,"pdfPage":24,"solutionHtml":"<p>Segurament amb sorpresa, molts de vost<strong>è</strong>s deuen haver observat de vegades la pres<strong>è</strong>ncia d’uns curiosos artefactes<br>s<strong>ò</strong>lids, d’aparença pl<strong>à</strong>stica, formats per una base plana de perif<strong>è</strong>ria corba i una superf<strong>í</strong>cie formada per les rectes que<br>uneixen cada punt de la base amb el v<strong>è</strong>rtex. S<strong>ó</strong>n aix<strong>ò</strong> que, per abreujar, anomenem cons de tr<strong>à</strong>nsit o, amb m<strong>é</strong>s<br>imprecisi<strong>ó</strong>, simplement cons. Apareixen de sobte a carreteres, carrers, gasolineres i aparcaments. Fins i tot en algun<br>camp de futbol sovint es veu com els jugadors s’entrenen amb la pilota als peus fent ziga-zagues entre cons. Solen ser<br>de colors cridaners: ataronjats o vermellosos, per<strong>ò</strong> tamb<strong>é</strong> n’hi ha de ratlles. Tenen un car<strong>à</strong>cter gregari: poques vegades<br>apareixen en solitari. S<strong>ó</strong>n t<strong>í</strong>mids i hier<strong>à</strong>tics, i hi ha qui sospita que el car<strong>à</strong>cter inofensiu que aparenten <strong>é</strong>s una farsa.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o05-ex13","number":"O5.13","title":"Accentueu les paraules que calgui d’aquest text.","type":"open","bodyHtml":"<p>Infinitat d’adjectius qualifiquen la valua de George Patullo, un extraordinari davanter que ho<br>va ser per casualitat i que ha arribat a ser descrit a la seva patria com l’escoces que va ser mes<br>letal que el mateix Maradona.<br>La historia d’aquest jugador te una singularitat excepcional. Ens hem de situar a l’any 1910 a<br>la Conreria de Badalona, un terreny de joc que solia ser l’escenari d’extraordinaries jornades<br>futbolistiques i aferrissats partits de costellada entre la colonia britanica de Barcelona i l’equip<br>barceloni de l’Universitari. Per be que el principal al·licient d’aquelles trobades era l’arros amb<br>pollastre i pesols que s’assaboria al final, els futbolistes jugaven amb un punt d’honor digne<br>d’un partit de la maxima. Un dia els britanics es van presentar amb un porter alt, ros i prim.<br>Es deia George Patullo, havia nascut a Glasgow el 4 de novembre de 1888 i feia poc que havia<br>arribat a Barcelona per solids motius de negocis. Practicava esports com el rugbi, l’hoquei i el<br>tennis, pero el futbol nomes esporadicament.</p><p>Manel Tomàs, <em>Revista</em> <em>oficial</em> <em>FC</em> <em>Barcelona</em>, núm. 51 (text adaptat)</p>","sourcePage":27,"pdfPage":24,"solutionHtml":"<p>Infinitat d’adjectius qualifiquen la v<strong>à</strong>lua de George Patullo, un extraordinari davanter que ho va ser per casualitat i que<br>ha arribat a ser descrit a la seva p<strong>à</strong>tria com l’escoc<strong>è</strong>s que va ser m<strong>é</strong>s letal que el mateix Maradona.<br>La hist<strong>ò</strong>ria d’aquest jugador t<strong>é</strong> una singularitat excepcional. Ens hem de situar a l’any 1910 a la Conreria de Badalona,<br>un terreny de joc que solia ser l’escenari d’extraordin<strong>à</strong>ries jornades futbol<strong>í</strong>stiques i aferrissats partits de costellada<br>entre la col<strong>ò</strong>nia brit<strong>à</strong>nica de Barcelona i l’equip barcelon<strong>í</strong> de l’Universitari. Per b<strong>é</strong> que el principal al·licient d’aquelles<br>trobades era l’arr<strong>ò</strong>s amb pollastre i p<strong>è</strong>sols que s’assaboria al final, els futbolistes jugaven amb un punt d’honor digne<br>d’un partit de la m<strong>à</strong>xima. Un dia els brit<strong>à</strong>nics es van presentar amb un porter alt, ros i prim. Es deia George Patullo,<br>havia nascut a Glasgow el 4 de novembre de 1888 i feia poc que havia arribat a Barcelona per s<strong>ò</strong>lids motius de negocis.<br>Practicava esports com el rugbi, l’hoquei i el tennis, per<strong>ò</strong> el futbol nom<strong>é</strong>s espor<strong>à</strong>dicament.</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 21–27 · <a href=\"assets/llibre-b2-ortografia.pdf#page=18\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>L’ACCENTUACIÓ</h3><p>L’accent gràfic és el signe que escrivim sobre algunes vocals per marcar que és la vocal tònica de la paraula.</p><p>L’accentuació gràfica de les paraules està determinada per la posició que ocupa la síl·laba tònica dins del<br>mot i per la terminació de la paraula. Així mateix, en català hi ha dos tipus d’accents, l’obert (greu) i el<br>tancat (agut).</p><h3>Paraules agudes, planes i esdrúixoles</h3><p>Els mots que tenen més d’una síl·laba es poden classificar, segons el lloc que ocupi la síl·laba tònica, en<br>aguts, plans i esdrúixols.</p><p>Els mots aguts són aquells en què la síl·laba tònica és l’última síl·laba.</p><p>ca-<em>mí</em>, al-<em>gú</em>, pa-<em>per</em>, do-<em>lent</em>, pa-<em>ret</em>, par-la-<em>rem</em>, fa-<em>ré</em>, de-<em>mà</em>, par-<em>tit</em>, re-<em>mei</em></p><p>Els mots plans són aquells en què la síl·laba tònica és la penúltima síl·laba.</p><p><em>cér</em>-vol, ca-len-<em>da</em>-ri, <em>jut</em>-ge, pi-<em>lo</em>-ta, <em>prés</em>-sec, <em>plat</em>-ja, car-nis-se-<em>ri</em>-a, <em>fei</em>-na</p><p>Els mots esdrúixols són aquells en què la síl·laba tònica és l’antepenúltima síl·laba.</p><p>his-<em>tò</em>-ri-a, <em>nò</em>-mi-na, <em>fí</em>-si-ca, es-<em>pè</em>-ci-e, <em>rà</em>-di-o, au-<em>tèn</em>-ti-ca, <em>Còr</em>-do-va, me-<em>mò</em>-ri-a</p><h3>Vocals obertes i vocals tancades</h3><p>En català hi ha dos tipus de vocals, les obertes i les tancades. La vocal <em>a</em> és oberta, les vocals <em>i/u</em> són<br>tancades i les vocals <em>e/o</em> poden ser obertes o tancades. L’obertura d’una vocal es reflecteix en l’accent;<br>per tant, tenim accents oberts i accents tancats.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\">V</td><td colspan=\"1\" rowspan=\"1\">Vocal</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">T</td><td colspan=\"1\" rowspan=\"1\">Tipus d’accent</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Exemples</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"3\" rowspan=\"1\"><em>a</em></td><td colspan=\"3\" rowspan=\"1\">obert</td><td colspan=\"3\" rowspan=\"1\">c<em>à</em>stig, dem<em>à</em></td></tr><tr><td colspan=\"3\" rowspan=\"1\"><em>e</em></td><td colspan=\"3\" rowspan=\"1\">obert<br>tancat</td><td colspan=\"3\" rowspan=\"1\">caf<em>è</em>, independ<em>è</em>ncia<br>tamb<em>é</em>, parlar<em>é</em></td></tr><tr><td colspan=\"3\" rowspan=\"1\"><em>i</em></td><td colspan=\"3\" rowspan=\"1\">tancat</td><td colspan=\"3\" rowspan=\"1\">cam<em>í</em>, l<em>í</em>mit</td></tr><tr><td colspan=\"3\" rowspan=\"1\"><em>o</em></td><td colspan=\"3\" rowspan=\"1\">obert<br>tancat</td><td colspan=\"3\" rowspan=\"1\">aix<em>ò</em>, per<em>ò</em><br>selecci<em>ó</em>, vermell<em>ó</em>s</td></tr><tr><td colspan=\"3\" rowspan=\"1\"><em>u</em></td><td colspan=\"3\" rowspan=\"1\">tancat</td><td colspan=\"3\" rowspan=\"1\"><em>ú</em>nic, alg<em>ú</em></td></tr></tbody></table></div><p>E oberta / E tancada</p><p>La millor manera de distingir una <em>e</em> oberta d’una <em>e</em> tancada és parant atenció a la pronúncia. Ara bé, potser<br>les indicacions següents ens hi poden ajudar.</p><p>En la majoria de casos, quan una <em>e</em> porta accent, el porta obert. Les paraules següents, però, porten l’accent<br>tancat:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"3\"><u>Agudes</u></td><td colspan=\"3\" rowspan=\"1\"><u><em>-</em><em>é</em></u></td><td colspan=\"1\" rowspan=\"1\">alguns gal·licismes: clix<em>é</em>, quinqu<em>é</em>, pur<em>é</em>, consom<em>é</em><br>el futur de tots els verbs: parlar<em>é</em>, sortir<em>é</em><br>el passat simple de tots els verbs: vingu<em>é</em>, digu<em>é</em><br>els compostos de -<em>bé</em> i -<em>té</em>: tamb<em>é</em>, malb<em>é</em>, sost<em>é</em>, ret<em>é</em></td></tr><tr><td colspan=\"3\" rowspan=\"1\"><u><em>-</em><em>é</em><em>s</em></u></td><td colspan=\"1\" rowspan=\"1\">l’imperfet de subjuntiu: an<em>és</em>, pogu<em>és</em><br>la majoria dels que fan el plural en -<em>essos</em>: congr<em>és</em>, acc<em>és</em>, progr<em>és</em><br>altres: despr<em>és</em>, nom<em>és</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><em>-</em></td><td colspan=\"1\" rowspan=\"1\"><em>-én</em></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">les formes verbals acabades en -<em>tén</em> i -<em>cén</em>: pret<em>én</em>, est<em>én</em>, enc<em>én</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Planes</u></td><td colspan=\"3\" rowspan=\"1\"><u><em>-</em><em>é</em></u></td><td colspan=\"1\" rowspan=\"1\">alguns infinitius: t<em>é</em>mer, <em>é</em>sser, pr<em>é</em>mer, n<em>é</em>ixer, cr<em>é</em>ixer<br>l’imperfet d’indicatiu del verb <em>ser</em>: <em>é</em>rem i <em>é</em>reu<br>el passat simple: tem<em>é</em>rem, vingu<em>é</em>reu, rigu<em>é</em>rem, digu<em>é</em>reu<br>l’imperfet de subjuntiu: vingu<em>é</em>ssim, vei<em>é</em>ssiu<br>alguns mots: c<em>é</em>rvol, fer<em>é</em>stec, pr<em>é</em>stec</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Esdrúixoles</u></td><td colspan=\"3\" rowspan=\"1\"><u><em>-</em><em>é</em></u></td><td colspan=\"1\" rowspan=\"1\">alguns mots: esgl<em>é</em>sia, fer<em>é</em>stega, c<em>é</em>rvola</td></tr></tbody></table></div><p>O oberta / O tancada</p><p>Com en el cas de la <em>e</em>, la millor manera de distingir una <em>o</em> oberta d’una <em>o</em> tancada és parant atenció a la<br>pronúncia. Ara bé, potser les indicacions següents ens hi poden ajudar.</p><p>La majoria de paraules agudes porten l’accent tancat. Les paraules següents, però, porten l’accent obert:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"2\"><u>Agudes</u></td><td colspan=\"1\" rowspan=\"1\"><em>-</em></td><td colspan=\"1\" rowspan=\"1\"><em>-ò</em></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">alguns mots: aix<em>ò</em>, all<em>ò</em>, per<em>ò</em>, ress<em>ò</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><em>-</em></td><td colspan=\"1\" rowspan=\"1\"><em>-òs</em></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">alguns mots: arr<em>òs</em>, rep<em>òs</em>, terr<em>òs</em>, esp<em>òs</em>, incl<em>òs</em>, excl<em>òs</em>, recl<em>òs</em>, Bes<em>òs</em></td></tr></tbody></table></div><p>En canvi, la majoria de paraules planes i esdrúixoles són obertes. Les paraules següents, però, porten<br>l’accent tancat:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>Planes</u></td><td colspan=\"1\" rowspan=\"1\"><u><em>-</em><em>ó</em></u></td><td colspan=\"1\" rowspan=\"1\">est<em>ó</em>mac, c<em>ó</em>rrer, fur<em>ó</em>ncol, S<em>ó</em>ller</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Esdrúixoles</u></td><td colspan=\"1\" rowspan=\"1\"><u><em>-</em><em>ó</em></u></td><td colspan=\"1\" rowspan=\"1\">f<em>ó</em>rmula, p<em>ó</em>lvora, t<em>ó</em>mbola, t<em>ó</em>rtora, g<em>ó</em>ndola</td></tr></tbody></table></div><h3>Regla general d’accentuació</h3><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>Mots</u> <u>aguts</u></td><td colspan=\"1\" rowspan=\"1\">S’accentuen els que acaben en les terminacions següents:<br>-<em>a</em>: catal<em>à</em> -<em>as</em>: rep<em>às</em> -<em>en</em>: ed<em>èn</em>, am<em>én</em><br>-<em>e</em>: caf<em>è</em>, conv<em>é</em> -<em>es</em>: angl<em>ès</em>, rev<em>és</em> -<em>in</em>: Berl<em>ín</em><br>-<em>i</em>: llum<em>í</em> -<em>is</em>: inc<em>ís</em><br>-<em>o</em>: all<em>ò</em>, nad<em>ó</em> -<em>os</em>: capgr<em>òs</em>, calor<em>ós</em><br>-<em>u</em>: com<em>ú</em> -<em>us</em>: tal<em>ús</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Mots</u> <u>plans</u></td><td colspan=\"1\" rowspan=\"1\">S’accentuen sempre que no acaben en alguna de les terminacions anteriors: pl<em>à</em>stic,<br><em>à</em>cid, m<em>ò</em>bil, <em>í</em>ntim, mal<em>è</em>vol, c<em>à</em>nem, Campdev<em>à</em>nol, dip<em>ò</em>sit, ex<em>à</em>mens</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Mots</u> <u>esdrúixols</u></td><td colspan=\"1\" rowspan=\"1\">S’accentuen sempre: <em>à</em>guila, esgl<em>é</em>sia, Val<em>è</em>ncia, pel·l<em>í</em>cula, p<em>ó</em>lvora, interlocut<em>ò</em>ria,<br>m<em>ú</em>sica</td></tr></tbody></table></div><p><em>Remarques</em></p><p><em>a</em>) Cal anar amb compte amb els mots que acaben en diftong (i diftong+consonant).</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"2\" rowspan=\"4\"><u>Mots</u> <u>amb</u><br><u>diftong</u><br>decreixent</td><td colspan=\"1\" rowspan=\"2\"><u>E</u><br>a</td><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>mots</u> <u>aguts</u> <u>s’escriuen</u> <u>sense</u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\">pal<em>au</em>, corr<em>eu</em>s, escr<em>iu</em>, enren<em>ou</em>, desm<em>ai</em>, rem<em>ei</em>,<br>xir<em>oi</em>, av<em>ui</em>, paran<em>oi</em>c</td></tr><tr><td colspan=\"1\" rowspan=\"1\">accent gràfic.</td></tr><tr><td colspan=\"1\" rowspan=\"2\"><u>E</u><br>a</td><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>mots</u> <u>plans</u> <u>s’escriuen</u> <u>amb</u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\">an<em>à</em>veu, amagu<em>é</em>ssiu, mov<em>í</em>eu, d<em>è</em>ieu, v<em>ò</em>lei</td></tr><tr><td colspan=\"1\" rowspan=\"1\">accent gràfic.</td></tr><tr><td colspan=\"1\" rowspan=\"2\"><u>Mots</u> <u>amb</u><br>diftong creixent</td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\"><u>E</u><br>a</td><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>mots</u> <u>plans</u> <u>s’escriuen</u> <u>sense</u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\">contigua, obliqua, ambigua, paraigua, aigua,<br>llengua, pasqua, pasqües</td></tr><tr><td colspan=\"1\" rowspan=\"1\">accent gràfic.</td></tr></tbody></table></div><p><em>b</em>) Les combinacions formades per <em>i</em>+vocal o bé <em>u</em>+vocal no fan diftong, llevat que la segona vocal no sigui<br>també una <em>i</em> o bé una <em>u</em>. Per tant, no porten accent paraules planes com ara:</p><p>psicologia, tenia, movia, Andalusia, actua, duo</p><p>En canvi, sí que porten accent les agudes i les esdrúixoles següents:</p><p>guardi<em>à</em>, ali<em>è</em>, admissi<em>ó</em><br>gu<em>à</em>rdia, mem<em>ò</em>ria, S<em>í</em>lvia, est<em>à</em>tua, p<em>è</em>rdua</p><p><em>c</em>) Mantenen l’accent els adverbis acabats en <em>–ment</em> que provenen d’adjectius femenins que en porten.</p><p>fàcil  f<em>à</em>cilment<br>tèbia  t<em>è</em>biament<br>comuna  comunament</p><h3>L’accent diacrític</h3><p>Hi ha alguns mots, sobretot monosíl·labs, que porten accent gràfic per distingir-los d’uns altres que<br>s’escriuen igual i que, segons la regla general, no n’haurien de dur.</p><p>D’acord amb l’<em>Ortografia</em> <em>catalana</em> de l’Institut d’Estudis Catalans (2016), només s’accentuen quinze mots<br>monosíl·labs:</p><p>bé (riquesa; satisfactòriament) be (xai)<br>déu (divinitat) deu (número; font, verb deure)<br>és (verb ser) es (pronom)<br>mà (part del cos) ma (possessiu)<br>més (adverbi de quantitat) mes (període de l&#x27;any; possessiu)<br>món (univers) mon (possessiu)<br>pèl (vellositat) pel (contracció per+el)<br>què (interrogatiu; relatiu tònic) que (conjunció; relatiu àton)<br>sé (verb saber) se (pronom reflexiu)<br>sí (afirmació) si (conjunció; nota musical; pronom)<br>sòl (terreny) sol (adjectiu; astre; nota musical)<br>són (verb ser) son (nom; possessiu)<br>té (verb tenir) te (infusió; nom de lletra; pronom feble)<br>ús (usar) us (pronom feble)<br><u>vós</u> <u>(pronom</u> <u>fort;</u> <u>tractament)</u> <u>-vos</u> <u>(pronom</u> <u>feble)</u></p><p>S’accentuen els plurals dels monosíl·labs següents: <em>béns</em>, <em>déus</em>, <em>pèls</em>, <em>quès</em>, <em>sís</em> i <em>sòls</em>.</p><p><em>Remarca</em></p><p>No porten accent els mots compostos i derivats següents: <em>adeu</em>, <em>adeu-siau</em>, <em>entresol</em>, <em>subsol</em>, <em>repel</em> i a<br><em>contrapel</em>. En canvi, els mots compostos <em>pèl-roig</em>, <em>déu-vos-guard</em> i <em>més-dient</em> sí que s’accentuen.</p></section>","topicNumber":"05"},{"id":"book-o06","title":"La dièresi","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"28–31","exercises":[{"id":"book-o06-ex1","number":"O6.1","title":"Poseu dièresi a les us que calgui.","type":"open","bodyHtml":"<p>consequència aiguera guanyar qualificar pinguí<br>sanguinari queixa liquadora antigues quatre<br>aquari ambigues enquesta paraigua antiguitat<br>frequent pasqua linguista quocient questió</p>","sourcePage":29,"pdfPage":26,"solutionHtml":"<p>conseq<strong>ü</strong>ència aig<strong>ü</strong>era guanyar qualificar ping<strong>ü</strong>í<br>sanguinari queixa liquadora antigues quatre<br>aquari ambig<strong>ü</strong>es enquesta paraigua antiguitat<br>freq<strong>ü</strong>ent pasqua ling<strong>ü</strong>ista quocient q<strong>ü</strong>estió</p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex2","number":"O6.2","title":"Separeu les síl·labes d’aquestes paraules, marqueu-ne la tònica i poseu-los dièresi, si cal.","type":"open","bodyHtml":"<p>biscaina: almoina:<br>pidolaire: Suissa:<br>geniut: fuet:<br>mania: divuit:<br>cocaina: increible:<br>peuc: rabiut:<br>Raul: heroina:<br>cofoi: pacient:</p>","sourcePage":29,"pdfPage":26,"solutionHtml":"<p>bis-ca-<u><strong>ï</strong></u>-na co-ca-<u><strong>ï</strong></u>-na al-<u>moi</u>-na in-cre-<u><strong>ï</strong></u>-ble<br>pi-do-<u>lai</u>-re pe-<u><strong>ü</strong>c</u> Su-<u><strong>ï</strong>s</u>-sa ra-bi-<u><strong>ü</strong>t</u><br>ge-ni-<u><strong>ü</strong>t</u> Ra-<u><strong>ü</strong>l</u> fu-<u>et</u> he-ro-<u><strong>ï</strong></u>-na<br>ma-<u>ni</u>-a co-<u>foi</u> di-<u>vuit</u> pa-ci-<u>ent</u></p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex3","number":"O6.3","title":"Poseu les dièresis i els accents que calguin en aquestes formes del verb conduir.","type":"open","bodyHtml":"<p>condueixo conduia condueixi conduis --------<br>condueixes conduies condueixis conduissis condueix<br>condueix conduia condueixi conduis condueixi<br>conduim conduiem conduim conduissim conduim<br>conduiu conduieu conduiu conduissiu conduiu<br>condueixen conduien condueixin conduissin condueixin</p>","sourcePage":30,"pdfPage":27,"solutionHtml":"<p>condueixo condu<strong>ï</strong>a condueixi condu<strong>í</strong>s --------<br>condueixes condu<strong>ï</strong>es condueixis condu<strong>ï</strong>ssis condueix<br>condueix condu<strong>ï</strong>a condueixi condu<strong>í</strong>s condueixi<br>condu<strong>ï</strong>m condu<strong>í</strong>em condu<strong>ï</strong>m condu<strong>í</strong>ssim condu<strong>ï</strong>m<br>condu<strong>ï</strong>u condu<strong>í</strong>eu condu<strong>ï</strong>u condu<strong>í</strong>ssiu condu<strong>ï</strong>u<br>condueixen condu<strong>ï</strong>en condueixin condu<strong>ï</strong>ssin condueixin</p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex4","number":"O6.4","title":"Completeu les formes verbals següents amb les dièresis que calguin.","type":"open","bodyHtml":"<p>adequi renuncii actui estudii<br>adequis renunciis actuis estudiis<br>adequi renuncii actui estudii<br>adequem renunciem actuem estudiem<br>adequeu renuncieu actueu estudieu<br>adequin renunciin actuin estudiin</p>","sourcePage":30,"pdfPage":27,"solutionHtml":"<p>adeq<strong>ü</strong>i renunci<strong>ï</strong> actu<strong>ï</strong> estudi<strong>ï</strong><br>adeq<strong>ü</strong>is renunci<strong>ï</strong>s actu<strong>ï</strong>s estudi<strong>ï</strong>s<br>adeq<strong>ü</strong>i renunci<strong>ï</strong> actu<strong>ï</strong> estudi<strong>ï</strong><br>adeq<strong>ü</strong>em renunciem actuem estudiem<br>adeq<strong>ü</strong>eu renuncieu actueu estudieu<br>adeq<strong>ü</strong>in renunci<strong>ï</strong>n actu<strong>ï</strong>n estudi<strong>ï</strong>n</p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex5","number":"O6.5","title":"Poseu dièresi on calgui.","type":"open","bodyHtml":"<p>descafeinat aillament cautela reumàtic cocainòman<br>ansietat enciam ensaimada veinatge lliurament<br>ruinós traició gratuitat trabucaire Lluiset</p>","sourcePage":30,"pdfPage":27,"solutionHtml":"<p>descafe<strong>ï</strong>nat a<strong>ï</strong>llament cautela reumàtic coca<strong>ï</strong>nòman<br>ansietat enciam ensa<strong>ï</strong>mada ve<strong>ï</strong>natge lliurament<br>ru<strong>ï</strong>nós tra<strong>ï</strong>ció gratu<strong>ï</strong>tat trabucaire Llu<strong>ï</strong>set</p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex6","number":"O6.6","title":"Poseu dièresi i/o accent en aquestes formes verbals, si cal.","type":"open","bodyHtml":"<p>contribuiem queien distribuissin reproduis duieu<br>construies beneida amoinaveu recauen traduit<br>llegia deduissiu adduiem aigualien absorbieu<br>posseia conduien duien destruissim constituien<br>substituiran continuis enviis sabies queieu</p>","sourcePage":30,"pdfPage":27,"solutionHtml":"<p>contribu<strong>í</strong>em queien distribu<strong>ï</strong>ssin reprodu<strong>í</strong>s d<strong>ú</strong>ieu<br>constru<strong>ï</strong>es bene<strong>ï</strong>da amo<strong>ï</strong>n<strong>à</strong>veu recauen tradu<strong>ï</strong>t<br>llegia dedu<strong>í</strong>ssiu addu<strong>í</strong>em aigualien absorb<strong>í</strong>eu<br>posse<strong>ï</strong>a condu<strong>ï</strong>en duien destru<strong>í</strong>ssim constitu<strong>ï</strong>en<br>substituiran continu<strong>ï</strong>s envi<strong>ï</strong>s sabies qu<strong>è</strong>ieu</p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex7","number":"O6.7","title":"Poseu dièresi i/o accent en aquestes paraules, si cal.","type":"open","bodyHtml":"<p>tornessiu traidoria gabia materia continui<br>linguistic reduissim conduir heroinoman coalicio<br>dormia certamen pressio egoisme accio<br>construiu recorrer agraieu agrait Lluis<br>tria taut incaut conduint ruina</p>","sourcePage":30,"pdfPage":27,"solutionHtml":"<p>torn<strong>é</strong>ssiu tra<strong>ï</strong>doria g<strong>à</strong>bia mat<strong>è</strong>ria continu<strong>ï</strong><br>ling<strong>üí</strong>stic redu<strong>í</strong>ssim conduir hero<strong>ï</strong>n<strong>ò</strong>man coalici<strong>ó</strong><br>dormia certamen pressi<strong>ó</strong> egoisme acci<strong>ó</strong><br>constru<strong>ï</strong>u rec<strong>ó</strong>rrer agra<strong>í</strong>eu agra<strong>ï</strong>t Llu<strong>í</strong>s<br>tria ta<strong>ü</strong>t incaut conduint ru<strong>ï</strong>na</p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex8","number":"O6.8","title":"Completeu aquest text amb els accents i les dièresis adients.","type":"open","bodyHtml":"<p>La punta dels dits de les potes d’un mamifer ungulat rep el nom de peulla. Consisteix en una<br>sola dura o gomosa i una paret dura formada per una ungla gruixuda que envolta la punta del<br>dit. El pes de l’animal es suportat per la sola i per la vora de l’ungla. Les peulles creixen<br>continuament i es desgasten constantment per l’us. Ovelles, cabres, cervols, vaques, bisons i</p><p>porcs en tenen dues de principals a cada pota, que conjuntament reben el nom d’unglot. La<br>majoria d’animals amb unglot tambe tenen unes petites urpes mes amunt de la pota.</p><p>&lt;https://ca.wikipedia.org/wiki/Peülla&gt; (text adaptat)</p>","sourcePage":30,"pdfPage":27,"solutionHtml":"<p>La punta dels dits de les potes d’un mam<strong>í</strong>fer ungulat rep el nom de pe<strong>ü</strong>lla. Consisteix en una sola dura o gomosa i una<br>paret dura formada per una ungla gruixuda que envolta la punta del dit. El pes de l’animal <strong>é</strong>s suportat per la sola i per<br>la vora de l’ungla. Les pe<strong>ü</strong>lles creixen cont<strong>í</strong>nuament i es desgasten constantment per l’<strong>ú</strong>s. Ovelles, cabres, c<strong>é</strong>rvols,<br>vaques, bisons i porcs en tenen dues de principals a cada pota, que conjuntament reben el nom d’unglot. La majoria<br>d’animals amb unglot tamb<strong>é</strong> tenen unes petites urpes m<strong>é</strong>s amunt de la pota.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex9","number":"O6.9","title":"Poseu accent o dièresi a les paraules que calgui del text següent.","type":"open","bodyHtml":"<p>Durant aquella primera epoca vam conviure amb prou comoditat. El pis on viviem era petit pero<br>lluminos, amb uns grans finestrals que permetien una vista privilegiada de la ciutat. Un passadis<br>molt llarg menava del rebedor al menjador, des del qual s’accedia a les dues habitacions. El<br>bany era acceptable, amb una banyera gran i comoda. A mes, ja tenia linia de telefon i no calia<br>pagar l’alta. La cuina era realment una ruina: vam haver de reformar-la totalment i recordo<br>que durant les obres, per estalviar, nomes menjavem arros i, de postres, nous, pressecs i raim,<br>que aleshores anaven be de preu.<br>Cada mes haviem d’anar tornant aquell prestec al banc, la qual cosa feia que haguessim de<br>vigilar les despeses fins al limit.</p>","sourcePage":31,"pdfPage":28,"solutionHtml":"<p>Durant aquella primera <strong>è</strong>poca vam conviure amb prou comoditat. El pis on viv<strong>í</strong>em era petit per<strong>ò</strong> llumin<strong>ó</strong>s, amb uns<br>grans finestrals que permetien una vista privilegiada de la ciutat. Un passad<strong>í</strong>s molt llarg menava del rebedor al<br>menjador, des del qual s’accedia a les dues habitacions. El bany era acceptable, amb una banyera gran i c<strong>ò</strong>moda. A<br>m<strong>é</strong>s, ja tenia l<strong>í</strong>nia de tel<strong>è</strong>fon i no calia pagar l’alta. La cuina era realment una ru<strong>ï</strong>na: vam haver de reformar-la totalment<br>i recordo que durant les obres, per estalviar, nom<strong>é</strong>s menj<strong>à</strong>vem arr<strong>ò</strong>s i, de postres, nous, pr<strong>é</strong>ssecs i ra<strong>ï</strong>m, que aleshores<br>anaven b<strong>é</strong> de preu.<br>Cada mes hav<strong>í</strong>em d’anar tornant aquell pr<strong>é</strong>stec al banc, la qual cosa feia que hagu<strong>é</strong>ssim de vigilar les despeses fins al<br>l<strong>í</strong>mit.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex10","number":"O6.10","title":"Poseu accent o dièresi a les paraules que calgui del text següent.","type":"open","bodyHtml":"<p>El futbol representa, sens dubte, l’esport mes arrelat al nostre pais, ja que va arribar a<br>Catalunya a final del segle XIX de la ma de la colonia anglesa que hi residia, aixi com de catalans<br>que havien estudiat a l’estranger. Pero la historia no ho explica pas tot i parlar de futbol vol<br>dir parlar tambe de passions, alegries i decepcions.<br>El reglament d’aquest esport es relativament senzill, fet que potser ha ajudat al seu exit; de<br>futbol tothom en sap i tothom en pot dir alguna cosa o altra. Molta gent te alguna vivencia<br>associada a una victoria inoblidable del seu club que fa esclatar una ciutat sencera o, per que<br>negar-ho, a una decepcio d’aquelles que fan epoca. Quan l’equip guanya, l’aficionat viu agrait<br>als tecnics i als jugadors, convertits en herois populars: celebracions, festes i alegria pertot<br>arreu. La ruina arriba quan l’equip perd: depressions, decepcions i, el pitjor de tot, aquell<br>somriure burleta del vei d’escala que sap de quin equip ets...</p>","sourcePage":31,"pdfPage":28,"solutionHtml":"<p>El futbol representa, sens dubte, l’esport m<strong>é</strong>s arrelat al nostre pa<strong>í</strong>s, ja que va arribar a Catalunya a final del segle XIX<br>de la m<strong>à</strong> de la col<strong>ò</strong>nia anglesa que hi residia, aix<strong>í</strong> com de catalans que havien estudiat a l’estranger. Per<strong>ò</strong> la hist<strong>ò</strong>ria no<br>ho explica pas tot i parlar de futbol vol dir parlar tamb<strong>é</strong> de passions, alegries i decepcions.<br>El reglament d’aquest esport <strong>é</strong>s relativament senzill, fet que potser ha ajudat al seu <strong>è</strong>xit; de futbol tothom en sap i<br>tothom en pot dir alguna cosa o altra. Molta gent t<strong>é</strong> alguna viv<strong>è</strong>ncia associada a una vict<strong>ò</strong>ria inoblidable del seu club<br>que fa esclatar una ciutat sencera o, per qu<strong>è</strong> negar-ho, a una decepci<strong>ó</strong> d’aquelles que fan <strong>è</strong>poca. Quan l’equip guanya,<br>l’aficionat viu agra<strong>ï</strong>t als t<strong>è</strong>cnics i als jugadors, convertits en herois populars: celebracions, festes i alegria pertot arreu.<br>La ru<strong>ï</strong>na arriba quan l’equip perd: depressions, decepcions i, el pitjor de tot, aquell somriure burleta del ve<strong>í</strong> d’escala<br>que sap de quin equip ets...</p>","book":true,"prompt":"","explanation":""},{"id":"book-o06-ex11","number":"O6.11","title":"Poseu accent o dièresi a les paraules que calgui del text següent.","type":"open","bodyHtml":"<p>Les persones adoptades, assolida la majoria d’edat o durant la minoria d’edat, representades<br>pels pares, tenen dret a coneixer les dades sobre els seus origens que estiguin en poder de les<br>entitats publiques espanyoles, sense perjudici de les limitacions que es puguin derivar de la<br>legislacio dels paisos dels quals provinguin els menors. Aquest dret s’ha de fer efectiu amb<br>l’assessorament, l’ajuda i la mediacio dels serveis especialitzats de l’entitat publica de<br>proteccio de menors o les organitzacions autoritzades per a aquesta finalitat.<br>Les entitats publiques competents han d’assegurar la conservacio de la informacio de que<br>disposin relativa als origens del nen, en particular la informacio respecte a la identitat dels<br>pares, aixi com la historia medica del nen i de la seva familia.<br>Les entitats col·laboradores que hagin mitjançat en l’adopcio han d’informar les entitats<br>publiques de les dades de que disposin sobre els origens del menor.</p><p>Article 12 de la Llei 54/2007, de 28 de desembre, d’adopció internacional (text adaptat)</p>","sourcePage":31,"pdfPage":28,"solutionHtml":"<p>Les persones adoptades, assolida la majoria d’edat o durant la minoria d’edat, representades pels pares, tenen dret a<br>con<strong>è</strong>ixer les dades sobre els seus or<strong>í</strong>gens que estiguin en poder de les entitats p<strong>ú</strong>bliques espanyoles, sense perjudici de<br>les limitacions que es puguin derivar de la legislaci<strong>ó</strong> dels pa<strong>ï</strong>sos dels quals provinguin els menors. Aquest dret s’ha de<br>fer efectiu amb l’assessorament, l’ajuda i la mediaci<strong>ó</strong> dels serveis especialitzats de l’entitat p<strong>ú</strong>blica de protecci<strong>ó</strong> de<br>menors o les organitzacions autoritzades per a aquesta finalitat.<br>Les entitats p<strong>ú</strong>bliques competents han d’assegurar la conservaci<strong>ó</strong> de la informaci<strong>ó</strong> de qu<strong>è</strong> disposin relativa als or<strong>í</strong>gens<br>del nen, en particular la informaci<strong>ó</strong> respecte a la identitat dels pares, aix<strong>í</strong> com la hist<strong>ò</strong>ria m<strong>è</strong>dica del nen i de la seva<br>fam<strong>í</strong>lia.<br>Les entitats col·laboradores que hagin mitjançat en l’adopci<strong>ó</strong> han d’informar les entitats públiques de les dades de qu<strong>è</strong><br>disposin sobre els or<strong>í</strong>gens del menor.</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 28–31 · <a href=\"assets/llibre-b2-ortografia.pdf#page=25\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>LA DIÈRESI</h3><p>La dièresi és un signe gràfic (¨) que escrivim damunt la <em>i</em> o la <em>u</em> en els casos següents:</p><p>1. Per indicar que cal pronunciar la <em>u</em> dels grups <em>gue</em>, <em>gui</em>, <em>que</em>, <em>qui</em>.</p><p>bilin<em>güe</em>, delin<em>qüe</em>nt, ai<em>güe</em>s, <em>qüe</em>stió, fre<em>qüe</em>nt, se<em>güe</em>nt, pas<em>qüe</em>s, pin<em>güí</em></p><p>Els grups <em>gua</em>, <em>guo</em>, <em>qua</em>, <em>quo</em> no porten dièresi, ja que en aquests casos la <em>u</em> sempre es pronuncia.</p><p>aigua, aiguota, quota, llengua, quotidià, qualitat, quantitat, guant, adequar, qualificar</p><p>2. Per assenyalar gràficament que una <em>i</em> o una <em>u</em> no forma diftong amb la vocal amb la qual està en contacte,<br>és a dir, que formen part de síl·labes diferents.</p><p>Quan la segona vocal d’un diftong decreixent és tònica, la combinació no fa diftong. Aleshores, cal marcar-<br>ho gràficament amb una dièresi sobre la segona vocal.</p><p>veïna (ve-<em>ï</em>-na) peüc (pe-<em>üc</em>) països (pa-<em>ï</em>-sos)<br>raïm (ra-<em>ïm</em>) reüll (re-<em>üll</em>) diürn (di-<em>ürn</em>)<br>cocaïna (co-ca-<em>ï</em>-na) cruïlla (cru-<em>ï</em>-lla) oïda (o-<em>ï</em>-da)</p><p>És el cas d’aquestes formes de verbs de la 3a conjugació, l’infinitiu dels quals acaba en vocal+<em>ir</em>.</p><p>sedu<em>ï</em>m condu<em>ï</em>m produ<em>ï</em>m enva<em>ï</em>m redu<em>ï</em>m<br>sedu<em>ï</em>ssis condu<em>ï</em>ssis produ<em>ï</em>ssis enva<em>ï</em>ssis redu<em>ï</em>ssis<br>sedu<em>ï</em>ssin condu<em>ï</em>ssin produ<em>ï</em>ssin enva<em>ï</em>ssin redu<em>ï</em>ssin<br>sedu<em>ï</em>t/<em>ï</em>da condu<em>ï</em>t/<em>ï</em>da produ<em>ï</em>t/<em>ï</em>da enva<em>ï</em>t/<em>ï</em>da redu<em>ï</em>t/<em>ï</em>da</p><p>Així mateix, les formes que contenen la combinació vocal+<em>i</em> (tònica)+vocal també porten dièresi a la <em>i</em>.</p><p>sedu<em>ï</em>a condu<em>ï</em>a produ<em>ï</em>a enva<em>ï</em>a redu<em>ï</em>a<br>sedu<em>ï</em>es condu<em>ï</em>es produ<em>ï</em>es enva<em>ï</em>es redu<em>ï</em>es<br>sedu<em>ï</em>u condu<em>ï</em>u produ<em>ï</em>u enva<em>ï</em>u redu<em>ï</em>u<br>sedu<em>ï</em>en condu<em>ï</em>en produ<em>ï</em>en enva<em>ï</em>en redu<em>ï</em>en</p><p>També porten dièresi les formes del singular i de la 3a persona del plural del present de subjuntiu dels verbs<br>l’infinitiu dels quals acaba en vocal+<em>ar</em>.</p><p>canviar  canvi<em>ï</em>, canvi<em>ï</em>s, canvi<em>ï</em>n suar  su<em>ï</em>, su<em>ï</em>s, su<em>ï</em>n<br>triar  tri<em>ï</em>, tri<em>ï</em>s, tri<em>ï</em>n continuar  continu<em>ï</em>, continu<em>ï</em>s, continu<em>ï</em>n</p><p>Quan coincideixen dues is (rumi<em>ï</em>, humili<em>ï</em>, espi<em>ï</em>), la dièresi sempre va a la segona.</p><p>Quan en un mot la combinació vocal+<em>i</em> o vocal+<em>u</em> no forma diftong, tampoc no en fa en cap paraula de la<br>mateixa família, i cal marcar-ho amb una dièresi, encara que la combinació estigui en posició àtona.</p><p>a-gra-<em>i</em>r  a-gra-<em>ï</em>-ment a-mo-<em>ï</em>-no  a-mo-<em>ï</em>-nar<br>pos-se-<em>i</em>r  pos-se-<em>ï</em>-dor ve-<em>í</em>  ve-<em>ï</em>-nat<br>in-tu-<em>i</em>r  in-tu-<em>ï</em>-ci-ó tra-<em>i</em>r  tra-<em>ï</em>-dor</p><p><em>Remarca</em></p><p>Casos en què no hem d’escriure la dièresi.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Exemples</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"2\"><u>Q</u><br>l</td><td colspan=\"1\" rowspan=\"1\"><u>Quan</u> <u>la</u> <u><em>i</em></u> <u>o</u> <u>la</u> <u><em>u</em></u> <u>han</u> <u>de</u> <u>dur</u> <u>accent</u> <u>segons</u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"3\" rowspan=\"2\">veí (aguda acabada en vocal)<br>agraíem (plana acabada en -<em>m</em>)</td></tr><tr><td colspan=\"1\" rowspan=\"1\">les regles d’accentuació.</td></tr><tr><td colspan=\"3\" rowspan=\"1\"><u>L’infinitiu,</u> <u>el</u> <u>gerundi,</u> <u>el</u> <u>futur</u> <u>i</u> <u>el</u><br><u>condicional</u> <u>dels</u> <u>verbs</u> <u>acabats</u> <u>en</u><br>vocal+<em>ir</em> (beneir, produir, seduir...)</td><td colspan=\"3\" rowspan=\"1\">agrair<br>agraint<br>agrairé, agrairàs, agrairà, agrairem, agraireu, agrairan<br>agrairia, agrairies, agrairia, agrairíem, agrairíeu, agrairien</td></tr><tr><td colspan=\"1\" rowspan=\"2\"><u>E</u><br>c</td><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>mots</u> <u>que</u> <u>comencen</u> <u>per</u> <u>un</u> <u>prefix</u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"3\" rowspan=\"2\">antiinflamatori, antioxidant, coautor, coincidència,<br>contraindicació, contraposar, reincidir, reintegrar, reunir</td></tr><tr><td colspan=\"1\" rowspan=\"1\">com <em>anti-</em>, <em>co</em>-, <em>contra</em>- i <em>re</em>-.</td></tr><tr><td colspan=\"1\" rowspan=\"2\"><u>E</u><br>i</td><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>mots</u> <u>que</u> <u>acaben</u> <u>en</u> <u>els</u> <u>sufixos</u> <u><em>-</em><em>i</em><em>s</em><em>m</em><em>e</em></u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"3\" rowspan=\"2\">egoisme, arcaisme, heroisme, altruista, europeista, maoista</td></tr><tr><td colspan=\"1\" rowspan=\"1\">i <em>-ista.</em></td></tr></tbody></table></div></section>","topicNumber":"06"},{"id":"book-o07","title":"B/V","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"32–33","exercises":[{"id":"book-o07-ex1","number":"O7.1","title":"Completeu les paraules següents amb b/v.","type":"open","bodyHtml":"<p>blau  bla__a, bla__or hauré  ha__er, ha__ia suau  sua__itat, sua__itzar<br>llop  llo__a, llo__ató déu  di__initat, di__í esclau  escla__itud, escla__a<br>deu  de__ia, de__em sap  sa__er, sa__erut rep  re__edor, re__ut<br>tou  to__a, esto__ar viu  vi__idor, vi__ència arxiu  arxi__ar, arxi__ador</p>","sourcePage":33,"pdfPage":30,"solutionHtml":"<p>bla<strong>v</strong>a, bla<strong>v</strong>or ha<strong>v</strong>er, ha<strong>v</strong>ia sua<strong>v</strong>itat, sua<strong>v</strong>itzar<br>llo<strong>b</strong>a, llo<strong>b</strong>ató di<strong>v</strong>initat, di<strong>v</strong>í escla<strong>v</strong>itud, escla<strong>v</strong>a<br>de<strong>v</strong>ia, de<strong>v</strong>em sa<strong>b</strong>er, sa<strong>b</strong>erut re<strong>b</strong>edor, re<strong>b</strong>ut<br>to<strong>v</strong>a, esto<strong>v</strong>ar vi<strong>v</strong>idor, vi<strong>v</strong>ència arxi<strong>v</strong>ar, arxi<strong>v</strong>ador</p>","book":true,"prompt":"","explanation":""},{"id":"book-o07-ex2","number":"O7.2","title":"Completeu aquestes paraules amb b/v, tenint en compte la consonant amb la qual estan en contacte.","type":"open","bodyHtml":"<p>em__olicar __rossa fe__le __lanquejar fi__ra<br>can__i con__eni en__iar en__elat em__enar<br>re__re en__air tram__ia em__alat o__lidar</p>","sourcePage":33,"pdfPage":30,"solutionHtml":"<p>em<strong>b</strong>olicar <strong>b</strong>rossa fe<strong>b</strong>le <strong>b</strong>lanquejar fi<strong>b</strong>ra<br>can<strong>v</strong>i con<strong>v</strong>eni en<strong>v</strong>iar en<strong>v</strong>elat em<strong>b</strong>enar<br>re<strong>b</strong>re en<strong>v</strong>air tram<strong>v</strong>ia em<strong>b</strong>alat o<strong>b</strong>lidar</p>","book":true,"prompt":"","explanation":""},{"id":"book-o07-ex3","number":"O7.3","title":"Empleneu els espais buits amb la forma d’imperfet d’indicatiu dels verbs subratllats.","type":"open","bodyHtml":"<p><u>Canto</u> cançons als nens. _________________ cançons als nens.<br><u>Escoltes</u> els debats de la ràdio. _________________ els debats de la ràdio.<br><u>Interposen</u> recursos als jutjats. _________________ recursos als jutjats.<br><u>Estudieu</u> francès a distància. _________________ francès a distància.<br><u>Escorcollem</u> el detingut. _________________ el detingut.</p>","sourcePage":33,"pdfPage":30,"solutionHtml":"<p><strong>Cantava</strong> cançons als nens. <strong>Estudiàveu</strong> francès a distància.<br><strong>Escoltaves</strong> els debats de la ràdio. <strong>Escorcollàvem</strong> el detingut.<br><strong>Interposaven</strong> recursos als jutjats.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o07-ex4","number":"O7.4","title":"Completeu aquestes frases amb b/v, segons el que calgui.","type":"open","bodyHtml":"<p>1. Un consell de sa__is va __eure de seguida que calia tro__ar una nova estratègia.<br>2. Durant la vista, l’ad__ocat de la defensa i el jutge s’adreçaran als tre__alladors en __asc.<br>3. L’à__ia sempre es queixa__a del soroll que hi ha__ia a la ta__erna del costat de casa seva.<br>4. Si compro__es els resultats a__ans de lliurar l’examen, de ben segur que apro__aràs.<br>5. Quan la policia es__rini el mò__il serà més fàcil sa__er qui ho va fer.<br>6. La Joana potser és molt espa__ilada escri__int, però no sap muntar a ca__all tan bé com tu.<br>7. Han traslladat la seu del go__ern a la ri__a dreta del riu que tra__essa la ciutat.<br>8. Al vehicle sinistrat se li va re__entar la roda, per la qual cosa va topar amb una __iga i va<br>__olcar.</p>","sourcePage":33,"pdfPage":30,"solutionHtml":"<p>1. Un consell de sa<strong>v</strong>is va <strong>v</strong>eure de seguida que calia tro<strong>b</strong>ar una nova estratègia.<br>2. Durant la vista, l’ad<strong>v</strong>ocat de la defensa i el jutge s’adreçaran als tre<strong>b</strong>alladors en <strong>b</strong>asc.<br>3. L’à<strong>v</strong>ia sempre es queixa<strong>v</strong>a del soroll que hi ha<strong>v</strong>ia a la ta<strong>v</strong>erna del costat de casa seva.<br>4. Si compro<strong>v</strong>es els resultats a<strong>b</strong>ans de lliurar l’examen, de ben segur que apro<strong>v</strong>aràs.<br>5. Quan la policia es<strong>b</strong>rini el mò<strong>b</strong>il serà més fàcil sa<strong>b</strong>er qui ho va fer.<br>6. La Joana potser és molt espa<strong>v</strong>ilada escri<strong>v</strong>int, però no sap muntar a ca<strong>v</strong>all tan bé com tu.<br>7. Han traslladat la seu del go<strong>v</strong>ern a la ri<strong>b</strong>a dreta del riu que tra<strong>v</strong>essa la ciutat.<br>8. Al vehicle sinistrat se li va re<strong>b</strong>entar la roda, per la qual cosa va topar amb una <strong>b</strong>iga i va <strong>b</strong>olcar.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o07-ex5","number":"O7.5","title":"Completeu aquestes frases amb b/v, segons el que calgui.","type":"open","bodyHtml":"<p>El telèfon cel·lular és un dispositiu electrònic amb ràdio de curt a__ast usat per a comunicacions<br>mò__ils de veu i dades. Funciona sobre una xarxa d’estacions __ase especialitzades distri__uïda<br>pel territori, conegudes com a cel·les. A més de la funció de veu estàndard d’un telèfon, els<br>telèfons actuals aca__en suportant molts ser__eis addicionals i accessoris: SMS per a missatges<br>de text, correu electrònic, jocs, càmera amb gra__ador de vídeo, MMS per en__iar missatges<br>amb fotos i vídeo, etc. Bàsicament tro__em dos tipus de xarxes de telefonia mò__il, l’analògica,<br>sense operati__itat des de l’any 2003, i la digital, que el 2004 va arri__ar als 1.000 milions<br>d’usuaris arreu del món.<br>Les antenes de telefonia mò__il re__en i emeten les trucades dels telèfons que hi ha en el seu<br>radi d’acció, a tra__és de l’emissió d’ones electromagnètiques d’una determinada freqüència.<br>En aquest punt el de__at és o__ert: són noci__es per a la salut aquestes antenes?<br>&lt;http://ca.wikipedia.org/wiki/Telèfon_mòbil&gt; (text adaptat)</p>","sourcePage":33,"pdfPage":30,"solutionHtml":"<p>El telèfon cel·lular és un dispositiu electrònic amb ràdio de curt a<strong>b</strong>ast usat per a comunicacions mò<strong>b</strong>ils de veu i dades.<br>Funciona sobre una xarxa d’estacions <strong>b</strong>ase especialitzades distri<strong>b</strong>uïda pel territori, conegudes com a cel·les. A més de<br>la funció de veu estàndard d’un telèfon, els telèfons actuals aca<strong>b</strong>en suportant molts ser<strong>v</strong>eis addicionals i accessoris:<br>SMS per a missatges de text, correu electrònic, jocs, càmera amb gra<strong>v</strong>ador de vídeo, MMS per en<strong>v</strong>iar missatges amb<br>fotos i vídeo, etc. Bàsicament tro<strong>b</strong>em dos tipus de xarxes de telefonia mò<strong>b</strong>il, l’analògica, sense operati<strong>v</strong>itat des de<br>l’any 2003, i la digital, que el 2004 va arri<strong>b</strong>ar als 1.000 milions d’usuaris arreu del món.<br>Les antenes de telefonia mò<strong>b</strong>il re<strong>b</strong>en i emeten les trucades dels telèfons que hi ha en el seu radi d’acció, a tra<strong>v</strong>és de<br>l’emissió d’ones electromagnètiques d’una determinada freqüència. En aquest punt el de<strong>b</strong>at és o<strong>b</strong>ert: són noci<strong>v</strong>es per<br>a la salut aquestes antenes?</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 32–33 · <a href=\"assets/llibre-b2-ortografia.pdf#page=29\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>B/V</h3><p>Actualment les lletres be (<em>b</em>) i ve baixa (<em>v</em>) es pronuncien de la mateixa manera en gran part del domini<br>lingüístic català. No hi ha cap distinció de pronúncia entre <em>bol</em> i <em>vol</em> o entre <em>probable</em> i <em>provable</em>. Tenim,<br>però, regles que resolen alguns casos en què podem dubtar de què cal escriure.</p><p><em>a</em>) Fem les alternances següents:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"2\"><u>Alternança</u> <u><em>p</em><em>/</em><em>b</em></u></td><td colspan=\"1\" rowspan=\"2\"><u>E</u><br><u>f</u></td><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>b</em></u> <u>si</u> <u>a</u> <u>l’arrel</u> <u>d’un</u> <u>mot</u> <u>de</u> <u>la</u> <u>mateixa</u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\">estre<em>p</em>  estre<em>b</em>ada, estre<em>b</em>ar<br>re<em>p</em>  re<em>b</em>ia, re<em>b</em>ut</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>família</u> <u>trobem</u> <u>el</u> <u>so</u> <u>de</u> <u><em>p</em>.</u></td></tr><tr><td colspan=\"1\" rowspan=\"2\"><u>Alternança</u> <u><em>u</em><em>/</em><em>v</em></u></td><td colspan=\"1\" rowspan=\"2\"><u>E</u><br>f</td><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>v</em></u> <u>si</u> <u>a</u> <u>l’arrel</u> <u>d’un</u> <u>mot</u> <u>de</u> <u>la</u> <u>mateixa</u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\">ne<em>u</em>  ne<em>v</em>ar, ne<em>v</em>ada<br>escri<em>u</em>  escri<em>v</em>int, escri<em>v</em>ia</td></tr><tr><td colspan=\"1\" rowspan=\"1\">família trobem la lletra <em>u</em>.</td></tr></tbody></table></div><p><em>b</em>) Escrivim <em>b</em> davant de <em>l</em> i <em>r</em>.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u><em>b</em></u></td><td colspan=\"1\" rowspan=\"1\"><u><em>b</em><em>l</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u>mo<em>b</em><em>l</em><em>e</em>,</u> <u><em>b</em><em>l</em>oc,</u> <u>o<em>b</em><em>l</em>idar,</u> <u>co<em>b</em><em>l</em>a</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u><em>b</em></u></td><td colspan=\"1\" rowspan=\"1\"><u><em>b</em><em>r</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u>a<em>b</em><em>r</em>açar,</u> <u><em>b</em><em>r</em>usa,</u> <u><em>b</em><em>r</em>ivall,</u> <u><em>b</em><em>r</em>essol</u></td></tr></tbody></table></div><p><em>c</em>) Escrivim <em>b</em> darrere de <em>m</em> i, en canvi, escrivim <em>v</em> darrere de <em>n</em>.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u>Exemples</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u>Excepcions</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u><em>m</em></u></td><td colspan=\"1\" rowspan=\"1\"><u><em>m</em><em>b</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"3\" rowspan=\"1\"><u>e<em>m</em><em>b</em>olicar,</u> <u>co<em>m</em><em>b</em>oi,</u> <u>va<em>m</em><em>b</em>a,</u> <u>ree<em>m</em><em>b</em>ors</u></td><td colspan=\"3\" rowspan=\"2\">circu<em>mv</em>al·lació, tra<em>mv</em>ia, triu<em>mv</em>ir</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u><em>n</em></u></td><td colspan=\"1\" rowspan=\"1\"><u><em>n</em><em>v</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"3\" rowspan=\"1\"><u>ca<em>n</em><em>v</em>iar,</u> <u>co<em>n</em><em>v</em>ertir,</u> <u>e<em>n</em><em>v</em>iament,</u> <u>e<em>n</em><em>v</em>estir</u></td></tr></tbody></table></div><p><em>d</em>) Escrivim <em>v</em> en les terminacions de l’imperfet d’indicatiu dels verbs de la 1a conjugació.</p><p>canta<em>v</em>a, troba<em>v</em>es, acabà<em>v</em>em, arribà<em>v</em>eu, parla<em>v</em>en</p><p>L’ús de <em>b/v</em> coincideix sovint amb les altres llengües romàniques. Però no sempre és així i, per influència<br>del castellà o del francès, escrivim malament una sèrie de mots.</p><p>Escrivim amb <em>b</em>:</p><p>abans basc Biscaia corba rebolcar<br>acabar bena (tira de fil) bolcar embenar ribera<br>alabès berruga calb mòbil sabó<br><u>arribar</u> <u>biga</u> <u>comboi</u> <u>rebentar</u> <u>treballar</u></p><p>Escrivim amb <em>v</em>:</p><p>advocat bava gavardina pavelló sivella<br>avall cascavell govern provar tàvec<br>avet cavall gravar raval taverna<br>avi covard haver rave travar<br>avorrir espavilar llavi rovell vaixell<br><u>avortar</u> <u>Esteve</u> <u>núvol</u> <u>savi</u> <u>vernís</u></p></section>","topicNumber":"07"},{"id":"book-o08","title":"P/B, T/D, C/G","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"34–37","exercises":[{"id":"book-o08-ex1","number":"O8.1","title":"Completeu els mots següents amb p/b, t/d o c/g.","type":"open","bodyHtml":"<p><u><em>p</em></u><em>/</em><u><em>b</em></u> <u><em>t</em></u><em>/</em><u><em>d</em></u> <u><em>c</em></u><em>/</em><u><em>g</em></u><br>esparadra__ co__ cunya__ nebo__ afala__ llar__<br>galo__ àra__ nor__ humi__ alberco__ festu__<br>destor__ xaro__ negui__ soleda__ ce__ alber__<br>ser__ esquer__ encanta__ eda__ pròdi__ anti__<br>prínce__ ver__ esplèndi__ ro__ galle__ barbame__</p>","sourcePage":36,"pdfPage":33,"solutionHtml":"<p><u><em>p</em><em>/</em><em>b</em></u> <u><em>t</em></u><em>/</em><u><em>d</em></u> <u><em>c</em></u><em>/</em><u><em>g</em></u><br>esparadra<strong>p</strong> co<strong>p</strong> cunya<strong>t</strong> nebo<strong>t</strong> afala<strong>c</strong> llar<strong>g</strong><br>galo<strong>p</strong> àra<strong>b</strong> nor<strong>d</strong> humi<strong>t</strong> alberco<strong>c</strong> festu<strong>c</strong><br>destor<strong>b</strong> xaro<strong>p</strong> negui<strong>t</strong> soleda<strong>t</strong> ce<strong>c</strong> alber<strong>g</strong><br>ser<strong>p</strong> esquer<strong>p</strong> encanta<strong>t</strong> eda<strong>t</strong> pròdi<strong>g</strong> anti<strong>c</strong><br>prínce<strong>p</strong> ver<strong>b</strong> esplèndi<strong>d</strong> ro<strong>t</strong> galle<strong>c</strong> barbame<strong>c</strong></p>","book":true,"prompt":"","explanation":""},{"id":"book-o08-ex2","number":"O8.2","title":"Completeu aquestes paraules amb t o d.","type":"open","bodyHtml":"<p>aptitu__ aju__ altitu__ solitu__ panxu__<br>institu__ punxegu__ benvingu__ gratitu__ exactitu__<br>su__ joventu__ mu__ gruixu__ eixu__<br>estatu__ plenitu__ lentitu__ tossu__ esclavitu__</p>","sourcePage":36,"pdfPage":33,"solutionHtml":"<p>aptitu<strong>d</strong> aju<strong>t</strong> altitu<strong>d</strong> solitu<strong>d</strong> panxu<strong>t</strong><br>institu<strong>t</strong> punxegu<strong>t</strong> benvingu<strong>t</strong> gratitu<strong>d</strong> exactitu<strong>d</strong><br>su<strong>d</strong> joventu<strong>t</strong> mu<strong>t</strong> gruixu<strong>t</strong> eixu<strong>t</strong><br>estatu<strong>t</strong> plenitu<strong>d</strong> lentitu<strong>d</strong> tossu<strong>t</strong> esclavitu<strong>d</strong></p>","book":true,"prompt":"","explanation":""},{"id":"book-o08-ex3","number":"O8.3","title":"Ompliu els espais buits amb la forma verbal corresponent.","type":"open","bodyHtml":"<p>1. Ells sempre venen a treballar mudats; jo no hi ________________ (venir) mai.<br>2. Tu escrius amb llapis; jo ________________ (escriure) amb ploma.<br>3. Ell té molta gana; jo no en ________________ (tenir) gaire.<br>4. Ells beuen vi per dinar; jo sempre ________________ (beure) aigua.<br>5. Ella coneix molta gent; jo en ________________ (conèixer) poca.<br>6. Ella entén totes les disposicions; jo no n’________________ (entendre) cap.<br>7. Ells sempre treuen el gos a passejar; jo no l’hi ________________ (treure) mai.<br>8. Tu comprens la situació; jo no la ________________ (comprendre).<br>9. Ell es pot comprar un cotxe nou; però jo no m’ho ________________ (poder) permetre.<br>10. Ella sempre està malalta; jo no ho ________________ (estar) mai.</p>","sourcePage":36,"pdfPage":33,"solutionHtml":"<p>1. Ells sempre venen a treballar mudats; jo no hi <strong>vinc</strong> mai.<br>2. Tu escrius amb llapis; jo <strong>escric</strong> amb ploma.<br>3. Ell té molta gana; jo no en <strong>tinc</strong> gaire.</p><p>4. Ells beuen vi per dinar; jo sempre <strong>bec</strong> aigua.<br>5. Ella coneix molta gent; jo en <strong>conec</strong> poca.<br>6. Ella entén totes les disposicions; jo no n’<strong>entenc</strong> cap.<br>7. Ells sempre treuen el gos a passejar; jo no l’hi <strong>trec/trac</strong> mai.<br>8. Tu comprens la situació; jo no la <strong>comprenc</strong>.<br>9. Ell es pot comprar un cotxe nou; però jo no m’ho <strong>puc</strong> permetre.<br>10. Ella sempre està malalta; jo no ho <strong>estic</strong> mai.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o08-ex4","number":"O8.4","title":"Escriviu una paraula de la mateixa família que acabi en consonant oclusiva.","type":"open","bodyHtml":"<p>recordar: <em>record</em> llampegar: encarregar:<br>glopejar: amargant: supèrbia:<br>nòrdic: estomacal: estupidesa:<br>oxidar: fangueig: catalogar:<br>naufragar: aridesa: refredar:</p>","sourcePage":36,"pdfPage":33,"solutionHtml":"<p><em>record</em> òxid amarg àrid estúpid<br>glop nàufrag estómac encàrrec catàleg<br>nord llamp/llampec fang superb fred</p>","book":true,"prompt":"","explanation":""},{"id":"book-o08-ex5","number":"O8.5","title":"Completeu els buits amb la consonant adient i relacioneu cada expressió amb el seu significat.","type":"open","bodyHtml":"<p>1. Cap geperu__ no es veu el ge__ a. Estar cansat<br>2. Feina feta no fa destor__ b. Fer que hom s’aparti d’algú<br>3. Dir quatre fàsti__s a algú c. Trobar-se en una situació moral difícil<br>4. Venir a tom__ d. Tenir la feina acabada<br>5. Anar ne__ i poli__ e. Fer retrets<br>6. Fer el bui__ a una persona f. No veure els propis defectes<br>7. Estar o viure dins el fan__ g. Fer alguna activitat sana<br>8. Estar balda__ h. Callar<br>9. Pessi__ de monja o pe__ de monja i. Apallissar<br>10. Fer mu__s i a la gàbia j. Venir a propòsit<br>11. Repartir xaro__ d’estopa k. Anar endreçat, pulcre<br>12. Fer salu__ l. Galeta petita, rodona i plana</p>","sourcePage":37,"pdfPage":34,"solutionHtml":"<p>1. Cap geperu<strong>t</strong> no es veu el ge<strong>p</strong> / 2. Feina feta no fa destor<strong>b</strong> / 3. Dir quatre fàsti<strong>c</strong>s a algú / 4. Venir a tom<strong>b</strong> / 5. Anar<br>ne<strong>t</strong> i poli<strong>t</strong> / 6. Fer el bui<strong>t</strong> a una persona / 7. Estar o viure dins el fan<strong>g</strong> / 8. Estar balda<strong>t</strong> / 9. Pessi<strong>c</strong> de monja o pe<strong>t</strong> de<br>monja / 10. Fer mu<strong>t</strong>s i a la gàbia / 11. Repartir xaro<strong>p</strong> d’estopa / 12. Fer salu<strong>t</strong><br>1f / 2d / 3e / 4j / 5k / 6b / 7c / 8a / 9l / 10h / 11i / 12g</p>","book":true,"prompt":"","explanation":""},{"id":"book-o08-ex6","number":"O8.6","title":"Completeu amb c/q, i poseu dièresi a la u, si cal.","type":"open","bodyHtml":"<p>__uantificar __uocient __uantitat e__uador __uestió<br>es__uar pas__ua eva__uar pas__ual conse__uència<br>__uota (paga) __ualificar fre__uent __uaranta en__uesta</p>","sourcePage":37,"pdfPage":34,"solutionHtml":"<p><strong>q</strong>uantificar <strong>q</strong>uocient <strong>q</strong>uantitat e<strong>q</strong>uador <strong>qü</strong>estió<br>es<strong>c</strong>uar pas<strong>q</strong>ua eva<strong>c</strong>uar pas<strong>q</strong>ual conse<strong>qü</strong>ència<br><strong>q</strong>uota <strong>q</strong>ualificar fre<strong>qü</strong>ent <strong>q</strong>uaranta en<strong>q</strong>uesta</p>","book":true,"prompt":"","explanation":""},{"id":"book-o08-ex7","number":"O8.7","title":"Completeu aquestes frases amb les consonants adients.","type":"open","bodyHtml":"<p>1. L’entrenador ha su__gerit el fitxatge de __uatre jugadors, entre els __uals hi ha un norue__<br>i un uruguaià.<br>2. Al ca__davall, aquest ull de vellu__ és l’únic que m’he endu__ de la baralla.<br>3. La possibilita__ de quedar __uarts allunya els du__tes de l’inici de la temporada.<br>4. L’acusació particular no per__ l’oportunita__ de presentar com a prova un epíle__ d’unes<br>escri__tures redactades en gre__ anti__.<br>5. __uasi la meita__ dels pagesos que es dediquen al conreu d’ame__llers i avellaners han<br>participat en la manifestació.<br>6. Sa__seja el po__ abans d’obrir-lo si vols que el gro__ de la pare__ sigui uniforme.<br>7. Cal tenir molta virtu__ per passar la ni__ al ras en aquestes latitu__s.<br>8. L’a__sència del segon co__nom en la llista oficial ha fet au__mentar la incertesa sobre la<br>identita__ del guanyador.<br>9. Al ca__damunt de la ca__çalera del llit de l’aba__ hi havia un santcrist de fusta.<br>10. Cada dia pren__ un refresc de présse__ __uan torno de córrer.</p>","sourcePage":37,"pdfPage":34,"solutionHtml":"<p>1. L’entrenador ha su<strong>g</strong>gerit el fitxatge de <strong>q</strong>uatre jugadors, entre els <strong>q</strong>uals hi ha un norue<strong>c</strong> i un uruguaià.<br>2. Al ca<strong>p</strong>davall, aquest ull de vellu<strong>t</strong> és l’únic que m’he endu<strong>t</strong> de la baralla.<br>3. La possibilita<strong>t</strong> de quedar <strong>q</strong>uarts allunya els du<strong>b</strong>tes de l’inici de la temporada.<br>4. L’acusació particular no per<strong>d</strong> l’oportunita<strong>t</strong> de presentar com a prova un epíle<strong>g</strong> d’unes escri<strong>p</strong>tures redactades en gre<strong>c</strong><br>anti<strong>c</strong>.<br>5. <strong>Q</strong>uasi la meita<strong>t</strong> dels pagesos que es dediquen al conreu d’ame<strong>t</strong>llers i avellaners han participat en la manifestació.<br>6. Sa<strong>c</strong>seja el po<strong>t</strong> abans d’obrir-lo si vols que el gro<strong>c</strong> de la pare<strong>t</strong> sigui uniforme.<br>7. Cal tenir molta virtu<strong>t</strong> per passar la ni<strong>t</strong> al ras en aquestes latitu<strong>d</strong>s.<br>8. L’a<strong>b</strong>sència del segon co<strong>g</strong>nom en la llista oficial ha fet au<strong>g</strong>mentar la incertesa sobre la identita<strong>t</strong> del guanyador.<br>9. Al ca<strong>p</strong>damunt de la ca<strong>p</strong>çalera del llit de l’aba<strong>t</strong> hi havia un santcrist de fusta.<br>10. Cada dia pren<strong>c</strong> un refresc de présse<strong>c</strong> <strong>q</strong>uan torno de córrer.</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 34–37 · <a href=\"assets/llibre-b2-ortografia.pdf#page=31\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>P/B, T/D, C/G</h3><p>L’escriptura de les grafies <em>p/b</em>, <em>t/d</em> i <em>c/g</em> (consonants oclusives) no presenta cap problema quan apareixen a<br>principi de síl·laba, ja que la pronúncia ens indica clarament quina lletra hem d’escriure. Quan es troben<br>en posició de final de síl·laba, però, es pronuncien igual, cosa que comporta problemes ortogràfics.</p><p><u>a</u> <u>principi</u> <u>de</u> <u>síl·laba</u> <u>a</u> <u>final</u> <u>de</u> <u>síl·laba</u><br><em>p</em>ena / <em>b</em>ena sa<em>p</em> / dissa<em>b</em>te<br>ren<em>t</em>a / ren<em>d</em>a do<em>t</em>ze / su<em>d</em><br>va<em>c</em>a / va<em>g</em>a anè<em>c</em>dota / càsti<em>g</em></p><h3>P/B, T/D, C/G a final de paraula</h3><p><em>a</em>) En general, escrivim <em>p/t/c</em> després de vocal tònica o de diftong tònic.</p><p>llo<em>p</em>, ta<em>p</em>, sa<em>p</em>, equi<em>p</em>, perce<em>p</em><br>mu<em>t</em>, nebo<em>t</em>, cunya<em>t</em>, humi<em>t</em>, bui<em>t</em><br>gro<em>c</em>, fo<em>c</em>, apare<em>c</em>, ami<em>c</em>, norue<em>c</em></p><p><em>b</em>) Després de consonant o de vocal àtona, en canvi, escrivim la mateixa lletra que apareix en els derivats.</p><p>àra<em>b</em> (ara<em>b</em>esc), ser<em>p</em> (ser<em>p</em>entina), super<em>b</em> (supèr<em>b</em>ia)<br>ràpi<em>d</em> (rapi<em>d</em>esa), sor<em>d</em> (sor<em>d</em>es), sor<em>t</em> (sor<em>t</em>ejar)<br>càsti<em>g</em> (casti<em>g</em>ar), amar<em>g</em> (amar<em>g</em>ar), fres<em>c</em> (fres<em>c</em>or)</p><p><em>Remarques</em></p><p><em>a</em>) Hi ha paraules que s’escriuen amb <em>b/d/g</em> després de vocal tònica (ado<em>b</em>, fre<em>d</em>, pedago<em>g</em>...).</p><p>Els noms femenins acabats en -<em>etud</em> i -<em>itud</em> s’escriuen amb -<em>d</em>, com ara qui<em>etud</em> o sol<em>itud</em>.</p><p><em>b</em>) Cal anar amb compte amb els verbs.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>No</u> <u>hi</u> <u>ha</u> <u>cap</u> <u>forma</u> <u>verbal</u> <u>que</u> <u>acabi</u> <u>en</u> <u>-<em>b</em></u> <u>(o</u> <u><em>b</em>+<em>s</em>):</u> <u>totes</u> <u>acaben</u> <u>en</u> <u>-<em>p</em>.</u></td><td colspan=\"1\" rowspan=\"1\">re<em>p</em>s, sa<em>p</em>s, perce<em>p</em>s<br>re<em>p</em>, sa<em>p</em>, perce<em>p</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>gerundis</u> <u>i</u> <u>els</u> <u>participis</u> <u>acaben</u> <u>en</u> <u>-<em>t</em>.</u></td><td colspan=\"1\" rowspan=\"1\">ballan<em>t</em>, naixen<em>t</em>, sortin<em>t</em><br>balla<em>t</em>, nascu<em>t</em>, sorti<em>t</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>No</u> <u>hi</u> <u>ha</u> <u>cap</u> <u>forma</u> <u>verbal</u> <u>que</u> <u>acabi</u> <u>en</u> <u>-<em>g</em>:</u> <u>totes</u> <u>acaben</u> <u>en</u> <u>-<em>c</em>.</u></td><td colspan=\"1\" rowspan=\"1\">apare<em>c</em>, cone<em>c</em>, tre<em>c</em><br>vin<em>c</em>, ven<em>c</em>, enten<em>c</em></td></tr></tbody></table></div><p><em>c</em>) Molts mots plans que acaben en -<em>ec</em> i les paraules <em>aràbic</em> i <em>fàstic</em> no segueixen la norma; és a dir, s’escriuen<br>amb <em>c</em> encara que en els derivats aparegui una <em>g</em>.</p><p>présse<em>c</em> (presse<em>g</em>uer), càrre<em>c</em> (càrre<em>g</em>a), espàrre<em>c</em> (esparre<em>g</em>uer), àne<em>c</em> (ane<em>g</em>uet)<br>fàsti<em>c</em> (fasti<em>g</em>uejar), aràbi<em>c</em> (aràbi<em>g</em>a)</p><p>Tots els mots que acaben en -<em>leg</em> s’escriuen amb <em>g</em>.</p><p>psicò<em>leg</em>, dià<em>leg</em>, homò<em>leg</em>, sacrí<em>leg</em></p><p><em>d</em>) En alguns mots acabats en <em>–p</em>, <em>-b</em>, <em>-t</em>, <em>-d</em> aquesta consonant no es pronuncia, però cal escriure-la, com en<br>els derivats.</p><p>cam<em>p</em> (cam<em>p</em>erol), tom<em>b</em> (tom<em>b</em>ar)<br>profun<em>d</em> (aprofun<em>d</em>ir), pun<em>t</em> (pun<em>t</em>et)</p><p>Cal tenir en compte que la paraula <em>gran</em> s’escriu sense -<em>d</em> final i que paraules com <em>col·legi</em>, <em>geni</em>, <em>premi</em> o<br><em>api</em> s’escriuen sense -<em>t</em> final.</p><h3>P/B, T/D, C/G enmig de paraula</h3><p><em>a</em>) Grafies <em>p/b</em></p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Exemples</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Excepcions</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\">E</td><td colspan=\"1\" rowspan=\"1\">En general escrivim <em>p</em>.</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"3\" rowspan=\"1\">rece<em>p</em>ta, escri<em>p</em>tor</td><td colspan=\"3\" rowspan=\"1\">du<em>b</em>te, so<em>b</em>te, dissa<em>b</em>te</td></tr><tr><td colspan=\"3\" rowspan=\"1\"><u>Escrivim</u> <u>amb</u> <u><em>b</em></u> <u>els</u> <u>mots</u> <u>començats</u> <u>per</u> <u><em>a</em><em>b</em>-,</u><br><u><em>o</em><em>b</em>-</u> <u>i</u> <u><em>s</em><em>u</em><em>b</em>-.</u></td><td colspan=\"3\" rowspan=\"1\"><em>ab</em>sència, <em>ab</em>solut<br><em>ob</em>jecte, <em>ob</em>tenir<br><em>sub</em>jecte, <em>sub</em>til</td><td colspan=\"3\" rowspan=\"1\">a<em>p</em>te, ò<em>p</em>tic, ò<em>p</em>tim, o<em>p</em>tar</td></tr><tr><td colspan=\"1\" rowspan=\"1\">E</td><td colspan=\"1\" rowspan=\"1\">Escrivim amb <em>p</em> els mots començats per <em>cap</em>-.</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"3\" rowspan=\"1\"><em>cap</em>sa, <em>cap</em>tar, ca<em>p</em>ciós</td><td colspan=\"3\" rowspan=\"1\">ca<em>b</em>dal, ca<em>b</em>dell, ca<em>b</em>dill</td></tr></tbody></table></div><p><em>b</em>) Grafies <em>t/d</em></p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Exemples</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Excepcions</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>En</u> <u>general</u> <u>escrivim</u> <u><em>t</em>.</u></td><td colspan=\"3\" rowspan=\"1\">forma<em>t</em>ge, pla<em>t</em>ja<br>ame<em>t</em>lla, se<em>t</em>mana, do<em>t</em>ze</td><td colspan=\"3\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>d</em></u> <u>en</u> <u>els</u> <u>mots</u> <u>començats</u> <u>per</u> <u><em>a</em><em>d</em>-.</u></td><td colspan=\"3\" rowspan=\"1\"><em>ad</em>ministració, <em>ad</em>jectiu<br><em>ad</em>missió, <em>ad</em>vocat</td><td colspan=\"3\" rowspan=\"1\">a<em>t</em>les, a<em>t</em>leta, A<em>t</em>làntic<br>a<em>t</em>zar, a<em>t</em>mosfera</td></tr></tbody></table></div><p><em>c</em>) Grafies <em>c/g</em></p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Exemples</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Excepcions</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>c</em></u> <u>davant</u> <u><em>c</em>,</u> <u><em>t</em>,</u> <u><em>s</em>.</u></td><td colspan=\"3\" rowspan=\"1\">a<em>c</em>cident, su<em>c</em>cés<br>a<em>c</em>tor, re<em>c</em>te<br>sa<em>c</em>sejar, fú<em>c</em>sia</td><td colspan=\"3\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>g</em></u> <u>davant</u> <u><em>m</em>,</u> <u><em>n</em>,</u> <u><em>d</em>,</u> <u><em>g</em>.</u></td><td colspan=\"3\" rowspan=\"1\">fra<em>g</em>ment, au<em>g</em>ment<br>si<em>g</em>nar, ma<em>g</em>nífic<br>ma<em>g</em>dalena, mara<em>g</em>da<br>su<em>g</em>gerir, su<em>g</em>gestió</td><td colspan=\"3\" rowspan=\"1\">anè<em>c</em>dota, tè<em>c</em>nic</td></tr></tbody></table></div><p><em>Remarca</em></p><p>En la majoria de paraules el grup <em>qua</em> s’escriu amb <em>qu</em>: <em>qua</em>tre, cin<em>qua</em>nt<em>a</em>, <em>qua</em>si, <em>qua</em>litat... Les paraules<br><em>cua</em> i eva<em>cua</em>r, però, s’escriuen amb <em>cu</em>.</p></section>","topicNumber":"08"},{"id":"book-o09","title":"S sorda i S sonora","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"38–43","exercises":[{"id":"book-o09-ex1","number":"O9.1","title":"Classifiqueu els mots següents segons si tenen un so de essa sorda o essa sonora.","type":"open","bodyHtml":"<p>tresor, tossut, rosa, quinze, salamandra, desànim, rossa, posar, passar, pesar, pagesa, bronze</p><p><u><em>s</em></u> <u>sorda</u> <u><em>s</em></u> <u>sonora</u></p>","sourcePage":41,"pdfPage":38,"solutionHtml":"<p><em>s</em> sorda: to<u>ss</u>ut, <u>s</u>alamandra, ro<u>ss</u>a, pa<u>ss</u>ar<br><em>s</em> sonora: tre<u>s</u>or, ro<u>s</u>a, quin<u>z</u>e, de<u>s</u>ànim, po<u>s</u>ar, pe<u>s</u>ar, page<u>s</u>a, bron<u>z</u>e</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex2","number":"O9.2","title":"Completeu les paraules següents amb la lletra corresponent al so de essa sorda.","type":"open","bodyHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><em>s</em> / <em>ss</em></td><td colspan=\"1\" rowspan=\"1\"><em>c</em> / <em>ç</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\">pe__ic ma__a<br>cap__a pre__a<br>dimi__ió pi__arra<br>pan__a embara__os<br>__uc espe__a</td><td colspan=\"1\" rowspan=\"1\">ca__era pin__a<br>Mer__è vi__i<br>gla__era llan__ament<br>renaixen__a adre__a<br>estru__ __iutadà</td></tr></tbody></table></div>","sourcePage":41,"pdfPage":38,"solutionHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\">pe<strong>ss</strong>ic ma<strong>ss</strong>a<br>cap<strong>s</strong>a pre<strong>ss</strong>a<br>dimi<strong>ss</strong>ió pi<strong>ss</strong>arra<br>pan<strong>s</strong>a embara<strong>ss</strong>os<br><u><strong>s</strong>uc</u> <u>espe<strong>s</strong><strong>s</strong>a</u></td><td colspan=\"1\" rowspan=\"1\">ca<strong>c</strong>era pin<strong>ç</strong>a<br>Mer<strong>c</strong>è vi<strong>c</strong>i<br>gla<strong>c</strong>era llan<strong>ç</strong>ament<br>renaixen<strong>ç</strong>a adre<strong>ç</strong>a<br><u>estru<strong>ç</strong></u> <u><strong>c</strong>iutadà</u></td></tr></tbody></table></div>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex3","number":"O9.3","title":"Completeu les formes verbals de les frases següents amb la lletra adient.","type":"open","bodyHtml":"<p>1. Si tingué__im més temps, hauríem de comen__ar a endre__ar l’arxiu del jutjat.<br>2. Quan fa__i bo vull que comen__is a nedar tot sol.<br>3. Si em fe__is una mica de cas, encara no llen__aries les cèdules de citació.<br>4. És molt fàcil vèn__er els que ja han estat ven__uts una vegada.<br>5. Si no fo__is tan bona persona, no t’haurien amena__at.</p>","sourcePage":41,"pdfPage":38,"solutionHtml":"<p>1. Si tingué<strong>ss</strong>im més temps, hauríem de comen<strong>ç</strong>ar a endre<strong>ç</strong>ar l’arxiu del jutjat.<br>2. Quan fa<strong>c</strong>i bo vull que comen<strong>c</strong>is a nedar tot sol.<br>3. Si em fe<strong>ss</strong>is una mica de cas, encara no llen<strong>ç</strong>aries les cèdules de citació.<br>4. És molt fàcil vèn<strong>c</strong>er els que ja han estat ven<strong>ç</strong>uts una vegada.<br>5. Si no fo<strong>ss</strong>is tan bona persona, no t’haurien amena<strong>ç</strong>at.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex4","number":"O9.4","title":"Torneu a escriure els mots següents amb els sufixos adients, com en l’exemple.","type":"open","bodyHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>boca</u></td><td colspan=\"1\" rowspan=\"4\">+assa</td><td colspan=\"1\" rowspan=\"1\"><u>bocassa</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>terra</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>dona</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>casa</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>enyorar</u></td><td colspan=\"1\" rowspan=\"4\">+dissa</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>trencar</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>córrer</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>bellugar</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div><p><u>boca</u> <u>bocassa</u> <u>enyorar</u><br><u>terra</u> <u>trencar</u><br>+assa +dissa<br><u>dona</u> <u>córrer</u><br><u>casa</u> <u>bellugar</u></p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>content</u></td><td colspan=\"1\" rowspan=\"4\">+íssim</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>ric</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>tendre</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>gros</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>aliar</u></td><td colspan=\"1\" rowspan=\"4\">+ança/ença</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>témer</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>créixer</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>assegurar</u></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div><p><u>content</u> <u>aliar</u><br><u>ric</u> <u>témer</u><br>+íssim +ança/ença<br><u>tendre</u> <u>créixer</u><br><u>gros</u> <u>assegurar</u></p>","sourcePage":41,"pdfPage":38,"solutionHtml":"<p>bocassa, terrassa, donassa, casassa enyoradissa, trencadissa, corredissa, bellugadissa<br>contentíssim, riquíssim, tendríssim, grossíssim aliança, temença, creixença, assegurança</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex5","number":"O9.5","title":"Completeu les frases següents amb les lletres adients corresponents al so de la essa sorda.","type":"open","bodyHtml":"<p>1. Les creen__es que transmeten els tapi__os de la __ala prin__ipal són ben a__enyades.<br>2. Si hague__in __ignat una alian__a per finan__ar el comer__ de __ucre, ara es trobarien en<br>una situa__ió boní__ima, immillorable.<br>3. La __ivella del seu __inturó és molt agre__iva, amb aquell gravat ofen__iu.<br>4. Pel pont del mar__ vull ser fora quan comen__in els embu__os a la sortida de la __iutat.<br>5. Em sento feli__ malgrat la impre__ionant palli__a que ha significat la de__isió judi__ial.</p>","sourcePage":42,"pdfPage":39,"solutionHtml":"<p>1. Les creen<strong>c</strong>es que transmeten els tapi<strong>ss</strong>os de la <strong>s</strong>ala prin<strong>c</strong>ipal són ben a<strong>ss</strong>enyades.<br>2. Si hague<strong>ss</strong>in <strong>s</strong>ignat una alian<strong>ç</strong>a per finan<strong>ç</strong>ar el comer<strong>ç</strong> de <strong>s</strong>ucre, ara es trobarien en una situa<strong>c</strong>ió boní<strong>ss</strong>ima,<br>immillorable.<br>3. La <strong>s</strong>ivella del seu <strong>c</strong>inturó és molt agre<strong>ss</strong>iva, amb aquell gravat ofen<strong>s</strong>iu.<br>4. Pel pont del mar<strong>ç</strong> vull ser fora quan comen<strong>c</strong>in els embu<strong>ss</strong>os a la sortida de la <strong>c</strong>iutat.<br>5. Em sento feli<strong>ç</strong> malgrat la impre<strong>ss</strong>ionant palli<strong>ss</strong>a que ha significat la de<strong>c</strong>isió judi<strong>c</strong>ial.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex6","number":"O9.6","title":"En totes aquestes paraules hi manca una essa sonora. Completeu-les amb s o z.","type":"open","bodyHtml":"<p>ben__inera __el tuni__ià topa__i ba__ar<br>ga__olinera abu__ar de__embre ximpan__é aran__el<br>tran__atlàntic belle__a cerve__a do__i ti__ores<br>Igna__i enfon__at don__ella dot__ena pin__ell</p>","sourcePage":42,"pdfPage":39,"solutionHtml":"<p>ben<strong>z</strong>inera <strong>z</strong>el tuni<strong>s</strong>ià topa<strong>z</strong>i ba<strong>s</strong>ar<br>ga<strong>s</strong>olinera abu<strong>s</strong>ar de<strong>s</strong>embre ximpan<strong>z</strong>é aran<strong>z</strong>el<br>tran<strong>s</strong>atlàntic belle<strong>s</strong>a cerve<strong>s</strong>a do<strong>s</strong>i ti<strong>s</strong>ores<br>Igna<strong>s</strong>i enfon<strong>s</strong>at don<strong>z</strong>ella dot<strong>z</strong>ena pin<strong>z</strong>ell</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex7","number":"O9.7","title":"Escriviu el plural de les paraules següents.","type":"open","bodyHtml":"<p>balanç: llaç: misteriós:<br>llis: avís: congrés:<br>tros: cas: anglès:<br>gros: autobús: interès:</p>","sourcePage":42,"pdfPage":39,"solutionHtml":"<p>balanços llaços misteriosos<br>llisos avisos congressos<br>trossos casos anglesos<br>grossos autobusos interessos</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex8","number":"O9.8","title":"Escriviu un nom derivat de cadascun dels infinitius següents, acabat en -ció o en -sió.","type":"open","bodyHtml":"<p>avaluar: <em>avaluació</em> resoldre: acusar:<br>decidir: concloure: citar:<br>confondre: veure: dividir:<br>falsificar: adherir: posar:</p>","sourcePage":42,"pdfPage":39,"solutionHtml":"<p><em>avaluació</em> resolució acusació<br>decisió conclusió citació<br>confusió visió divisió<br>falsificació adhesió posició</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex9","number":"O9.9","title":"Escriviu un verb derivat de cadascun dels mots següents, acabat en -itzar.","type":"open","bodyHtml":"<p>memòria: <em>memoritzar</em> síntesi: senyal:<br>agut: mòbil: indemne:<br>caràcter: anàlisi: suau:</p>","sourcePage":42,"pdfPage":39,"solutionHtml":"<p><em>memoritzar</em> sintetitzar senyalitzar<br>aguditzar mobilitzar indemnitzar<br>caracteritzar analitzar suavitzar</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex10","number":"O9.10","title":"Completeu les paraules següents amb -esa o -essa.","type":"open","bodyHtml":"<p>invalid___ alcald___ impr___ angl___ adm___<br>sord__ hongar___ savi___ metg___ vell___<br>poet___ host___ xin___ polon___ jutg___</p>","sourcePage":42,"pdfPage":39,"solutionHtml":"<p>invalid<strong>esa</strong> alcald<strong>essa</strong> impr<strong>esa</strong> angl<strong>esa</strong> adm<strong>esa</strong><br>sord<strong>esa</strong> hongar<strong>esa</strong> savi<strong>esa</strong> metg<strong>essa</strong> vell<strong>esa</strong><br>poet<strong>essa</strong> host<strong>essa</strong> xin<strong>esa</strong> polon<strong>esa</strong> jutg<strong>essa</strong></p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex11","number":"O9.11","title":"Completeu les frases següents amb les lletres escaients.","type":"open","bodyHtml":"<p>1. Ja podeu consultar la nota informativa sobre els permi__os i els terminis de pre__a de<br>po__e__ió del personal funcionari del cos de tramita__ió pro__e__al.<br>2. Notifico la re__olució anterior a la persona intere__ada en pre__ència del seu advocat i li<br>lliuro la cita__ió corresponent.<br>3. Els Mo__os d’Esquadra han de portar el detingut a comi__aria perquè el jutge li prengui<br>declara__ió abans d’ingre__ar preventivament a la pre__ó.<br>4. D’acord amb la pre__umpció d’innocència, tota persona acu__ada d’un fet delictiu és<br>innocent fins que la seva culpabilitat hagi estat establerta en un pro__és públic, en el qual<br>totes les garanties nece__àries per a la defensa hagin estat a__egurades.<br>5. Qui maltracti amb acarni__ament animals domèstics i els cau__i la mort o els provoqui<br>le__ions fí__iques ha de ser castigat a la inhabilita__ió d’un a tres anys per a la profe__ió,<br>ofi__i o comer__ que tingui rela__ió amb els animals.</p>","sourcePage":43,"pdfPage":40,"solutionHtml":"<p>1. Ja podeu consultar la nota informativa sobre els permi<strong>s</strong>os i els terminis de pre<strong>s</strong>a de po<strong>ss</strong>e<strong>ss</strong>ió del personal funcionari<br>del cos de tramita<strong>c</strong>ió pro<strong>c</strong>e<strong>ss</strong>al.<br>2. Notifico la re<strong>s</strong>olució anterior a la persona intere<strong>ss</strong>ada en pre<strong>s</strong>ència del seu advocat i li lliuro la cita<strong>c</strong>ió corresponent</p><p>3. Els Mo<strong>ss</strong>os d’Esquadra han de portar el detingut a comi<strong>ss</strong>aria perquè el jutge li prengui declara<strong>c</strong>ió abans d’ingre<strong>ss</strong>ar<br>preventivament a la pre<strong>s</strong>ó.<br>4. D’acord amb la pre<strong>s</strong>umpció d’innocència, tota persona acu<strong>s</strong>ada d’un fet delictiu és innocent fins que la seva<br>culpabilitat hagi estat establerta en un pro<strong>c</strong>és públic, en el qual totes les garanties nece<strong>ss</strong>àries per a la defensa hagin<br>estat a<strong>ss</strong>egurades.<br>5. Qui maltracti amb acarni<strong>ss</strong>ament animals domèstics i els cau<strong>s</strong>i la mort o els provoqui le<strong>s</strong>ions fí<strong>s</strong>iques ha de ser castigat<br>a la inhabilita<strong>c</strong>ió d’un a tres anys per a la profe<strong>ss</strong>ió, ofi<strong>c</strong>i o comer<strong>ç</strong> que tingui rela<strong>c</strong>ió amb els animals.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex12","number":"O9.12","title":"Completeu aquest article del Reial decret legislatiu 1/2007, de 16 de novembre, amb les consonants adients.","type":"open","bodyHtml":"<p>1. Els empre__aris han de po__ar en coneixement previ del consumidor i u__uari, per mitjans<br>apropiats, els riscos susceptibles de provenir d’una utilit__ació previ__ible dels béns i serveis,<br>tenint en compte la naturale__a, les característiques, la durada i les persones a qui van<br>destinats, d’acord amb el que es dispo__a a l’article 18 i normes reglamentàries que siguin<br>aplicables.<br>2. Els productes químics i tots els articles que en la seva compo__ició portin substàn__ies<br>cla__ificades com a perillo__es han d’anar enva__ats amb les garanties de __eguretat degudes<br>i han de portar de forma vi__ible les indica__ions oportunes que adverteixin del risc de<br>manipular-los.</p>","sourcePage":43,"pdfPage":40,"solutionHtml":"<p>1. Els empre<strong>s</strong>aris han de po<strong>s</strong>ar en coneixement previ del consumidor i u<strong>s</strong>uari, per mitjans apropiats, els riscos<br>susceptibles de provenir d’una utilit<strong>z</strong>ació previ<strong>s</strong>ible dels béns i serveis, tenint en compte la naturale<strong>s</strong>a, les<br>característiques, la durada i les persones a qui van destinats, d’acord amb el que es dispo<strong>s</strong>a a l’article 18 i normes<br>reglamentàries que siguin aplicables.<br>2. Els productes químics i tots els articles que en la seva compo<strong>s</strong>ició portin substàn<strong>c</strong>ies cla<strong>ss</strong>ificades com a perillo<strong>s</strong>es<br>han d’anar enva<strong>s</strong>ats amb les garanties de <strong>s</strong>eguretat degudes i han de portar de forma vi<strong>s</strong>ible les indica<strong>c</strong>ions oportunes<br>que adverteixin del risc de manipular-los.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o09-ex13","number":"O9.13","title":"Completeu el text següent amb les lletres que hi falten.","type":"open","bodyHtml":"<p>Hi arribo un diumenge, per carreteres rectilínies a__olellades que re__egueixen terres de secà.<br>Cartells __ituats en punts estratègics indicant la direcció i el quilometratge que em resta són<br>premonitoris de la importància del lloc on em dirigeixo. Verdú, coneguda prin__ipalment per<br>la __eràmica negra, compta amb un mu__eu que farà les delí__ies dels més menuts i no tan<br>menuts: el Mu__eu de Joguets i Autòmats. Impul__at pel col·leccionista verduní Manel Mayoral<br>amb la idea de dinamit__ar el territori, el centre està con__iderat un dels més importants en<br>la seva temàtica. L’equipament, únic a Europa, és una antiga ca__a pairal totalment reformada<br>__ituada a la mateixa pla__a Major. Quatre plantes de somnis, fanta__ia i records.</p><p>Bernat Calbetó, “Museu de Joguets i Autòmats (Verdú)”. <em>in.directe!cat</em>, 24 d’agost de 2011<br>&lt;https://indirecte.larepublica.cat/6366&gt;</p>","sourcePage":43,"pdfPage":40,"solutionHtml":"<p>Hi arribo un diumenge, per carreteres rectilínies a<strong>ss</strong>olellades que re<strong>ss</strong>egueixen terres de secà. Cartells <strong>s</strong>ituats en punts<br>estratègics indicant la direcció i el quilometratge que em resta són premonitoris de la importància del lloc on em<br>dirigeixo. Verdú, coneguda prin<strong>c</strong>ipalment per la <strong>c</strong>eràmica negra, compta amb un mu<strong>s</strong>eu que farà les delí<strong>c</strong>ies dels més<br>menuts i no tan menuts: el Mu<strong>s</strong>eu de Joguets i Autòmats. Impul<strong>s</strong>at pel col·leccionista verduní Manel Mayoral amb la<br>idea de dinamit<strong>z</strong>ar el territori, el centre està con<strong>s</strong>iderat un dels més importants en la seva temàtica. L’equipament,<br>únic a Europa, és una antiga ca<strong>s</strong>a pairal totalment reformada <strong>s</strong>ituada a la mateixa pla<strong>ç</strong>a Major. Quatre plantes de<br>somnis, fanta<strong>s</strong>ia i records.</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 38–43 · <a href=\"assets/llibre-b2-ortografia.pdf#page=35\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>S SORDA I S SONORA</h3><p>La diferència a l’hora de pronunciar el so de la essa sorda i el de la essa sonora consisteix en la vibració de<br>les cordes vocals. Quan pronunciem una essa sorda, les cordes vocals no vibren; en canvi, quan pronunciem<br>una essa sonora, sí que ho fan.</p><p><u>essa</u> <u>sorda</u> <u>essa</u> <u>sonora</u><br><em>c</em>inc <em>z</em>inc<br>ra<em>ç</em>a ra<em>s</em>a<br>ca<em>ç</em>a ca<em>s</em>a<br><em>c</em>el <em>z</em>el<br>sal<em>s</em>a sal<em>z</em>e<br>el<em>s</em> <em>s</em>avis el<em>s</em> avis<br>el<em>s</em> <em>s</em>ous el<em>s</em> ous</p><h3>La essa sorda: S, SS, C, Ç</h3><p>La essa sorda es pot escriure amb les lletres <em>s</em>, <em>ss</em>, <em>c</em>, <em>ç</em>. Podem agrupar aquestes lletres en dos grups diferents<br>―<em>s/ss</em>, d’una banda, i <em>c/ç</em>, de l’altra― i, d’alguna manera, podem dir que cada mot s’inclou en un d’aquests<br>dos grups.</p><p>Per saber si el so de la essa sorda s’ha d’escriure <em>s/ss</em> o bé <em>c/ç</em> cal tenir en compte que hi ha molts mots que<br>coincideixen amb altres llengües romàniques. Així, si en castellà, en francès o en italià van amb <em>z</em>, <em>c</em> o <em>ç</em>, en<br>català van amb <em>c</em> o <em>ç</em>. I, si en una altra llengua romànica van amb <em>s</em>, en català van amb <em>s</em> o <em>ss</em>.</p><p>can<em>ç</em>ó, ofi<em>c</em>i, <em>c</em>ent, lla<em>ç</em>, pin<em>ç</em>a, <em>c</em>ita<em>c</em>ió<br>fal<em>s</em>, a<em>ss</em>a<em>ss</em>í, <em>s</em>entiment, <em>s</em>enyalar, premi<em>ss</em>a, a<em>ss</em>entiment</p><p>Hi ha paraules, però, que no coincideixen. Trobareu un quadre amb aquestes paraules al final del tema.</p><p>Grup <em>s</em>/<em>ss</em></p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"4\"><u>E</u><br><u>―</u><br><u>―</u><br>―</td><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>s</em>:</u></td><td colspan=\"1\" rowspan=\"4\"></td><td colspan=\"1\" rowspan=\"4\"><em>s</em>al, <em>s</em>ucre, <em>s</em>oca, <em>s</em>erp, <em>s</em>iamès<br>tro<em>s</em>, anglè<em>s</em>, llapi<em>s</em>, arrò<em>s</em>, cabà<em>s</em>, embú<em>s</em><br>pan<em>s</em>a, precur<em>s</em>or, pol<em>s</em>im, adver<em>s</em>itat, Còr<em>s</em>ega</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>―a</u> <u>començament</u> <u>de</u> <u>mot</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>―a</u> <u>final</u> <u>de</u> <u>mot</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\">―entre consonant i vocal</td></tr><tr><td colspan=\"3\" rowspan=\"2\">Escrivim <em>ss</em> només entre vocals.</td><td colspan=\"1\" rowspan=\"1\">Escrivim <em>ss</em> només entre vocals.</td><td colspan=\"1\" rowspan=\"2\">ta<em>ss</em>a, Bru<em>ss</em>el·les, ca<em>ss</em>ola, boní<em>ss</em>im, cante<em>ss</em>is<br>a<em>ss</em>umpte, confe<em>ss</em>ió</td></tr></tbody></table></div><p>Grup <em>c</em>/<em>ç</em></p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>c</em></u> <u>al</u> <u>davant</u> <u>de</u> <u>les</u> <u>vocals</u> <u><em>e</em>/<em>i</em>,</u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\"><em>c</em>endra, <em>c</em>ella, <em>c</em>igró, <em>c</em>istell, <em>c</em>itar<br>Mer<em>c</em>è, feli<em>c</em>es, endol<em>c</em>ir, peti<em>c</em>ió</td></tr><tr><td colspan=\"1\" rowspan=\"1\">a començament de mot i enmig de mot.</td></tr><tr><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>ç</em></u> <u>al</u> <u>davant</u> <u>de</u> <u>les</u> <u>vocals</u> <u><em>a</em>/<em>o</em>/<em>u</em></u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\">pla<em>ç</em>a, llen<em>ç</em>ol, bra<em>ç</em>os, for<em>ç</em>ut<br>bra<em>ç</em>, comer<em>ç</em>, preco<em>ç</em>, llu<em>ç</em></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>i</u> <u>a</u> <u>fi</u> <u>de</u> <u>mot.</u></td></tr></tbody></table></div><p><em>Remarques</em></p><p><em>a</em>) Dins d’una mateixa família de paraules alternen la <em>s</em> amb la doble <em>ss</em>, i la <em>c</em> amb la <em>ç</em>.</p><p>arrò<em>s</em>, arro<em>ss</em>os, arro<em>ss</em>ada<br>pa<em>s</em>, pa<em>ss</em>os, pa<em>ss</em>ar<br>ca<em>ç</em>a, ca<em>ç</em>ador, ca<em>c</em>era<br>capa<em>ç</em>, capa<em>c</em>es, capa<em>ç</em>os</p><p><em>b</em>) Les paraules derivades acabades en -<em>ança</em> i -<em>ença</em> sempre s’escriuen amb <em>ç</em>.</p><p>esperar  esper<em>ança</em> néixer  naix<em>ença</em><br>enyorar  enyor<em>ança</em> tenir  tin<em>ença</em></p><p>Els mots <em>dansa</em> i <em>defensa</em>, que no són derivats, s’escriuen amb <em>s</em>.</p><p><em>c</em>) L’imperfet de subjuntiu sempre s’escriu amb <em>ss</em>.</p><p>cantés temés dormís<br>cante<em>ss</em>is teme<em>ss</em>is dormi<em>ss</em>is<br>cantés temés dormís<br>canté<em>ss</em>im temé<em>ss</em>im dormí<em>ss</em>im<br>canté<em>ss</em>iu temé<em>ss</em>iu dormí<em>ss</em>iu<br>cante<em>ss</em>in teme<em>ss</em>in dormi<em>ss</em>in</p><p><em>d</em>) S’escriuen amb <em>ss</em> els mots acabats en:</p><p>-<em>assa</em>: bon<em>assa</em>, boc<em>assa</em><br>-<em>issa</em>: corred<em>issa</em>, terr<em>issa</em><br>-<em>íssim</em>, -<em>íssima</em>: bon<em>íssim</em>, il·lustríss<em>ima</em><br>-<em>ussa</em>: gent<em>ussa</em>, pel<em>ussa</em><br>-<em>gressió</em>, -<em>gressor</em>: a<em>gressió</em>, a<em>gressor</em>, trans<em>gressió</em>, trans<em>gressor</em><br>-<em>missió</em>, -<em>missor</em>: e<em>missió</em>, e<em>missor</em>, trans<em>missió</em>, trans<em>missor</em><br>-<em>pressió</em>, -<em>pressor</em>: im<em>pressió</em>, im<em>pressor</em>, ex<em>pressió</em>, com<em>pressor</em></p><h3>La essa sonora: S, Z</h3><p>Per representar gràficament el so de la essa sonora tenim dues grafies: <em>s</em>, <em>z</em>.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Exemples</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Excepcions</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"1\"><u>Generalment,</u> <u>escrivim</u> <u><em>s</em></u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"3\" rowspan=\"2\">cau<em>s</em>a, de<em>s</em>è, provi<em>s</em>ió, re<em>s</em>oldre, ca<em>s</em>ual</td><td colspan=\"3\" rowspan=\"2\">ama<em>z</em>ona, o<em>z</em>ó, trape<em>z</em>i, na<em>z</em>isme,<br>bi<em>z</em>antí, esqui<em>z</em>ofrènia</td></tr><tr><td colspan=\"1\" rowspan=\"1\">entre vocals.</td></tr><tr><td colspan=\"1\" rowspan=\"3\"></td><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>z</em>:</u></td><td colspan=\"1\" rowspan=\"3\"></td><td colspan=\"3\" rowspan=\"3\"><em>z</em>àping, <em>z</em>ero, <em>z</em>inc, <em>z</em>oo, <em>z</em>ulú<br>pin<em>z</em>ell, ximpan<em>z</em>é, agut<em>z</em>il, sal<em>z</em>e</td><td colspan=\"3\" rowspan=\"3\">Els mots compostos amb <em>dins</em>, <em>trans</em><br>i <em>fons</em>: en<em>dins</em>ar, en<em>fons</em>ar,<br><em>trans</em>itar</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>―a</u> <u>principi</u> <u>de</u> <u>mot</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\">―entre consonant i vocal</td></tr></tbody></table></div><p><em>Remarques</em></p><p><em>a</em>) Hi ha plurals de mots masculins acabats en -<em>s</em> que s’escriuen amb <em>ss</em>, perquè són sords, i altres només<br>amb <em>s</em>, perquè són sonors.</p><p>pas  pa<em>ss</em>os (i pa<em>ss</em>ar, pa<em>ss</em>adís) pes  pe<em>s</em>os (i pe<em>s</em>ar, pe<em>s</em>ador)<br>gros  gro<em>ss</em>os (i gro<em>ss</em>a, engro<em>ss</em>ir) llis  lli<em>s</em>os (i lli<em>s</em>a, alli<em>s</em>ar)</p><p><em>b</em>) S’escriuen amb <em>ss</em> els femenins que acaben en -<em>essa</em>.</p><p>alcald<em>essa</em>, comt<em>essa</em>, duqu<em>essa</em>, metg<em>essa</em></p><p>Ara bé, acaben en -<em>esa</em>:</p><p>―els femenins següents: burg<em>esa</em>, marqu<em>esa</em>, pag<em>esa</em>, princ<em>esa</em><br>―els substantius abstractes derivats: riqu<em>esa</em>, trist<em>esa</em>, infant<em>esa</em><br>―els gentilicis: irland<em>esa</em>, ucraïn<em>esa</em>, roman<em>esa</em><br>―els participis: ent<em>esa</em>, em<em>esa</em>, at<em>esa</em></p><p><em>c</em>) Hi ha paraules que generalment pronunciem de manera incorrecta.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Cal pronunciar amb essa sonora</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Cal pronunciar amb essa sorda</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"3\" rowspan=\"1\">À<em>s</em>ia, Eu<em>s</em>ebi, Su<em>s</em>anna, a<em>s</em>il, pre<em>s</em>umpte, fa<em>s</em>e,<br>ca<em>s</em>ino, pai<em>s</em>atge, medu<em>s</em>a<br>Les paraules que acaben en -<em>si</em>: te<em>s</em>i, cri<em>s</em>i,<br>anàli<em>s</em>i, do<em>s</em>i</td><td colspan=\"3\" rowspan=\"1\">velo<em>c</em>itat, metge<em>ss</em>a, discu<em>ss</em>ió, agre<em>ss</em>ió, di<em>ss</em>eny,<br>impre<em>ss</em>ió</td></tr></tbody></table></div><p><em>d</em>) Finalment, i tal com hem dit, hi ha un seguit de paraules que sovint escrivim malament per influència<br>d’altres llengües romàniques.</p><p>Escrivim amb <em>s</em>/<em>ss</em>:</p><p>arrebossar carrossa Eivissa mostassa sucre<br>arrissar cassola embarassar pissarra tapís<br>arròs cervesa llapis ris tassa<br>barnús Còrsega massapà sabata tossut<br>basar dansa massís Saragossa tros<br>capatàs disfressa mosso sentinella vernís</p><p>Escrivim amb <em>z</em>:</p><p>alzina botzina donzella senzill zebra<br>benzina bronze pinzell ximpanzé zero</p></section>","topicNumber":"09"},{"id":"book-o10","title":"G/J (TG/TJ), IG/TX, X/IX","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"44–47","exercises":[{"id":"book-o10-ex1","number":"O10.1","title":"Classifiqueu les paraules següents segons el so que representen les grafies subratllades.","type":"open","bodyHtml":"<p>ba<u>ix</u>ar, co<u>ix</u>í, ra<u>tx</u>a, enve<u>j</u>a, <u>j</u>uny, pla<u>tj</u>a, mi<u>tj</u>ó, via<u>tg</u>e, estiue<u>ig</u>, to<u>tx</u>ana, passe<u>j</u>ar, à<u>g</u>il, <u>x</u>ifra, ra<u>ig</u>,<br><u>x</u>arop, llangarda<u>ix</u>, bo<u>g</u>eria, asse<u>tj</u>ament, lle<u>tj</u>a, esto<u>ig</u></p><p><u>sonen</u> <u>com</u> <u><em>x</em>oc</u> <u>sonen</u> <u>com</u> <u><em>j</em>oc</u> <u>sonen</u> <u>com</u> <u>me<em>t</em><em>x</em>a</u> <u>sonen</u> <u>com</u> <u>me<em>t</em><em>g</em>e</u></p>","sourcePage":46,"pdfPage":43,"solutionHtml":"<p>Sonen com <em>x</em>oc: ba<u>ix</u>ar, co<u>ix</u>í, <u>x</u>ifra, <u>x</u>arop, llangarda<u>ix</u><br>Sonen com <em>j</em>oc: enve<u>j</u>a, <u>j</u>uny, passe<u>j</u>ar, à<u>g</u>il, bo<u>g</u>eria<br>Sonen com me<em>tx</em>a: ra<u>tx</u>a, estiue<u>ig</u>, to<u>tx</u>ana, ra<u>ig</u>, esto<u>ig</u><br>Sonen com me<em>tg</em>e: pla<u>tj</u>a, mi<u>tj</u>ó, via<u>tg</u>e, asse<u>tj</u>ament, lle<u>tj</u>a</p>","book":true,"prompt":"","explanation":""},{"id":"book-o10-ex2","number":"O10.2","title":"Completeu amb j o g les paraules següents.","type":"open","bodyHtml":"<p>in__ecció __irafa tra__ecte tar__eta __espa<br>ma__estàtic __ueu ob__ecció presti__i __esuïta<br>__ibrell llet__es vi__ilant __eroglífic a__ermanar</p>","sourcePage":46,"pdfPage":43,"solutionHtml":"<p>in<strong>j</strong>ecció <strong>g</strong>irafa tra<strong>j</strong>ecte tar<strong>g</strong>eta <strong>g</strong>espa<br>ma<strong>j</strong>estàtic <strong>j</strong>ueu ob<strong>j</strong>ecció presti<strong>g</strong>i <strong>j</strong>esuïta<br><strong>g</strong>ibrell llet<strong>g</strong>es vi<strong>g</strong>ilant <strong>j</strong>eroglífic a<strong>g</strong>ermanar</p>","book":true,"prompt":"","explanation":""},{"id":"book-o10-ex3","number":"O10.3","title":"Completeu aquest embarbussament amb j/g/tj/tg i llegiu-lo en veu alta.","type":"open","bodyHtml":"<p>Setze ju__es d’un ju__at men__en fe__e d’un pen__at; si el pen__at es despen__és es<br>men__aria els setze fe__es dels setze ju__es que l’han ju__at.</p>","sourcePage":46,"pdfPage":43,"solutionHtml":"<p>Setze ju<strong>tg</strong>es d’un ju<strong>tj</strong>at men<strong>g</strong>en fe<strong>tg</strong>e d’un pen<strong>j</strong>at; si el pen<strong>j</strong>at es despen<strong>g</strong>és es men<strong>j</strong>aria els setze fe<strong>tg</strong>es dels setze<br>ju<strong>tg</strong>es que l’han ju<strong>tj</strong>at.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o10-ex4","number":"O10.4","title":"Escriviu un verb derivat de cadascun dels mots següents i completeu-los amb tx o ig (o g).","type":"open","bodyHtml":"<p>______________: desi__ ______________: rebu__ ______________: feste__<br>______________: empa__ ______________: passe__ ______________: xiuxiue__<br>______________: assa__ ______________: tirote__ ______________: sorte__<br>______________: bloque__ ______________: saque__ ______________: esqui__<br>______________: capri__ ______________: sonde__ ______________: trepi__</p>","sourcePage":46,"pdfPage":43,"solutionHtml":"<p>desitjar: desi<strong>g</strong> rebutjar: rebu<strong>ig</strong> festejar: feste<strong>ig</strong><br>empatxar: empa<strong>tx</strong> passejar: passe<strong>ig</strong> xiuxiuejar: xiuxiue<strong>ig</strong><br>assajar: assa<strong>ig</strong> tirotejar: tirote<strong>ig</strong> sortejar: sorte<strong>ig</strong><br>bloquejar: bloque<strong>ig</strong> saquejar: saque<strong>ig</strong> esquitxar: esqui<strong>tx</strong><br>encapritxar: capri<strong>tx</strong> sondejar: sonde<strong>ig</strong> trepitjar: trepi<strong>g</strong></p>","book":true,"prompt":"","explanation":""},{"id":"book-o10-ex5","number":"O10.5","title":"Escriviu el plural de les frases següents.","type":"open","bodyHtml":"<p>1. El boig que conduïa pel bosc tenia un cartutx de dinamita a punt per fer explotar.</p><p>2. El meu desig és tenir a casa un despatx molt espaiós.</p><p>3. Aquell home provoca mareig de tan lleig com és.</p>","sourcePage":46,"pdfPage":43,"solutionHtml":"<p>1. Els bojos/boigs que conduïen pels boscos/boscs tenien uns cartutxos de dinamita a punt per fer explotar.<br>2. Els meus desitjos/desigs són tenir a casa uns despatxos molt espaiosos.<br>3. Aquells homes provoquen marejos/mareigs de tan lletjos/lleigs com són.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o10-ex6","number":"O10.6","title":"Completeu amb ix o bé x les paraules següents.","type":"open","bodyHtml":"<p>__àfec e__emple pe__era xar__a fe__<br>e__èrcit rau__a fe__uc que__alada se__e<br>e__erit madu__ot co__ __imple se__anta<br>e__amen cala__era __arranca garbu__ __andall</p>","sourcePage":47,"pdfPage":44,"solutionHtml":"<p><strong>x</strong>àfec e<strong>x</strong>emple pe<strong>ix</strong>era xar<strong>x</strong>a fe<strong>ix</strong><br>e<strong>x</strong>èrcit rau<strong>x</strong>a fe<strong>ix</strong>uc que<strong>ix</strong>alada se<strong>x</strong>e<br>e<strong>ix</strong>erit madu<strong>ix</strong>ot co<strong>ix</strong> <strong>x</strong>imple se<strong>ix</strong>anta<br>e<strong>x</strong>amen cala<strong>ix</strong>era <strong>x</strong>arranca garbu<strong>ix</strong> <strong>x</strong>andall</p>","book":true,"prompt":"","explanation":""},{"id":"book-o10-ex7","number":"O10.7","title":"Completeu les sèries següents.","type":"open","bodyHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>citar</u></td><td colspan=\"1\" rowspan=\"1\"><u>cito</u></td><td colspan=\"1\" rowspan=\"1\"><u>cita</u></td><td colspan=\"1\" rowspan=\"1\"><u>citi</u></td><td colspan=\"1\" rowspan=\"1\"><u>cités</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>jutjar</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>repartir</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>annexar</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>dirigir</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>falsejar</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>rebaixar</u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div>","sourcePage":47,"pdfPage":44,"solutionHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>jutjo</u></td><td colspan=\"1\" rowspan=\"1\"><u>jutja</u></td><td colspan=\"1\" rowspan=\"1\"><u>jutgi</u></td><td colspan=\"1\" rowspan=\"1\"><u>jutgés</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>reparteixo</u></td><td colspan=\"1\" rowspan=\"1\"><u>reparteix</u></td><td colspan=\"1\" rowspan=\"1\"><u>reparteixi</u></td><td colspan=\"1\" rowspan=\"1\"><u>repartís</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>annexo</u></td><td colspan=\"1\" rowspan=\"1\"><u>annexa</u></td><td colspan=\"1\" rowspan=\"1\"><u>annexi</u></td><td colspan=\"1\" rowspan=\"1\"><u>annexés</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>dirigeixo</u></td><td colspan=\"1\" rowspan=\"1\"><u>dirigeix</u></td><td colspan=\"1\" rowspan=\"1\"><u>dirigeixi</u></td><td colspan=\"1\" rowspan=\"1\"><u>dirigís</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>falsejo</u></td><td colspan=\"1\" rowspan=\"1\"><u>falseja</u></td><td colspan=\"1\" rowspan=\"1\"><u>falsegi</u></td><td colspan=\"1\" rowspan=\"1\"><u>falsegés</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>rebaixo</u></td><td colspan=\"1\" rowspan=\"1\"><u>rebaixa</u></td><td colspan=\"1\" rowspan=\"1\"><u>rebaixi</u></td><td colspan=\"1\" rowspan=\"1\"><u>rebaixés</u></td></tr></tbody></table></div>","book":true,"prompt":"","explanation":""},{"id":"book-o10-ex8","number":"O10.8","title":"Completeu les frases següents amb j/g/tj/tg/ig/tx/ix/x.","type":"open","bodyHtml":"<p>1. El bo__í va arribar a mi__anit amb un __est d’intranquil·litat dibu__at a la cara.<br>2. Els __eranis de ma __ermana serviran per homena__ar la nostra mare.<br>3. Els diumen__es del mes de ma__ m’agrada __eure fins a l’hora de l’esbar__o.<br>4. A la botiga del __amfrà de casa venen unes corre__es i unes mi__es que fan prou go__.<br>5. Si jo fu__o i ell també fu__, segur que tu també acabaràs fu__int.<br>6. Cal tenir cora__e per allo__ar a l’hosta__eria del convent un salva__e com aquell.</p>","sourcePage":47,"pdfPage":44,"solutionHtml":"<p>1. El bo<strong>tx</strong>í va arribar a mi<strong>tj</strong>anit amb un <strong>g</strong>est d’intranquil·litat dibu<strong>ix</strong>at a la cara.<br>2. Els <strong>g</strong>eranis de ma <strong>g</strong>ermana serviran per homena<strong>tj</strong>ar la nostra mare.<br>3. Els diumen<strong>g</strong>es del mes de ma<strong>ig</strong> m’agrada <strong>j</strong>eure fins a l’hora de l’esbar<strong>j</strong>o.<br>4. A la botiga del <strong>x</strong>amfrà de casa venen unes corre<strong>tg</strong>es i unes mi<strong>tg</strong>es que fan prou go<strong>ig</strong>.<br>5. Si jo fu<strong>j</strong>o i ell també fu<strong>ig</strong>, segur que tu també acabaràs fu<strong>g</strong>int.<br>6. Cal tenir cora<strong>tg</strong>e per allo<strong>tj</strong>ar a l’hosta<strong>tg</strong>eria del convent un salva<strong>tg</strong>e com aquell.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o10-ex9","number":"O10.9","title":"Completeu aquest text amb j/g/tj/tg/ig/tx/ix/x.","type":"open","bodyHtml":"<p>El conductor del co__e blau, responsable principal del __oc d’ahir a mi__a tarda, és de<br>nacionalitat __eca, concretament de Praga, encara que té veïna__e civil a Catalunya. Es tracta<br>d’un home molt e__ut vestit amb un __ersei de color ro__ i que, __ust quan els Mossos<br>d’Esquadra van arribar per oferir el seu a__ut, estava a__agut a terra a causa d’un mare__,<br>encara que no van haver d’avisar cap me__e. L’automòbil del ciutadà estran__er presentava la<br>part davantera totalment a__afada.<br>Els a__ents van despa__ar ràpidament els tràmits perquè les parts van se__ellar un acord amb<br>una enca__ada.</p>","sourcePage":47,"pdfPage":44,"solutionHtml":"<p>El conductor del co<strong>tx</strong>e blau, responsable principal del <strong>x</strong>oc d’ahir a mi<strong>tj</strong>a tarda, és de nacionalitat <strong>tx</strong>eca, concretament<br>de Praga, encara que té veïna<strong>tg</strong>e civil a Catalunya. Es tracta d’un home molt e<strong>ix</strong>ut vestit amb un <strong>j</strong>ersei de color ro<strong>ig</strong> i<br>que, <strong>j</strong>ust quan els Mossos d’Esquadra van arribar per oferir el seu a<strong>j</strong>ut, estava a<strong>j</strong>agut a terra a causa d’un mare<strong>ig</strong>, encara<br>que no van haver d’avisar cap me<strong>tg</strong>e. L’automòbil del ciutadà estran<strong>g</strong>er presentava la part davantera totalment<br>a<strong>ix</strong>afada.<br>Els a<strong>g</strong>ents van despa<strong>tx</strong>ar ràpidament els tràmits perquè les parts van se<strong>g</strong>ellar un acord amb una enca<strong>ix</strong>ada.</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 44–47 · <a href=\"assets/llibre-b2-ortografia.pdf#page=41\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>G/J (TG/TJ), IG/TX, X/IX</h3><p>Les grafies destacades d’aquests mots representen sons tan similars que a vegades fins i tot es confonen.</p><p><em>j</em>oc ― <em>x</em>oc<br><em>g</em>ec ― <em>x</em>ec ― <em>tx</em>ec<br>me<em>tg</em>e ― me<em>tx</em>a</p><p>Per saber com cal escriure aquests sons, agrupem les grafies segons el so que els correspon.</p><p><u><em>g</em><em>/</em><em>j</em></u> <u>pa<em>g</em>ès,</u> <u><em>J</em>oan</u> <u><em>i</em><em>g</em><em>/</em><em>t</em><em>x</em></u> <u>bo<em>i</em><em>g</em>,</u> <u><em>T</em><em>x</em>èquia</u></p><p><u><em>t</em><em>g</em><em>/</em><em>t</em><em>j</em></u> <u>fet<em>g</em>e,</u> <u>plat<em>j</em>a</u> <u><em>x</em><em>/</em><em>i</em><em>x</em></u> <u><em>x</em>iular,</u> <u>co<em>i</em><em>x</em></u></p><h3>G/J i TG/TJ</h3><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Exemples</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Excepcions</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>j</em></u> <u>al</u> <u>davant</u><br><u>de</u> <u><em>a</em>,</u> <u><em>o</em>,</u> <u><em>u</em>.</u></td><td colspan=\"3\" rowspan=\"1\"><em>j</em>ardí, men<em>j</em>ar<br><em>j</em>ove, ra<em>j</em>olí<br><em>j</em>uvenil, a<em>j</em>uda</td><td colspan=\"3\" rowspan=\"2\"><em>a</em>) Els mots amb els grups -<em>jecc-</em> i -<em>ject-</em>: in<em>jecc</em>ió, in<em>ject</em>ar,<br>ob<em>jecc</em>ió, o<em>bject</em>ar, pro<em>jecci</em>ó, tra<em>ject</em>òria<br><em>b</em>) Totes les formes del verb <em>jeure</em>: <em>j</em>ec, <em>j</em>eus, <em>j</em>eu, <em>j</em>èiem<br><em>c</em>) Mots propis d’origen bíblic i derivats: <em>J</em>esús, <em>J</em>esucrist,<br><em>J</em>eremies, <em>J</em>ehovà, <em>J</em>erusalem, <em>j</em>esuïta<br><em>d</em>) Altres mots, com ara: <em>j</em>erarquia, <em>j</em>ersei, ma<em>j</em>estat, <em>j</em>eroglífic</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Escrivim</u> <u><em>g</em></u> <u>al</u> <u>davant</u><br><u>de</u> <u><em>e</em>,</u> <u><em>i</em>.</u></td><td colspan=\"3\" rowspan=\"1\"><em>g</em>ener, men<em>g</em>en<br><em>g</em>irafa, mà<em>g</em>ic</td></tr></tbody></table></div><p><em>Remarques</em></p><p><em>a</em>) Cal tenir en compte l’alternança <em>j</em>/<em>g</em> en les paraules d’una mateixa família o quan conjuguem un verb.<br>Aquesta alternança també afecta els grups <em>tj</em>/<em>tg</em>.</p><p><u>Alternança</u> <u><em>j</em>/<em>g</em></u> <u>Alternança</u> <u><em>t</em><em>j</em>/<em>t</em><em>g</em></u><br>bo<em>j</em>a, bo<em>g</em>es, bo<em>j</em>os, bo<em>g</em>eria plat<em>j</em>a, plat<em>g</em>eta, plat<em>j</em>ola<br>pen<em>j</em>o, pen<em>g</em>es, pen<em>j</em>a, pen<em>g</em>em, pen<em>g</em>eu, pen<em>g</em>en jut<em>j</em>o, jut<em>g</em>es, jut<em>j</em>a, jut<em>g</em>em, jut<em>g</em>eu, jut<em>g</em>en</p><p><em>b</em>) Cal anar amb compte a pronunciar correctament el so de la <em>j</em> o de la <em>g</em> de les paraules següents:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"3\" rowspan=\"1\"><u>No</u> <u>s’han</u> <u>de</u> <u>pronunciar</u> <u>amb</u> <u><em>i</em>.</u></td><td colspan=\"1\" rowspan=\"1\">ma<em>j</em>úscula, <em>j</em>aciment, pro<em>j</em>ectil, <em>j</em>uxtaposar, pa<em>g</em>ès,<br><u>jut<em>g</em>e,</u> <u>in<em>j</em>ecció,</u> <u>pro<em>j</em>ecte,</u> <u>tra<em>j</em>ecte,</u> <u><em>g</em>essamí</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">No s’han de pronunciar amb <em>g</em> de <em>gat</em>.</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">ven<em>j</em>ar, ven<em>j</em>ança, distin<em>g</em>ir, extin<em>g</em>ir, bur<em>g</em>ès</td></tr><tr><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"1\"><u>No</u> <u>s’han</u> <u>de</u> <u>pronunciar</u> <u>amb</u> <u>el</u> <u>so</u> <u>de</u> <u>la</u> <u><em>j</em></u> <u>del</u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\">pi<em>j</em>ama, <em>J</em>úpiter, <em>g</em>elatina, <em>j</em>ota, <em>j</em>ungla, <em>g</em>eografia,<br><u><em>g</em>irafa,</u> <u><em>g</em>el</u> <u>(de</u> <u>bany)</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\">castellà.</td></tr></tbody></table></div><p><em>c</em>) El verb <em>suggerir</em> i les paraules que en deriven s’escriuen amb <em>gg</em>: su<em>gg</em>erir, su<em>gg</em>eriment, su<em>gg</em>eridor...</p><h3>IG/TX</h3><p>Les grafies <em>ig</em> i <em>tx</em> representen el mateix so quan són a final de mot.</p><p>bate<em>ig</em>, bo<em>ig</em><br>cartu<em>tx</em>, despa<em>tx</em></p><p>En cas de dubte sobre l’ortografia d’aquests mots, els seus derivats ens indiquen amb quines lletres<br>s’han d’escriure.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"3\" rowspan=\"1\"><u>El</u> <u>grup</u> <u><em>i</em><em>g</em></u> <u>alterna</u> <u>amb</u> <u><em>g</em><em>/</em><em>j</em></u> <u>o</u> <u><em>t</em><em>g</em><em>/</em><em>t</em><em>j</em></u><br>en els derivats.</td><td colspan=\"1\" rowspan=\"1\">bate<em>ig</em>  bate<em>j</em>ar<br>bo<em>ig</em>  bo<em>g</em>eria<br>m<em>ig</em>  mi<em>tj</em>ana<br>lle<em>ig</em>  lle<em>tg</em>esa/llet<em>j</em>or</td></tr><tr><td colspan=\"1\" rowspan=\"2\"><u>E</u><br>e</td><td colspan=\"1\" rowspan=\"1\"><u>El</u> <u>grup</u> <u><em>t</em><em>x</em></u> <u>alterna</u> <u>amb</u> <u>-<em>t</em><em>x</em><em>-</em></u></td><td colspan=\"1\" rowspan=\"2\"></td><td colspan=\"1\" rowspan=\"2\">escabe<em>tx</em>  escabe<em>tx</em>ada<br>despa<em>tx</em>  despa<em>tx</em>ar</td></tr><tr><td colspan=\"1\" rowspan=\"1\">en els derivats.</td></tr></tbody></table></div><p><em>Remarques</em></p><p><em>a</em>) No hi ha cap paraula que acabi en -<em>tg</em> o -<em>tj</em>.</p><p><em>b</em>) Les paraules que acaben en -<em>ig</em> fan el plural afegint -<em>s</em> o bé -<em>os</em> al singular.</p><p>bateig<em>s</em> / bate<em>jos</em> mig<em>s</em> / mi<em>tjos</em><br>boig<em>s</em> / bo<em>jos</em> lleig<em>s</em> / lle<em>tjos</em></p><p>En el plural acabat en -<em>os</em> escriurem <em>j</em> o <em>tj</em>, d’acord amb la pronúncia. Així mateix, també podem<br>prendre com a referència una paraula derivada.</p><p>bateig / bate<em>j</em>ar / bate<em>j</em>os<br>boig / bo<em>g</em>eria / bo<em>j</em>os<br>mig / mi<em>tj</em>ana / mi<em>tj</em>os<br>lleig / lle<em>tg</em>esa / lle<em>tj</em>os</p><p><em>c</em>) Les paraules que acaben en -<em>tx</em> fan el plural afegint -<em>os</em> al singular, com ara <em>cartutxos</em> o <em>despatxos</em>.</p><h3>X/IX</h3><p>La lletra <em>x</em> representa diversos sons.</p><p>ta<em>x</em>i, fi<em>x</em>, e<em>x</em>plotar e<em>x</em>amen, e<em>x</em>emple, he<em>x</em>àgon madu<em>ix</em>a, <em>x</em>iclet, car<em>x</em>ofa</p><p>Per escriure el so de madu<em>ix</em>a, <em>x</em>iclet o car<em>x</em>ofa tenim la grafia <em>x</em> i el dígraf <em>ix</em>.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"3\" rowspan=\"2\"><u>Escrivim</u> <u><em>x</em></u></td><td colspan=\"1\" rowspan=\"1\">A començament de paraula i darrere<br>de consonant</td><td colspan=\"1\" rowspan=\"1\"><em>x</em>al, <em>x</em>erès, <em>x</em>iroi, <em>x</em>ofer, <em>x</em>umet<br>or<em>x</em>ata, pan<em>x</em>eta, ar<em>x</em>iu, tron<em>x</em>o, pan<em>x</em>ut</td></tr><tr><td colspan=\"1\" rowspan=\"1\">Darrere de la vocal <em>i</em> i darrere del<br><u>diftong</u> <u>decreixent</u> <u><em>a</em><em>u</em></u></td><td colspan=\"1\" rowspan=\"1\">gui<em>x</em>, bi<em>x</em>est, Fli<em>x,</em> cli<em>x</em>é<br>disbau<em>x</em>a, xau<em>x</em>a, rau<em>x</em>a</td></tr><tr><td colspan=\"1\" rowspan=\"1\">E</td><td colspan=\"1\" rowspan=\"1\">Escrivim <em>ix</em></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Darrere de vocal</td><td colspan=\"1\" rowspan=\"1\">fa<em>ix</em>a, lle<em>ix</em>a, bo<em>ix</em> (arbust), gru<em>ix</em>ut</td></tr></tbody></table></div><p><em>Remarca</em></p><p>Les paraules següents s’escriuen i es pronuncien amb <em>s</em>, no amb <em>x</em>:</p><p>e<em>s</em>tranger, e<em>s</em>polsar, e<em>s</em>trany, e<em>s</em>tendre, e<em>s</em>prémer, e<em>s</em>tricte</p></section>","topicNumber":"10"},{"id":"book-o11","title":"M/N","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"48–50","exercises":[{"id":"book-o11-ex1","number":"O11.1","title":"Completeu les paraules següents amb m o n i classifiqueu-les.","type":"open","bodyHtml":"<p>mi__var, co__vivència, a__fibi, co__mutar, co__binació, a__pliar, circu__ferència,<br>pri__mirat, rebo__bori, e__và, co__plidor, e__bús, co__moció, aca__pada, parani__f</p><p><u><em>m</em><em>b</em></u> <u><em>m</em><em>p</em></u> <u><em>m</em><em>m</em></u> <u><em>m</em><em>f</em></u> <u><em>n</em><em>v</em></u></p>","sourcePage":49,"pdfPage":46,"solutionHtml":"<p>mb: co<strong>m</strong>binació, rebo<strong>m</strong>bori, e<strong>m</strong>bús<br>mp: a<strong>m</strong>pliar, co<strong>m</strong>plidor, aca<strong>m</strong>pada<br>mm: co<strong>m</strong>mutar, pri<strong>m</strong>mirat, co<strong>m</strong>moció<br>mf: a<strong>m</strong>fibi, circu<strong>m</strong>ferència, parani<strong>m</strong>f<br>nv: mi<strong>n</strong>var, co<strong>n</strong>vivència, e<strong>n</strong>và</p>","book":true,"prompt":"","explanation":""},{"id":"book-o11-ex2","number":"O11.2","title":"Completeu les paraules següents amb m o n.","type":"open","bodyHtml":"<p>i__fermera co__fusió i__munitzar a__baixada i__pressionant<br>e__mig e__mudir a__fitrió co__vidar co__fessar<br>co__ferència e__filar e__farfegar e__balar a__fiteatre<br>e__veja fla__ o__bra i__putar e__feinat</p>","sourcePage":49,"pdfPage":46,"solutionHtml":"<p>i<strong>n</strong>fermera co<strong>n</strong>fusió i<strong>m</strong>munitzar a<strong>m</strong>baixada i<strong>m</strong>pressionant<br>e<strong>n</strong>mig e<strong>m</strong>mudir a<strong>m</strong>fitrió co<strong>n</strong>vidar co<strong>n</strong>fessar<br>co<strong>n</strong>ferència e<strong>n</strong>filar e<strong>n</strong>farfegar e<strong>m</strong>balar a<strong>m</strong>fiteatre<br>e<strong>n</strong>veja fla<strong>m</strong> o<strong>m</strong>bra i<strong>m</strong>putar e<strong>n</strong>feinat</p>","book":true,"prompt":"","explanation":""},{"id":"book-o11-ex3","number":"O11.3","title":"Completeu els mots següents amb im o in.","type":"open","bodyHtml":"<p>___batut ___prudent ___fal·lible ___mortal ___mutable<br>___feliç ___perfecte ___pacient ___potència ___tolerància<br>___madur ___fidel ___voluntari ___finit ___material</p>","sourcePage":49,"pdfPage":46,"solutionHtml":"<p><strong>im</strong>batut <strong>im</strong>prudent <strong>in</strong>fal·lible <strong>im</strong>mortal <strong>im</strong>mutable<br><strong>in</strong>feliç <strong>im</strong>perfecte <strong>im</strong>pacient <strong>im</strong>potència <strong>in</strong>tolerància<br><strong>im</strong>madur <strong>in</strong>fidel <strong>in</strong>voluntari <strong>in</strong>finit <strong>im</strong>material</p>","book":true,"prompt":"","explanation":""},{"id":"book-o11-ex4","number":"O11.4","title":"Completeu aquests verbs derivats amb em o en.","type":"open","bodyHtml":"<p>petit  ___petitir dolç  ___dolcir fang  ___fangar<br>barca  ___barcar boig  ___bogir gran ___grandir<br>fosc  ___fosquir marc  ___marcar fons  ___fonsar<br>malalt  ___malaltir car  ___carir mordassa  ___mordassar</p>","sourcePage":50,"pdfPage":47,"solutionHtml":"<p><strong>em</strong>petitir <strong>en</strong>dolcir <strong>en</strong>fangar<br><strong>em</strong>barcar <strong>em</strong>bogir <strong>en</strong>grandir<br><strong>en</strong>fosquir <strong>em</strong>marcar <strong>en</strong>fonsar<br><strong>em</strong>malaltir <strong>en</strong>carir <strong>em</strong>mordassar</p>","book":true,"prompt":"","explanation":""},{"id":"book-o11-ex5","number":"O11.5","title":"Completeu les frases següents amb compte, conte o comte.","type":"open","bodyHtml":"<p>1. Cal anar molt amb __________________ de no bloquejar el __________________ corrent de<br>la part actora.<br>2. El seu besavi era el __________________ del castell.<br>3. La protagonista del _________________ de fades vivia amb un __________________.<br>4. Tingueu en __________________ que el processat no va pagar el __________________ de<br>l’hotel on s’allotjava.</p>","sourcePage":50,"pdfPage":47,"solutionHtml":"<p>1. Cal anar molt amb <strong>compte</strong> de no bloquejar el <strong>compte</strong> corrent de la part actora.<br>2. El seu besavi era el <strong>comte</strong> del castell.<br>3. La protagonista del <strong>conte</strong> de fades vivia amb un <strong>comte</strong>.<br>4. Tingueu en <strong>compte</strong> que el processat no va pagar el <strong>compte</strong> de l’hotel on s’allotjava.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o11-ex6","number":"O11.6","title":"Empleneu els buits de les frases següents amb la paraula corresponent.","type":"open","bodyHtml":"<p>pinyol, estany, codonyat, parany, espardenya, esmunyir, banyes, empenyorar, escopinyes,<br>constrenyiment, carmanyola</p><p>1. Quin decret regula la recaptació per via de _____________ d’aquestes sancions?<br>2. La truita es va _____________ per no caure en un _____________.<br>3. Per pagar els deutes va _____________ l’anell de l’àvia i unes _____________ de cérvol de<br>l’avi.<br>4. Sempre s’emporta el dinar en una _____________. Avui du amanida amb _____________ i<br>olives sense _____________ i, per postres, formatge amb _____________.<br>5. Li falta una _____________ i ara s’ha de remullar mig descalç en aquest _____________.</p>","sourcePage":50,"pdfPage":47,"solutionHtml":"<p>1. Quin decret regula la recaptació per via de <strong>constrenyiment</strong> d’aquestes sancions?<br>2. La truita es va <strong>esmunyir</strong> per no caure en un <strong>parany</strong>.<br>3. Per pagar els deutes va <strong>empenyorar</strong> l’anell de l’àvia i unes <strong>banyes</strong> de cérvol de l’avi.<br>4. Sempre s’emporta el dinar en una <strong>carmanyola</strong>. Avui du amanida amb <strong>escopinyes</strong> i olives sense <strong>pinyol</strong> i, per postres,<br>formatge amb <strong>codonyat</strong>.<br>5. Li falta una <strong>espardenya</strong> i ara s’ha de remullar mig descalç en aquest <strong>estany</strong>.</p>","book":true,"prompt":"","explanation":""},{"id":"book-o11-ex7","number":"O11.7","title":"Completeu les frases següents amb m/n/ny/mm/nn/mp.","type":"open","bodyHtml":"<p>1. Em vaig quedar i___òbil quan vaig trobar-me el ca___pió de boxa al tra___via.<br>2. El fiscal va quedar fet un ___ap quan va saber que eres i___ocent en aquell assu___te.<br>3. Els co___fits i els carqui___olis de la pastisseria del xa___frà són i___ensos, massa grans per<br>al meu gust.<br>4. És un mal sí___toma que hagis perdut la co___fiança en aquestes circu___stàncies.<br>5. L’atleta va encaixar el trio___f del rival amb un so___riure vergo___ós.<br>6. Per co___emorar l’aniversari de l’entitat, l’orquestra si___fònica va interpretar l’himne amb<br>tot l’è___fasi que permetia el moment.<br>7. Quan explico co___tes en públic, se m’i___fla la pa___xa perquè soc un ma___oc de nervis.<br>8. Estic co___ogut pel refra___ que acaba de dir l’A___a.<br>9. Els bo___bers van arribar de manera i___ediata a l’ate___tat contra la impre___ta.<br>10. El co___te va aportar diners del seu co___te corrent per fer realitat el seu so___ni<br>e___presarial.</p>","sourcePage":50,"pdfPage":47,"solutionHtml":"<p>1. Em vaig quedar i<strong>mm</strong>òbil quan vaig trobar-me el ca<strong>m</strong>pió de boxa al tra<strong>m</strong>via.<br>2. El fiscal va quedar fet un <strong>ny</strong>ap quan va saber que eres i<strong>nn</strong>ocent en aquell assu<strong>mp</strong>te.<br>3. Els co<strong>n</strong>fits i els carqui<strong>ny</strong>olis de la pastisseria del xa<strong>m</strong>frà són i<strong>mm</strong>ensos, massa grans per al meu gust.<br>4. És un mal sí<strong>mp</strong>toma que hagis perdut la co<strong>n</strong>fiança en aquestes circu<strong>m</strong>stàncies.<br>5. L’atleta va encaixar el trio<strong>m</strong>f del rival amb un so<strong>m</strong>riure vergo<strong>ny</strong>ós.<br>6. Per co<strong>mm</strong>emorar l’aniversari de l’entitat, l’orquestra si<strong>m</strong>fònica va interpretar l’himne amb tot l’è<strong>m</strong>fasi que permetia<br>el moment.<br>7. Quan explico co<strong>n</strong>tes en públic, se m’i<strong>n</strong>fla la pa<strong>n</strong>xa perquè soc un ma<strong>ny</strong>oc de nervis.<br>8. Estic co<strong>mm</strong>ogut pel refra<strong>ny</strong> que acaba de dir l’A<strong>nn</strong>a.<br>9. Els bo<strong>m</strong>bers van arribar de manera i<strong>mm</strong>ediata a l’ate<strong>mp</strong>tat contra la impre<strong>m</strong>ta.<br>10. El co<strong>m</strong>te va aportar diners del seu co<strong>mp</strong>te corrent per fer realitat el seu so<strong>m</strong>ni e<strong>m</strong>presarial.</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 48–50 · <a href=\"assets/llibre-b2-ortografia.pdf#page=45\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>M/N</h3><p>Les grafies <em>m</em> i <em>n</em> no presenten cap dificultat quan van al davant de vocal. Ara bé, quan van al davant<br>d’algunes consonants poden ocasionar problemes.</p><p>T’ho pots e<em>m</em>provar si no ho vols ca<em>n</em>viar.<br>Aquest i<em>nv</em>ent és i<em>m</em>millorable.</p><p>Normes que resolen casos en què <em>m</em> i <em>n</em> sonen igual:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Exemples</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Excepcions</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"3\" rowspan=\"1\"><u>Escrivim</u> <u><em>m</em></u></td><td colspan=\"3\" rowspan=\"1\"><u>Davant</u> <u><em>b</em>,</u> <u><em>p</em>,</u> <u><em>m</em>,</u> <u><em>f</em></u></td><td colspan=\"3\" rowspan=\"1\">e<em>m</em>bellir, o<em>m</em>bra, to<em>m</em>bar<br>co<em>m</em>provar, i<em>m</em>près<br>i<em>m</em>mòbil, e<em>m</em>magatzemar<br>à<em>m</em>fora, sa<em>m</em>faina</td><td colspan=\"3\" rowspan=\"1\">e<em>n</em>mig, ta<em>n</em>mateix<br>Escrivim <em>n</em> davant de la <em>f</em> en els mots<br>formats amb els prefixos <em>con</em>-, <em>en-</em>, <em>in-</em>:<br>co<em>n</em>fit, e<em>n</em>fonsar, i<em>n</em>forme</td></tr><tr><td colspan=\"1\" rowspan=\"1\">E</td><td colspan=\"1\" rowspan=\"1\">Escrivim <em>n</em></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">D</td><td colspan=\"1\" rowspan=\"1\">Davant <em>v</em></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"3\" rowspan=\"1\">co<em>n</em>veni, e<em>n</em>verinar</td><td colspan=\"3\" rowspan=\"1\">tra<em>m</em>via, triu<em>m</em>vir</td></tr></tbody></table></div><p><em>Remarques</em></p><p><em>a</em>) Cal escriure <em>im</em>-, i no pas <em>in</em>-, en fer el contrari d’una paraula que comença per <em>b-</em>, <em>m-</em> o <em>p-</em>: i<em>m</em>bevible,<br>i<em>m</em>moral, i<em>m</em>perfecte.<br>Així mateix, cal escriure <em>em</em>-, i no pas <em>en</em>-, en fer un verb derivat d’una paraula que comença per <em>b-</em>, <em>m-</em> o<br><em>p-</em>: e<em>m</em>barcar, e<em>m</em>marcar, e<em>m</em>pedrar.</p><p><em>b</em>) Les paraules <em>comte</em>, <em>compte</em> i <em>conte</em>:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\">comte</td><td colspan=\"1\" rowspan=\"1\">El títol de <em>comte</em> està per damunt del de <em>vescomte</em> i per sota del de <em>marquès</em>.</td></tr><tr><td colspan=\"1\" rowspan=\"1\">compte</td><td colspan=\"1\" rowspan=\"1\">He perdut el <em>compte</em> de les trucades que he fet aquest vespre.<br>Ves amb <em>compte</em> de no caure!<br>El magistrat ha disposat que se li cancel·li el <em>compte</em> corrent.<br>Porti’m el <em>compte</em>, si us plau.</td></tr><tr><td colspan=\"1\" rowspan=\"1\">conte</td><td colspan=\"1\" rowspan=\"1\">Tenim el costum d’explicar-li un <em>conte</em> abans d’anar a dormir.</td></tr></tbody></table></div><p><em>c</em>) El dígraf <em>ny</em> representa el fonema que en basc i en castellà s’escriu amb <em>ñ</em>; en francès i en italià, amb <em>gn</em>;<br>i en portuguès i en occità, amb <em>nh</em>. L’escriptura del dígraf <em>ny</em> no presenta cap complicació, però quan el<br>trobem a final de mot pot dificultar-ne la pronúncia.</p><p>pu<em>ny</em>, llu<em>ny</em>, esborra<em>ny</em>, a<em>ny</em>, para<em>ny</em></p><p>Cal recordar que, en separar les síl·labes d’un mot, no es poden separar les dues lletres que el formen.</p><p>ca-<em>ny</em>a, mun-ta-<em>ny</em>a, pi-<em>ny</em>a, as-se-<em>ny</em>a-lar</p><p><em>d</em>) Escrivim amb <em>m</em> paraules com ara:</p><p>impre<em>m</em>ta, empre<em>m</em>ta, pre<em>m</em>sa, so<em>m</em>riure</p><p><em>e</em>) També escrivim <em>m</em> en els prefixos <em>amfi-</em> i <em>circum-</em>:</p><p><em>amfi</em>teatre, <em>amfi</em>bi, <em>circum</em>ferència, <em>circum</em>val·lació</p><p><em>f</em>) Dupliquen la consonant les paraules següents:</p><p>mm: ga<em>mm</em>a, Ge<em>mm</em>a<br>nn: A<em>nn</em>a, a<em>nn</em>ex, co<em>nn</em>ectar, i<em>nn</em>ocent, Susa<em>nn</em>a</p><p><em>g</em>) Cal escriure <em>mp</em> en algunes paraules encara que la <em>p</em> sigui muda.</p><p>ate<em>mp</em>tat, ca<em>mp</em>, co<em>mp</em>te, exe<em>mp</em>t, pro<em>mp</em>te, rede<em>mp</em>tor, sí<em>mp</em>toma, te<em>mp</em>s, te<em>mp</em>tar</p></section>","topicNumber":"11"},{"id":"book-o12","title":"R/RR","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"51–52","exercises":[{"id":"book-o12-ex1","number":"O12.1","title":"Digueu si el so de les r en cursiva és simple, múltiple o mut.","type":"open","bodyHtml":"<p>aclari<em>r</em>: pa<em>r</em>la: que<em>r</em>ella:<br>bu<em>r</em>illa: contra<em>r</em>estar: xiva<em>rr</em>i:<br>supra<em>r</em>enal: sabate<em>r</em>: flo<em>r</em>s:</p>","sourcePage":52,"pdfPage":49,"solutionHtml":"<p>aclari<strong>r</strong>: mut pa<strong>r</strong>la: múltiple que<strong>r</strong>ella: simple<br>bu<strong>r</strong>illa: simple contra<strong>r</strong>estar: múltiple xiva<strong>rr</strong>i: múltiple<br>supra<strong>r</strong>enal: múltiple sabate<strong>r</strong>: mut flo<strong>r</strong>s: mut</p>","book":true,"prompt":"","explanation":""},{"id":"book-o12-ex2","number":"O12.2","title":"Escriviu la forma d’infinitiu dels verbs següents.","type":"open","bodyHtml":"<p>dúieu: depenc: resolc:<br>venen: bato: estrenyem:<br>presumia: caic: perceps:<br>concloem: recorria: apreníem:</p>","sourcePage":52,"pdfPage":49,"solutionHtml":"<p>dur dependre resoldre<br>vendre/venir/vindre batre estrènyer<br>presumir caure percebre<br>concloure recórrer aprendre</p>","book":true,"prompt":"","explanation":""},{"id":"book-o12-ex3","number":"O12.3","title":"Escriviu, amb accent o r final, si cal, el mot primitiu del qual deriva cada paraula. Ex.: estrangeria: estranger","type":"open","bodyHtml":"<p>poruc: finor: comissionista:<br>primeria: coixinera: maduresa:<br>empitjorar: comunitat: balconada:<br>funcionari: frenar: cigronet:</p>","sourcePage":52,"pdfPage":49,"solutionHtml":"<p>por fi comissió<br>primer coixí madur<br>pitjor comú balcó<br>funció fre cigró</p>","book":true,"prompt":"","explanation":""},{"id":"book-o12-ex4","number":"O12.4","title":"Formeu un substantiu acabat en -r a partir de cadascun d’aquests mots. Ex.: fosc: foscor","type":"open","bodyHtml":"<p>buit: gris: venda:<br>negre: forn: pastís:<br>sabata: avió: fang:<br>cendra: cirera: carn:</p>","sourcePage":52,"pdfPage":49,"solutionHtml":"<p>buidor grisor venedor<br>negror forner pastisser<br>sabater aviador fangar<br>cendrer cirerer carnisser</p>","book":true,"prompt":"","explanation":""},{"id":"book-o12-ex5","number":"O12.5","title":"Als espais buits dels mots de les frases següents, escriviu-hi r o bé accentueu la vocal corresponent, segons el que calgui.","type":"open","bodyHtml":"<p>1. No se__ si ahi__ passa__ el camio__ de l’Agusti__ en fer-se cla__.<br>2. Els cànti__s estrange__s es trenquen de seguida.<br>3. El perruque__ del meu carre__ m’ha regalat un ram de flo__s.<br>4. El botigue__ llença__ el colla__ del gos.<br>5. Va posa__ com a condicio__ ana__ al vago__ dels no fumado__s.<br>6. És prou madu__ per sabe__ si li farà mal tant de cafe__.<br>7. El clixe__ de solte__ madu__ no t’acaba__ d’encaixa__.<br>8. Potse__ al mes de gene__ no sera__ tan ple com a la tardo__.<br>9. El venedo__ es deixa__ l’encenedo__ damunt del llum de buta__.<br>10. Atencio__ al llogue__! De comissio__, ni parlar-ne.</p>","sourcePage":52,"pdfPage":49,"solutionHtml":"<p>1. No s<strong>é</strong> si ahi<strong>r</strong> pass<strong>à</strong> el cami<strong>ó</strong> de l’Agust<strong>í</strong> en fer-se cla<strong>r</strong>.<br>2. Els cànti<strong>r</strong>s estrange<strong>r</strong>s es trenquen de seguida.<br>3. El perruque<strong>r</strong> del meu carre<strong>r</strong> m’ha regalat un ram de flo<strong>r</strong>s.<br>4. El botigue<strong>r</strong> llenç<strong>à</strong> el colla<strong>r</strong> del gos.<br>5. Va posa<strong>r</strong> com a condici<strong>ó</strong> ana<strong>r</strong> al vag<strong>ó</strong> dels no fumado<strong>r</strong>s.<br>6. És prou madu<strong>r</strong> per sabe<strong>r</strong> si li farà mal tant de caf<strong>è</strong>.<br>7. El clix<strong>é</strong> de solte<strong>r</strong> madu<strong>r</strong> no t’acab<strong>à</strong> d’encaixa<strong>r</strong>.<br>8. Potse<strong>r</strong> al mes de gene<strong>r</strong> no ser<strong>à</strong> tan ple com a la tardo<strong>r</strong>.<br>9. El venedo<strong>r</strong> es deix<strong>à</strong> l’encenedo<strong>r</strong> damunt del llum de but<strong>à</strong>.<br>10. Atenci<strong>ó</strong> al llogue<strong>r</strong>! De comissi<strong>ó</strong>, ni parlar-ne.</p>","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 51–52 · <a href=\"assets/llibre-b2-ortografia.pdf#page=48\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>R/RR</h3><p>La lletra <em>r</em> pot representar dos sons diferents, el simple i el múltiple.</p><p>ca<em>r</em>ota, co<em>r</em>all, ge<em>r</em>ent, comissa<em>r</em>ia, pa<em>r</em>e, pe<em>r</em>ill<br><em>r</em>ata, <em>r</em>evenda, <em>r</em>oca, en<em>r</em>aono, con<em>r</em>eu</p><p>A l’hora d’escriure’ls només la erra múltiple ofereix una certa dificultat, ja que es pot escriure de dues<br>maneres: amb <em>r</em> o <em>rr</em>.</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"3\" rowspan=\"2\"><u>Escrivim</u> <u><em>r</em></u></td><td colspan=\"1\" rowspan=\"1\">A</td><td colspan=\"1\" rowspan=\"1\">A començament de mot</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><em>r</em>atificació, <em>r</em>iquesa, <em>r</em>ossinyol</td></tr><tr><td colspan=\"1\" rowspan=\"1\">D</td><td colspan=\"1\" rowspan=\"1\">Darrere de consonant</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">fol<em>r</em>e, som<em>r</em>ient, Man<em>r</em>esa</td></tr><tr><td colspan=\"1\" rowspan=\"1\">E</td><td colspan=\"1\" rowspan=\"1\">Escrivim <em>rr</em></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">E</td><td colspan=\"1\" rowspan=\"1\">Entre vocals</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">esbo<em>rr</em>any, incó<em>rr</em>er, a<em>rr</em>est</td></tr></tbody></table></div><p><em>Remarques</em></p><p><em>a</em>) No escrivim <em>rr</em> en paraules derivades i compostes com ara auto<em>r</em>etrat, multi<em>r</em>acial, contra<em>r</em>estar o<br>anti<em>r</em>eligiós.</p><p><em>b</em>) En la majoria dels mots la erra final no sona, llevat de casos com ara amo<em>r</em>, co<em>r</em>, ma<em>r</em>, fa<em>r</em>... Aquest fet<br>comporta sovint problemes ortogràfics.</p><p>S’escriuen amb <em>r</em> final:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Exemples</td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\">Excepcions</td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>infinitius</u> <u>dels</u> <u>verbs</u></td><td colspan=\"3\" rowspan=\"1\">lliura<em>r</em>, córre<em>r</em>, fugi<em>r</em>, espera<em>r</em>, téme<em>r</em></td><td colspan=\"3\" rowspan=\"1\">Els infinitius dels verbs de la 2a<br>conjugació que acaben en<br>-<em>re</em>: mou<em>r</em>e, cau<em>r</em>e, viu<em>r</em>e</td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>primitius</u> <u>de</u> <u>mots</u> <u>derivats</u><br><u>en</u> <u>què</u> <u>apareix</u> <u>una</u> <u><em>r</em></u></td><td colspan=\"3\" rowspan=\"1\">carrer  carre<em>r</em>ó<br>clar  cla<em>r</em>ejar<br>paper  pape<em>r</em>era<br>por  po<em>r</em>uc<br>flor  flo<em>r</em>ir</td><td colspan=\"3\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>Els</u> <u>mots</u> <u>acabats</u> <u>amb</u> <u>aquests</u><br><u>sufixos</u> <u>de</u> <u>derivació</u></td><td colspan=\"3\" rowspan=\"1\"><em>-ar</em>: alzin<em>ar</em>, besti<em>ar</em>, colom<em>ar</em><br>llind<em>ar</em>, platan<em>ar</em><br>-<em>er</em>: ametll<em>er</em>, clau<em>er</em>, fust<em>er</em><br>fem<em>er</em>, mentid<em>er</em><br>-<em>or</em>: blav<em>or</em>, escalf<em>or</em>, mar<em>or</em><br>escalfad<em>or</em>, parad<em>or</em>, pescad<em>or</em><br>cant<em>or</em>, pint<em>or</em>, correct<em>or</em><br>impress<em>or</em>, marmess<em>or</em>, profess<em>or</em></td><td colspan=\"3\" rowspan=\"1\"></td></tr></tbody></table></div></section>","topicNumber":"12"},{"id":"book-o13","title":"L/L·L/LL","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"53–54","exercises":[{"id":"book-o13-ex1","number":"O13.1","title":"Escriviu la paraula contrària dels adjectius següents.","type":"open","bodyHtml":"<p>legal: lícit: lògic:<br>limitat: legítim: les:</p>","sourcePage":54,"pdfPage":51,"solutionHtml":"<p>il·legal il·lícit il·lògic<br>il·limitat il·legítim il·lès</p>","book":true,"prompt":"","explanation":""},{"id":"book-o13-ex2","number":"O13.2","title":"Completeu aquests infinitius amb l o l·l i escriviu-ne un substantiu derivat.","type":"open","bodyHtml":"<p>ape__ar: ce__ebrar: e__aborar:<br>co__ocar: cance__ar: anu__ar:<br>a__ucinar: e__iminar: osci__ar:<br>co__idir: insta__ar: po__uir:</p>","sourcePage":54,"pdfPage":51,"solutionHtml":"<p>ape<strong>l·l</strong>ar: apel·lació ce<strong>l</strong>ebrar: celebració e<strong>l</strong>aborar: elaboració<br>co<strong>l·l</strong>ocar: col·locació cance<strong>l·l</strong>ar: cancel·lació anu<strong>l·l</strong>ar: anul·lació<br>a<strong>l·l</strong>ucinar: al·lucinació e<strong>l</strong>iminar: eliminatòria/eliminació osci<strong>l·l</strong>ar: oscil·lació<br>co<strong>l·l</strong>idir: col·lisió insta<strong>l·l</strong>ar: instal·lador/instal·lació po<strong>l·l</strong>uir: pol·lució</p>","book":true,"prompt":"","explanation":""},{"id":"book-o13-ex3","number":"O13.3","title":"Elimineu d’aquesta graella els mots que contenen un error ortogràfic.","type":"open","bodyHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>satèl·lit</u></td><td colspan=\"1\" rowspan=\"1\"><u>gorila</u></td><td colspan=\"1\" rowspan=\"1\"><u>clientela</u></td><td colspan=\"1\" rowspan=\"1\"><u>colega</u></td><td colspan=\"1\" rowspan=\"1\"><u>mil·lèsim</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>til·la</u></td><td colspan=\"1\" rowspan=\"1\"><u>tranquil·litat</u></td><td colspan=\"1\" rowspan=\"1\"><u>pàl·lid</u></td><td colspan=\"1\" rowspan=\"1\"><u>cercavila</u></td><td colspan=\"1\" rowspan=\"1\"><u>milió</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>idili</u></td><td colspan=\"1\" rowspan=\"1\"><u>apilar</u></td><td colspan=\"1\" rowspan=\"1\"><u>rebelió</u></td><td colspan=\"1\" rowspan=\"1\"><u>metàl·lic</u></td><td colspan=\"1\" rowspan=\"1\"><u>del·legat</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>síl·laba</u></td><td colspan=\"1\" rowspan=\"1\"><u>passarel·la</u></td><td colspan=\"1\" rowspan=\"1\"><u>al·lèrgia</u></td><td colspan=\"1\" rowspan=\"1\"><u>miler</u></td><td colspan=\"1\" rowspan=\"1\"><u>ilusió</u></td></tr></tbody></table></div>","sourcePage":54,"pdfPage":51,"solutionHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><u>satèl·lit</u></td><td colspan=\"1\" rowspan=\"1\"><u>gorila</u></td><td colspan=\"1\" rowspan=\"1\"><u>clientela</u></td><td colspan=\"1\" rowspan=\"1\"><u>colega</u></td><td colspan=\"1\" rowspan=\"1\"><u>mil·lèsim</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>til·la</u></td><td colspan=\"1\" rowspan=\"1\"><u>tranquil·litat</u></td><td colspan=\"1\" rowspan=\"1\"><u>pàl·lid</u></td><td colspan=\"1\" rowspan=\"1\"><u>cercavila</u></td><td colspan=\"1\" rowspan=\"1\"><u>milió</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>idili</u></td><td colspan=\"1\" rowspan=\"1\"><u>apilar</u></td><td colspan=\"1\" rowspan=\"1\"><u>rebelió</u></td><td colspan=\"1\" rowspan=\"1\"><u>metàl·lic</u></td><td colspan=\"1\" rowspan=\"1\"><u>del·legat</u></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><u>síl·laba</u></td><td colspan=\"1\" rowspan=\"1\"><u>passarel·la</u></td><td colspan=\"1\" rowspan=\"1\"><u>al·lèrgia</u></td><td colspan=\"1\" rowspan=\"1\"><u>miler</u></td><td colspan=\"1\" rowspan=\"1\"><u>ilusió</u></td></tr></tbody></table></div>","book":true,"prompt":"","explanation":""},{"id":"book-o13-ex4","number":"O13.4","title":"Completeu les paraules següents amb l, l·l o ll i torneu-les a escriure a la columna corresponent.","type":"open","bodyHtml":"<p>nove__a, sentine__a, motxi__a, exce__ent, pe__ícula, tras__adar, nu__itat, __eganya, parce__a,<br>cèdu__a, a__egria, so__ució, __enya, ce__ebrar, se__ecció, so__itud, porce__ana, inte__igència</p><p><u><em>l</em></u> <u><em>l</em><em>·</em><em>l</em></u> <u><em>l</em><em>l</em></u></p>","sourcePage":54,"pdfPage":51,"solutionHtml":"<p><em>l</em>: cèdu<strong>l</strong>a, a<strong>l</strong>egria, so<strong>l</strong>ució, ce<strong>l</strong>ebrar, se<strong>l</strong>ecció, so<strong>l</strong>itud<br><em>l·l</em>: nove<strong>l·l</strong>a, exce<strong>l·l</strong>ent, pe<strong>l·l</strong>ícula, nu<strong>l·l</strong>itat, parce<strong>l·l</strong>a, inte<strong>l·l</strong>igència<br><em>ll</em>: sentine<strong>ll</strong>a, motxi<strong>ll</strong>a, tras<strong>ll</strong>adar, <strong>ll</strong>eganya, <strong>ll</strong>enya, porce<strong>ll</strong>ana</p>","book":true,"prompt":"","explanation":""},{"id":"book-o13-ex5","number":"O13.5","title":"Completeu els buits dels fets d’aquesta sentència amb l, l·l o ll.","type":"open","bodyHtml":"<p><em>Primer</em>. El 27 de febrer de 2006 el de__egat del Govern de la Genera__itat a Barcelona va<br>imposar a Carmen Costa Giménez una sanció que consistia en una multa de 300,50 euros perquè,<br>com a titu__ar del vehicle, no va identificar el conductor responsable de la infracció en el<br>termini establert, malgrat que van requerir-li que ho fes.<br><em>Segon</em>. El 8 de maig de 2006 el Servei Cata__à de Trànsit va dictar una reso__ució en què va<br>desestimar el recurs d’alçada que la part actora hi havia formu__at.<br><em>Tercer</em>. La part actora hi ha interposat un recurs contenciós administratiu perquè s’anu__i la<br>reso__ució i perquè es deixi sense efecte la sanció, ja que a__ega que durant la tramitació de<br>l’expedient sancionador se li ha causat indefensió, atès que no es va intentar fer la notificació<br>personal per mitjà de la di__igència oportuna.</p><p>Departament de Justícia, <em>Curs</em> <em>de</em> <em>llenguatge</em> <em>jurídic</em> (2a edició)</p>","sourcePage":54,"pdfPage":51,"solutionHtml":"","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 53–54 · <a href=\"assets/llibre-b2-ortografia.pdf#page=50\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>L/L·L/LL</h3><p>En català hi ha força mots que porten ela geminada, és a dir, que tenen repetit el so de la ela. La pronúncia,<br>però, no marca clarament aquest so, la qual cosa provoca problemes ortogràfics. A més, el fet que una<br>paraula dugui ela geminada no està lligat a cap regla específica, sinó que depèn de la seva etimologia, és a<br>dir, de la paraula de la qual prové.</p><p>S’escriuen amb ela geminada, entre d’altres, els mots següents i els seus derivats:</p><p><em>a</em>) Els mots començats per:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>a</em><em>l</em><em>·</em><em>l</em><em>-</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"4\">a<em>l·l</em>egar, a<em>l·l</em>eluia, a<em>l·l</em>èrgia, a<em>l·l</em>icient, a<em>l·l</em>ucinar<br>co<em>l·l</em>aborar, co<em>l·l</em>ocar, co<em>l·l</em>apse, co<em>l·l</em>ectiu, co<em>l·l</em>ega, co<em>l·l</em>egi, co<em>l·l</em>isió, co<em>l·l</em>ocar, co<em>l·l</em>oqui<br>i<em>l·l</em>egal, i<em>l·l</em>egible, i<em>l·l</em>ès, i<em>l·l</em>ícit, i<em>l·l</em>imitat, i<em>l·l</em>ògic, i<em>l·l</em>uminar, i<em>l·l</em>usió, i<em>l·l</em>ustrar<br>mi<em>l·l</em>enari, mi<em>l·l</em>enni, mi<em>l·l</em>èsim, mi<em>l·l</em>igram, mi<em>l·l</em>ímetre</td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>c</em><em>o</em><em>l</em><em>·</em><em>l</em><em>-</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>i</em><em>l</em><em>·</em><em>l</em><em>-</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>m</em><em>i</em><em>l</em><em>·</em><em>l</em><em>-</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div><p><em>b</em>) Els mots acabats en:</p><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>-</em><em>e</em><em>l</em><em>·</em><em>l</em><em>a</em></u></td><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"4\">aquare<em>l·l</em>a, ce<em>l·l</em>a, frane<em>l·l</em>a, mortade<em>l·l</em>a, nove<em>l·l</em>a, ombre<em>l·l</em>a, parce<em>l·l</em>a, passare<em>l·l</em>a<br>ape<em>l·l</em>ar, cance<em>l·l</em>ar, interpe<em>l·l</em>ar<br>axi<em>l·l</em>a, gori<em>l·l</em>a, pupi<em>l·l</em>a, ti<em>l·l</em>a, tranqui<em>l·l</em>a<br>capi<em>l·l</em>ar, desti<em>l·l</em>ar, osci<em>l·l</em>ar, vaci<em>l·l</em>ar</td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>-</em><em>e</em><em>l</em><em>·</em><em>l</em><em>a</em><em>r</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>-</em><em>i</em><em>l</em><em>·</em><em>l</em><em>a</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr><tr><td colspan=\"1\" rowspan=\"1\"></td><td colspan=\"1\" rowspan=\"1\"><u><em>-</em><em>i</em><em>l</em><em>·</em><em>l</em><em>a</em><em>r</em></u></td><td colspan=\"1\" rowspan=\"1\"></td></tr></tbody></table></div><p><em>c</em>) Aquests mots:</p><p>bèl·lic excel·lent intel·ligent pàl·lid putxinel·li<br>Brussel·les expel·lir medul·la paral·lel rebel·lió<br>cal·ligrafia idil·li metàl·lic pel·lícula satèl·lit<br>cèl·lula instal·lar nul·la pol·len síl·laba<br>constel·lació intel·lectual pal·liar pol·luir sol·licitar</p><p><em>Remarques</em></p><p><em>a</em>) Aquestes paraules no duen ela geminada:</p><p>celebrar, alegria, elaborar, lila, miler, milió, revelar, selecció, solució, eliminar</p><p><em>b</em>) Cal pronunciar i escriure bé les paraules següents:</p><p>traslladar, motxilla, rellotge, lingüístic, lleganya, lògic, porcellana</p></section>","topicNumber":"13"},{"id":"book-o14","title":"H","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"55–56","exercises":[{"id":"book-o14-ex1","number":"O14.1","title":"Completeu amb h aquestes paraules, si cal.","type":"open","bodyHtml":"<p>__ostatge ad__erir a__ir sub__asta Est__er<br>co__et __armonia ales__ores Montblanc__ caca__uet<br>__ivern al__ora __eterosexual __orfe in__ibir<br>__orxata __issar __imne __idrofòbia fil__armònica</p>","sourcePage":56,"pdfPage":53,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o14-ex2","number":"O14.2","title":"Completeu les frases següents.","type":"open","bodyHtml":"<div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><em>s’hi</em><br><em>si</em><br><em>sí</em></td><td colspan=\"1\" rowspan=\"1\">Digues al Blai que __________ que anirem a veure’l, però només<br>__________ no __________ oposa ningú. A més, __________ la seva mare<br>__________ avé, potser es pot afegir a la visita la Quima, __________ té<br>temps i diu que __________, és clar.</td></tr></tbody></table></div><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><em>ho</em><br><em>o</em></td><td colspan=\"1\" rowspan=\"1\">Digues! El testimoni __________ va declarar durant el judici __________<br>en la vista prèvia? No __________ saps __________ bé no ens __________<br>vols dir?</td></tr></tbody></table></div><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><em>hem</em><br><em>em</em></td><td colspan=\"1\" rowspan=\"1\">__________ penso que per assolir un bon resultat __________ de canviar<br>d’estratègia, però no __________ veig amb cor de fer res més que el que<br>__________ pactat.</td></tr></tbody></table></div><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><em>ha</em><br><em>a</em></td><td colspan=\"1\" rowspan=\"1\">El judici __________ començat __________ l’hora assenyalada, per la<br>qual cosa la magistrada __________ previst que acabi cap __________ la<br>una del migdia.</td></tr></tbody></table></div><div class=\"table-wrap\"><table class=\"book-table\"><tbody><tr><td colspan=\"1\" rowspan=\"1\"><em>hi</em><br><em>i</em></td><td colspan=\"1\" rowspan=\"1\">S’ha decidit que al centre __________ a les instal·lacions annexes els<br>alumnes majors d’edat __________ entrin sense necessitar cap permís.<br>No obstant això, encara __________ ha la norma per la qual la directora<br>ha d’autoritzar les entrades __________ les sortides del centre<br>__________ ha de vetllar pel compliment de l’horari.</td></tr></tbody></table></div>","sourcePage":56,"pdfPage":53,"solutionHtml":"","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 55–56 · <a href=\"assets/llibre-b2-ortografia.pdf#page=52\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory book-content\"><h2>Teoria</h2><h3>H</h3><p>La lletra hac, que es conserva per raons etimològiques, no representa avui cap so, llevat d’alguns casos<br>d’onomatopeia, és a dir, d’imitació de sons (<em>ha</em>, <em>ha</em>, <em>ha!</em>, <em>ehem!</em>...), o de paraules manllevades d’altres<br>llengües que no han estat catalanitzades (<em>hippy</em>, <em>hall</em>...). Per tant, convé recordar les paraules que porten<br>hac i també fixar-se en les discrepàncies que hi ha respecte a altres llengües.</p><p>Escrivim amb hac:</p><p>ham hemorràgia heterosexual hissar homogeni<br>harmonia herba higiene hivern hoquei<br>hemisferi hereu hipòtesi homicida humitat</p><p>També escrivim amb hac, en aquest cas intercalada, les paraules següents:</p><p>adherir alhora cohibir inherent subhasta<br>ahir cohesió exhaurir inhibició tothom</p><p>En canvi, s’escriuen sense hac paraules com ara:</p><p>Boí Ester Maó Munic ostatge<br>cacauet exuberant Montblanc orfe truà<br>coet Judit Montjuïc orxata Vic</p><p><em>Remarca</em></p><p>Segons la posició de la <em>h</em>, o si el mot en porta o no, convé distingir bé entre:</p><p><em>ha</em> (verb haver): Ja ha acabat. <em>ho</em> (pronom feble): Falta redactar-ho.<br><em>ah!</em> (interjecció): Ah! Ja m’ho pensava. <em>oh!</em> (interjecció): Oh! Quina sorpresa!<br><em>a</em> (preposició): Aniré a fer un volt. <em>o</em> (conjunció): Per escrit o de paraula?</p><p><em>hem</em> (verb haver): Hem viatjat a l’Àfrica. <em>hi</em> (pronom feble): Hi aniré demà, al Jutjat.<br><em>em</em> (pronom feble): Em dic Manel. <em>i</em> (conjunció): Treballa a Vic i Olot.</p><p><em>s’hi</em> (combinació pronominal): S’hi fan molts <em>eh!</em> (interjecció): Eh! Escolta’m!<br>judicis, en aquesta sala! <em>he</em> (verb haver): Els he comunicat la notícia.<br><em>si</em> (conjunció): Si plou, no us mogueu d’aquí.<br><em>sí</em> (adverbi): Diu que sí a totes les propostes. <em>hom</em> (pronom): Hom creu que és cert.<br><em>om</em> (arbre): L’om s’ha assecat.</p></section>","topicNumber":"14"},{"id":"book-o15","title":"Exercicis de repàs","area":"Ortografia · Llibre B2","section":"ortografia","book":true,"sourcePages":"57–62","exercises":[{"id":"book-o15-ex1","number":"O15.1","title":"Separeu les paraules següents en síl·labes i assenyaleu-ne la síl·laba tònica.","type":"open","bodyHtml":"<p>bressol: grua:<br>gripau: platja:<br>feia: pingüins:<br>missioner: aixella:<br>guardiola: ioga:<br>rossinyol: inquietud:<br>equivocació: il·luminació:<br>immensitat: lloança:</p>","sourcePage":57,"pdfPage":54,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex2","number":"O15.2","title":"Completeu els espais buits d’aquest text amb a/e segons correspongui.","type":"open","bodyHtml":"<p>El pastís li va quedar molt tou i saborós, així que tots els funcionaris que treballav__n a l’oficina<br>van anar tr__ient les cos__s de sobre de les taul__s per menjar-se’l més còmod__ment. La<br>respl__ndor que els arribava provinent de la sala enorm__ que hi havia al costat permeti__ que<br>mantinguessin el llum apagat, però ni tan sols la p__sada Cat__rina va protestar per això: aquell<br>no era moment de mal__nconies ni __nyorances, sinó que calia oblidar totes les diferènci__s<br>que durant massa temps els havien dividit. Quan va aparèixer la jov__ __mbaixadora, acabada<br>de nomenar, tothom va aplaudir sense cap mena de r__ncor. De sobt__, però, una ràf__ga de<br>trets ho va interrompr__ tot.</p>","sourcePage":57,"pdfPage":54,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex3","number":"O15.3","title":"Completeu els espais buits d’aquest text amb o/u segons correspongui.","type":"open","bodyHtml":"<p>Durant la meva plàcida j__ventut vaig viure a la casa que els pares tenien a la m__ntanya. Hi<br>havia alguns conre__s de tar__ngers i p__meres i aquelles taronges i pomes tan bones<br>compensaven alguna inc__moditat com era l’habitual retard del corre__ i la manca<br>d’autobus__s de línia. La meva mare feia de m__dista a Viladrau i mon pare treballava als<br>bosc__s de la zona, fent de carb__ner. No v__líem ni sentir a parlar d’un hip__tètic trasllat al<br>poble, malgrat que sovint ens visitava l’alcalde, un home de ve__ greu i __lleres gr__ixudes,<br>amb l’oferta de treballar als despatx__s municipals, una canç__neta que ja ens res__ltava<br>familiar i que reb__tjàvem com p__díem.</p>","sourcePage":57,"pdfPage":54,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex4","number":"O15.4","title":"Ompliu els buits amb a/e/o/u segons calgui.","type":"open","bodyHtml":"<p>Aquest és un altr__ avantatg__ que podem atribuir a les màquin__s: no ten__n escrúp__ls, ni<br>__nyorança ni r__ncor, ni han de s__portar altr__s sentiments tan humans com aquests. Per<br>contra, és cert que poden patir av__ries, poden tenir vir__s o es poden perdre pels llargs ri__s<br>i les immens__s m__ntanyes d’informació que actualment s__rgeixen de tot arre__. Fins on<br>podran arribar aquests ginys? Represent__n aquella m__ravella respl__ndent, aquell nou<br>capít__l de la història que ens van vendr__ o encara no ens apartem gair__ de la tradició escrita<br>que van mantenir els monj__s als mon__stirs fa mil anys o la que van difondr__ oralment els<br>j__glars? El futur més imminent potser no es presenta tan negr__ ni av__rrit com pensàv__m.</p>","sourcePage":57,"pdfPage":54,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex5","number":"O15.5","title":"Escriviu aquestes paraules a la columna corresponent.","type":"open","bodyHtml":"<p>greu, lleig, txec, fems, llest, text, tres, rec, test, greix, xec, fet, ser, preu, cec</p><p><u><em>e</em></u> <u>oberta</u> <u><em>e</em></u> <u>tancada</u></p>","sourcePage":58,"pdfPage":55,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex6","number":"O15.6","title":"Escriviu aquestes paraules a la columna corresponent.","type":"open","bodyHtml":"<p>tros, Pol, lloc, porc, tronc, poc, llot, boig, pot, bo, boix, cop, fort, or, poll, gros</p><p><u><em>o</em></u> <u>oberta</u> <u><em>o</em></u> <u>tancada</u></p>","sourcePage":58,"pdfPage":55,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex7","number":"O15.7","title":"Accentueu les paraules que calgui del text següent.","type":"open","bodyHtml":"<p>Els patrons de bellesa son ben volatils. Anys enrere, els cossos turgents plens de corbes es<br>preferien a les figures pal·lides i languides tan de moda avui dia. La insatisfaccio amb el propi<br>cos en plena adolescencia es una bomba de rellotgeria i un element clau per entendre<br>l’augment dels trastorns en el comportament alimentari. A la voluntat de perdre grans<br>quantitats de pes amb dietes estrictes s’afegeix l’obsessio per l’exercici, l’autoestima baixa,<br>un caracter perfeccionista, inseguretat i aïllament social i familiar i especialment la incapacitat<br>d’acceptar la malaltia. Recentment s’ha presentat una proposicio no de llei sobre l’elaboracio<br>d’un pla global per prevenir i evitar l’anorexia i la bulimia, que preten restringir la venda de<br>laxants i diüretics a menors a les farmacies i homogeneïtzar les talles de la roba, entre d’altres.</p><p><em>El</em> <em>Temps</em>, 20 de juny de 2006 (text adaptat)</p>","sourcePage":58,"pdfPage":55,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex8","number":"O15.8","title":"Completeu aquest text amb els accents que hi falten.","type":"open","bodyHtml":"<p>Abraham va insistir que era ell qui havia convidat i qui havia de pagar els plats trencats, pero<br>Quim es posa greu i hieratic amb l’argument que potser no es tornarien a veure mai mes i que<br>ell era avui el seu hoste i el volia rebre i fer els honors que l’hospitalitat mediterrania exigeix.<br>Paga el compte i sortiren al port. Era ja mes de la una i encara hi havia una gran animacio. La<br>vida nocturna feia les delicies de <em>Martin</em>. Decidiren caminar seguint la vora de la mar fins a<br>Colom. <em>Martin</em> els explica la seva vida rutinaria de burocrata a Zuric amb un cert detall, el<br>cansament que arriba a produir-li, el fastic vital que tot plegat li feia avinent el tenia anorreat.</p><p>Joaquim Pijoan, <em>Sayonara</em> <em>Barcelona</em> (text adaptat)</p>","sourcePage":58,"pdfPage":55,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex9","number":"O15.9","title":"Poseu els accents que falten en el text següent.","type":"open","bodyHtml":"<p>En Jordi esta ben convençut que nomes vosaltres fareu tirar endavant les empreses en un mon<br>globalitzat i sotmes continuament a turbulencies financeres, laborals, personals en el si d’un<br>ocea de “competitivitat” molt gran. Tambe manifesta un cert grau de pessimisme quan pensa<br>i, ho diu amb sordina, que construir per durar es cada cop mes una idea romantica i que,<br>malgrat el voluntarisme que hi posem, les empreses i les organitzacions, dels tipus que siguin,<br>cada vegada tindran una vida mes efimera i que els moments mes dolços seran fugissers tambe<br>per als liders, els artistes, els veins, les parelles i que continuament haurem de reconfigurar i<br>reinventar des dels llocs de treball fins a la nostra vida col·lectiva, passant per les questions<br>de la propia “sostenibilitat” de les persones.</p><p>Sebastià Serrano, <em>La</em> <em>festa</em> <em>dels</em> <em>sentits</em> (text adaptat)</p>","sourcePage":59,"pdfPage":56,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex10","number":"O15.10","title":"Poseu els accents i les dièresis que calguin en el text següent.","type":"open","bodyHtml":"<p>Deixar de menjar carn, per que no? Poques persones vegetarianes tenen els problemes de<br>colesterol i d’obesitat que causen tantes morts prematures als paisos occidentals. Pero, abans<br>de fer-se vegetaria, conve saber que la carn es una de les principals fonts de proteines a la<br>nostra dieta i que les proteines son els maons amb que esta construit el cos huma. Els ossos,<br>els musculs, els ulls, la pell, tots els nostres organs estan fets amb proteines. I, com que els<br>cos huma esta sempre en obres, perque cada dia moren milions de cel·lules que han de ser<br>substituides, cada dia necessitem noves proteines per regenerar-nos.</p><p>Valentí Fuster, <em>La</em> <em>ciència</em> <em>de</em> <em>la</em> <em>salut</em> (text adaptat)</p>","sourcePage":59,"pdfPage":56,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex11","number":"O15.11","title":"Poseu els accents i les dièresis que falten en el text següent.","type":"open","bodyHtml":"<p>Nomes en Salvador <em>Sense</em> <em>Germana</em>, tan donat a inventar histories, podia ser qui, assenyalant-<br>me’l, em fes veure la contradiccio estranya i misteriosa entre aquell carrer tan petit i<br>insignificant, tan brut i fosc, sense sortida, i la importancia i grandiositat del nom que portava.<br>Allo no era normal, em deia, havia de respondre a un enigma que, tard o d’hora, acabariem<br>per descobrir. El cap del mon podia ser la fi del mon. I m’introduia en tenebroses histories<br>d’espies, de negocis il·legals, de perdularis i assassins (o de perdularis assassins) que tenien<br>l’origen i el final en el fabulos carrer del Cap del Mon.</p><p>Lluís-Anton Baulenas, <em>Per</em> <em>un</em> <em>sac</em> <em>d’ossos</em> (text adaptat)</p>","sourcePage":59,"pdfPage":56,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex12","number":"O15.12","title":"Poseu els accents i les dièresis que falten en el text següent.","type":"open","bodyHtml":"<p>Nizzi era una dona de pell molt blanca, de cabells negres i ulls tirant a morats. Portava un<br>vestit de vellut carmesi amb un escot magnific, damunt el qual, penjat d’una cadena d’or, lluia<br>un topazi extraordinari. Era una coqueta espontania com una gata, que posseia la provocacio<br>de la model professional i la distincio d’una prostituta magnificament educada que dispensava<br>el seu ofici amb superbia i una fermesa suau. Era intel·ligent, riallera, sabia parlar dolçament,<br>muntava a la perfeccio i conduia ella mateixa l’automobil, bevia whisky i fumava tabac oriental.</p><p>Nèstor Luján, <em>A</em> <em>Mayerlin,</em> <em>una</em> <em>nit...</em> (text adaptat)</p>","sourcePage":59,"pdfPage":56,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex13","number":"O15.13","title":"Poseu accent o dièresi a les paraules que calgui del text següent.","type":"open","bodyHtml":"<p>Te el coratge de qui ha estat abandonat a la deriva i al panic cosmic del mar salat, la set i la<br>mort, i, tot i aixo, es lliura a la providencia. Aixi que ho pensa, enveja aquesta confiança absoluta<br>que empeny a sobreviure. Es un impuls diferent del desig d’abandonar una terra desposseida que<br>no ofereix cap possibilitat de progres, que fa emigrar fugint del caos, les dictadures, la guerra,<br>les sequeles colonials, les injusticies socials, la pobresa. En el viatge de l’Aisha i la Fatima hi ha<br>una recerca d’obertura que s’assembla al miratge dels joves que contemplen la promesa<br>perversa del mar: paisos que es declaren germans, anuncien una vida ideal i ofereixen la materia<br>densa de les onades. La migracio, la recerca dels origens, l’exili forços se succeeixen en la<br>memoria dels naufrags que recorren tots els mars del mon.</p><p>Núria Esponellà, <em>La</em> <em>travessia</em> (text adaptat)</p>","sourcePage":60,"pdfPage":57,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex14","number":"O15.14","title":"Poseu els accents i les dièresis adients en el text següent.","type":"open","bodyHtml":"<p>Els plens son l’espectacle mes gran de la Patum; el seu moment culminant; l’apoteosi de la festa.<br>Els plens, que antigament havien format un sol quadre amb les maces i que deuen el seu nom al<br>fet que van plens de foc, estan documentats des del 1628. Quan s’apaguen els llums, comença<br>la musica i la plaça esdeve un infern que s’omple de foc amb mil fuets cremant alhora. Els plens<br>evolucionaven unicament al so del tabal fins a final del segle XIX, quan en Quim Serra va<br>compondre la musica genial i enardidora amb que salten actualment.<br>L’any 1756 l’Ajuntament de Berga va decidir incorporar una aliga a les solemnitats del Corpus<br>Christi, que fou construida pel fuster Ramon Roca i que es la mateixa que figura actualment a la<br>Patum. El seu ball es el de major valor coreografic de tota la representacio, i la seva musica la<br>mes distingida i monumental. Aquesta extraordinaria partitura presenta moltes semblances amb<br>una dansa tipica del Renaixement, que podria tenir el seu origen al segle XVI, tot i que la seva<br>linia melodica sembla que deriva d’un himne gregoria.</p><p>&lt;www.museu.lapatum.cat&gt; (text adaptat)</p>","sourcePage":60,"pdfPage":57,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex15","number":"O15.15","title":"Poseu els accents i les dièresis que falten en el text següent.","type":"open","bodyHtml":"<p>Els que aspirin a realitzar les proves selectives per a l’ingres al notariat han de complir, en la<br>data en que acabi el termini de presentacio de les instancies, les condicions seguents:<br>1. Ser espanyol o tenir la nacionalitat de qualsevol pais membre de la Unio Europea.<br>2. Ser major d’edat.<br>3. No estar compres en cap dels casos que incapaciten o impossibiliten per exercir el carrec de<br>notari.<br>4. Ser doctor o llicenciat en dret o haver conclos els estudis d’aquesta llicenciatura.<br>Si el titol procedis d’un estat membre de la Unio Europea, s’ha de presentar el certificat<br>acreditatiu del reconeixement o l’homologacio del titol equivalent, de conformitat amb la<br>Directiva 89/48, de 21 de desembre de 1988, el Reial decret 1665/1991, de 24 d’octubre, i altres<br>normes de transposicio i desplegament.</p><p>Article 10 de la Llei del notariat (fragment)</p>","sourcePage":60,"pdfPage":57,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex16","number":"O15.16","title":"Completeu el text següent amb les lletres adients.","type":"open","bodyHtml":"<p>Després de les sardanes hi va ha__er jocs infantils i la seva germana i la meva van pro__ar<br>d’af__itar glob__s i se’ls van re__entar de seguida. Van fer carreres de sacs i var__n tr__ncar<br>l’olla i sembla__a que s’ho passa__en molt bé; els vam mirar una est__neta i després v__m<br>agafar les bicicletes i v__m anar a l’estació a veur__ passar trens. Està__em contents. A la nit<br>hi ha__ia ball, em va dir que ballaríem junts i el cor se’m va eix__mplar. El ball comença<br>sempr__ tardíssim, quan els músics ja han s__pat i ress__pat i em recordo que esta__a tot<br>neguitós perquè l’hora no aca__a__a d’arri__ar mai.</p><p>Maria Mercè Roca, <em>Com</em> <em>un</em> <em>miratge</em> (text adaptat)</p>","sourcePage":61,"pdfPage":58,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex17","number":"O15.17","title":"Ompliu, si cal, els buits amb les grafies corresponents.","type":"open","bodyHtml":"<p>De__ia ca__tar que el que deia no em feia ni fre__ ni calor perquè va continuar garlan__ amb<br>aquell seu aire fanfàrria. A__ans que es p__sés a la boca la paraula sida, abaixan__ la veu,<br>estona feia que jo ha__ia end__vinat la causa de l’ava__uació del Joel de qui parla__a. Sentia<br>fàsti__ que mercad__gés amb les notícies i potser també se’m desperta__a la por, el cas és que<br>li vaig e__zibar als morros un rene__ verinós amb la intenció de deixar-lo mu__. Potser vaig<br>confegir una ganyota, però no ho cre__ pas.</p><p>Maria Barbal, <em>Escrivia</em> <em>cartes</em> <em>al</em> <em>cel</em> (text adaptat)</p>","sourcePage":61,"pdfPage":58,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex18","number":"O15.18","title":"Ompliu els buits amb les grafies corresponents.","type":"open","bodyHtml":"<p>T’escriu una amiga, arquitect__ i mare de tres fills. Es queixa que les dones amb profe__ions<br>__ualificades només tenen dues opcions: o renuncien a la maternita__, o tenen fills però ho<br>di__imulen. No estaria __en vist que plegue__in a l’hora en punt per anar a rec__llir els nens a<br>l’escola, ni que s’escape__in de la feina __uan se’ls po__a un nen malalt, ni que fe__in cara de<br>pomes agres __uan les convo__en a una reunió a les vuit del ve__pre.<br>La tercera opció pa__a per conformar-se, ni que si__i de forma provi__ional, amb una feina de<br>menys __ualificació. En aquest cas ja es pot entendre que hagis de portar el fill al pediatr__,<br>que t’acullis al dret de reducció de jornada i que expo__is fotos dels nens al lloc on tr__balles.</p><p>Eva Piquer, <em>La</em> <em>feina</em> <em>o</em> <em>la</em> <em>vida</em> (text adaptat)</p>","sourcePage":61,"pdfPage":58,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex19","number":"O15.19","title":"Ompliu els buits amb les grafies corresponents.","type":"open","bodyHtml":"<p>La nosa d’una verita__ terrible li peta al cer__ell de manera fulminant: la Martina ha canviat<br>el número del seu telèfon mò__il. Can__ada de la persecu__ió insistent, ho recone__, a què<br>l’ha sotme__a darrer__ment, primer ba__ant a Barcelona i escom__tent-la a l’entrada o a la<br>s__rtida del pis, vorera amunt o vorera a__all del seu carrer, a la piscina que freqüenta els<br>esti__s o a casa de la Dèlia, on s’ha__ia refu__iat expre__ament perquè no la tro__és a casa<br>seva, i després, d’una setmana ençà, trucant-li i enviant-li corre__s matí, tard__ i vespr__,<br>com un veritable corcó, de Can Montalà estant amb el pre__, sempre el mateix pre__, de<br>tornar-ho a pro__ar i esperar a veure què pa__a.</p><p>Antoni Pladevall, <em>La</em> <em>papallona</em> <em>negra</em> (text adaptat)</p>","sourcePage":61,"pdfPage":58,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex20","number":"O15.20","title":"Ompliu els buits amb les grafies corresponents.","type":"open","bodyHtml":"<p>En David ja no tenia cap dubt__. Quan la Ge__a vingués a sopar a casa seva li prepararia aquell<br>plat fet amb àne__ i b__tifarra amb __eba que havia après a cuinar quan encara era un __icot<br>jove i i__madur que vivia sense maldecaps. Era feli__ i se li notava a la cara, a la mirada, a<br>tots els por__s de la pell. La perspectiva del sopar i__minent va s__posar-li tota una in__ecció<br>de moral, quan ja estava a punt d’e__bogir.<br>Pa__aven quin__e minuts justos de l’hora establerta quan va arri__ar. Estava g__lada i<br>sorprenentment va dir-li que volia cerve__a, que tenia molta se__. Tot seguit, es va po__ar un<br>d__vantal i es va esmu__ir cap a la cuina. Va demanar-li a quin cala__ tenia els ganivets; de<br>sobte, el so agu__ d’un mò__il va crear un moment de co__fusió.</p>","sourcePage":62,"pdfPage":59,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex21","number":"O15.21","title":"Ompliu els buits del text següent amb les grafies que hi falten.","type":"open","bodyHtml":"<p>Aquell vespr__ en Pere no va tenir gens de sor__: va estar-se ma__a estona esperant que piqués<br>algun pe__ i tot va resultar debades, ja que va aca__ar cansat i __op per la rosada, i amb el<br>cov__ buit. Feia fred i a__ans de tornar cap a casa va pensar que li aniria bé prendre una bona<br>ta__a de xocolata desfeta.<br>Amb aquesta intenció va pa__ar a veure el seu bon amic Quimet, el f__rner, que encara de__ia<br>estar treballant. El coneixia de l’escola, de feia un munt d’anys, quan junts van s__portar<br>aquell mestr__ que pretenia que recorde__in llistes interminables de reis i__mortals amb noms<br>estra__bòtics. Ara eren dos homes fets i drets que mantenien una amista__ molt estreta i que<br>encara compartien for__a estones quan la feina els ho permetia. Va tr__car a la porta lateral<br>de la botiga i de seguida va aparèixer el seu amic, que el va convidar a entrar. La seva dona<br>havia s__rtit i tots dos sols podrien x__rrar amb tranqui__itat d’allò que els vingués de gust:<br>una d’aquelles llargues i ma__estuoses converses sobre els temes importants de la vida.</p>","sourcePage":62,"pdfPage":59,"solutionHtml":"","book":true,"prompt":"","explanation":""},{"id":"book-o15-ex22","number":"O15.22","title":"Poseu els accents i les dièresis que falten en el text següent.","type":"open","bodyHtml":"<p>Catalunya es terra d’arros per excel·lencia i, sens dubte, el primer lloc del ranquing productiu<br>l’ocupa el delta de l’Ebre, sobretot per quantitat de produccio i per extensio paisatgistica. Son<br>12.000 hectarees de superficie conreada amb 40.000 tones d’aquest cereal produides<br>anualment, que modela una zona unica i que ens acosta a la veina albufera de Valencia. Un<br>terreny increiblement pla en un pais muntanyos mes aigua abundant son sinonim de lloc<br>adequat per a aquest conreu.<br>Aquest fet no pot desmereixer una altra zona arrossera mes petita al cor de l’Emporda, amb<br>una produccio de nomes 900 tones anuals brutes, pero amb una tradicio arrossera de major<br>antiguitat, ja que es remunta al segle XV. No es perque si que Pals, en llati, vol dir “terreny<br>pantanos”, la qual cosa ja ens indica una zona arrossera en potencia des de temps reculats.</p>","sourcePage":62,"pdfPage":59,"solutionHtml":"","book":true,"prompt":"","explanation":""}],"theoryHtml":"<p class=\"muted book-source\">Llibre B2 · Ortografia · pàgines 57–62 · <a href=\"assets/llibre-b2-ortografia.pdf#page=54\" target=\"_blank\" rel=\"noopener\">Consultar el document original</a></p><section class=\"card theory\"><h2>Repàs d’ortografia</h2><p>Repassa les regles dels catorze temes anteriors abans de resoldre aquests exercicis.</p></section>","topicNumber":"15"},{"id":"book-morfosintaxi-1","title":"L’oració i les categories gramaticals","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"01","exercises":[]},{"id":"book-morfosintaxi-2","title":"Els determinants: articles, demostratius, possessius i interrogatius","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"02","exercises":[]},{"id":"book-morfosintaxi-3","title":"Els quantificadors: numerals, quantitatius i indefinits","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"03","exercises":[]},{"id":"book-morfosintaxi-4","title":"El substantiu i l’adjectiu: gènere","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"04","exercises":[]},{"id":"book-morfosintaxi-5","title":"El substantiu i l’adjectiu: nombre","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"05","exercises":[]},{"id":"book-morfosintaxi-6","title":"Els verbs regulars","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"06","exercises":[]},{"id":"book-morfosintaxi-7","title":"Els verbs irregulars i les perífrasis verbals","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"07","exercises":[]},{"id":"book-morfosintaxi-8","title":"Les funcions sintàctiques","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"08","exercises":[]},{"id":"book-morfosintaxi-9","title":"Els pronoms febles","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"09","exercises":[]},{"id":"book-morfosintaxi-10","title":"Els pronoms relatius","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"10","exercises":[]},{"id":"book-morfosintaxi-11","title":"Les preposicions","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"11","exercises":[]},{"id":"book-morfosintaxi-12","title":"Les conjuncions","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"12","exercises":[]},{"id":"book-morfosintaxi-13","title":"Els adverbis","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"13","exercises":[]},{"id":"book-morfosintaxi-14","title":"Exercicis de repàs","area":"Morfosintaxi","section":"morfosintaxi","book":true,"pending":true,"topicNumber":"14","exercises":[]},{"id":"book-lexic-1","title":"Exercicis de lèxic","area":"Lèxic","section":"lexic","book":true,"pending":true,"topicNumber":"01","exercises":[]},{"id":"book-lexic-2","title":"Les hores","area":"Lèxic","section":"lexic","book":true,"pending":true,"topicNumber":"02","exercises":[]},{"id":"book-lexic-3","title":"Les frases fetes","area":"Lèxic","section":"lexic","book":true,"pending":true,"topicNumber":"03","exercises":[]}];
